    account_id = fields.Many2one('account.account',string="Account Code", required=True)

    @api.model
    def get_view(self,view_id=None,view_type='form', **options):
        res = super(AccountCashflowExclude,self).get_view(view_id=view_id,view_type=view_type, **options)
        if view_type == 'form':
            res['arch'] = """
                <form string="Account Cashflow COA Exclude">
                    <sheet>
                        <group string="General">
                            <field name="company_id"/>
                            <field name="account_id" domain="[('company_id','=', company_id)]"/>
                        </group>
                        <notebook>
                            <page string="Technical">
                                <group>
                                    <group>
                                        <field name="sync_type"/>
                                        <field name="sync_consol_date" readonly="1" />
                                    </group>
                                    <group>
                                        <field name="sync_consol_id_main" readonly="1" />
                                        <field name="sync_consol_id_unit" readonly="1" />
                                    </group>
                                </group>
                            </page>
                        </notebook>
                    </sheet>
                </form>
                """
        if view_type == 'tree':
            res['arch'] = """
                <tree string="Cashflow COA Exclude">
                    <field name="company_id" />
                    <field name="account_id" />
                    <field name="sync_type" />
                </tree> 
            """
        from lxml import etree
        doc = etree.XML(res['arch'])
        View = self.env['ir.ui.view'].sudo()
        res['arch'], res['fields'] = View.postprocess_and_fields(doc, self._name, validate=True)
        return res


