    @api.onchange('sync_type', 'name','type_tax_use','amount_type','amount','description','analytic','active','price_include','include_base_amount','tax_adjustment','account_id','refund_account_id')
    def onchange_trigger_write(self):
        self.trigger_write = True


    @api.model
    def get_view(self,view_id=None, view_type='form', **options):
        res = super(AccountTax,self).get_view(view_id=view_id,view_type=view_type, **options)        
            
        View = self.env['ir.ui.view'].sudo()
        from lxml import etree
        if res.get('view_id'):
            view_id = res['view_id']
        if view_id:
            root_view = View.browse(view_id).read_combined(['arch'])
            res['arch'] = root_view['arch']
        doc = etree.XML(res['arch'])
        if view_type == 'form':
            doc = View.apply_inheritance_specs(doc,etree.XML("""
            <data>
                
                <xpath expr="//page[@name='advanced_options']" position="after">
                    <page string="Technical">
                        <group>
                            <group>
                                <field name="sync_type"/>
                                <field name="sync_consol_date"/>
                                <field name="trigger_create" invisible="1"/>
                                <field name="trigger_write" invisible="1"/>
                            </group>
                            <group>
                                <field name="sync_consol_id_main"/>
                                <field name="sync_consol_id_unit"/>
                            </group>
                        </group>
                    </page>
                </xpath>
            </data>
            """))
        if view_type == 'tree':
            doc = View.apply_inheritance_specs(doc,etree.XML("""
            <data>
                <xpath expr="//tree" position="attributes">
                    <attribute name="delete">0</attribute>
                </xpath>
                <xpath expr="//field[@name='company_id']" position="after">
                    <field name="sync_type"/>
                </xpath>
            </data>
            """))
        # from lxml import etree
        # doc = etree.XML(res['arch'])
        # View = self.env['ir.ui.view'].sudo()
        res['arch'], res['fields'] = View.postprocess_and_fields(doc, self._name, validate=True)
        return res






