class DepartmentCostReport(models.Model):
    _name = 'department.cost.report'

    sync_type = sync.type
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date

    name = fields.Char(string="Facility/Location")
    company_id = fields.Many2one('res.company', string="Company")
    id_location = fields.Integer(string="Location ID", readonly=True)
    analytic_id = fields.Many2one('account.analytic.account',string="Analytic Account",index=True)

    @api.model
    def _query_values(self):
        query = """
            INSERT INTO department_cost_report (
                company_id, sync_type, name, 
                id_location, create_date, create_uid,
                write_date, write_uid ) 
            (
                SELECT DISTINCT a.company_id, a.sync_type,
                    COALESCE(a.name,'NULL') nama, 
                    a.id id_location,
                    CURRENT_TIMESTAMP create_date, 1 create_uid,
                    CURRENT_TIMESTAMP write_date, 1 write_uid 
                FROM stock_location a 
                WHERE NOT EXISTS (
                    SELECT 1 FROM department_cost_report b 
                    WHERE b.company_id = a.company_id
                    AND b.name = COALESCE(a.name,'NULL') 
                ) AND a.company_id IS NOT NULL 
            )"""
        self.env.cr.execute(query)


    @api.model
    def get_view(self,view_id=None, view_type='form', **options):
        res = super(DepartmentCostReport,self).get_view(view_id=view_id,view_type=view_type, **options)        
        
