class PatientGroupReport(models.Model):
    _name = 'patientgroup.report'

    sync_type = sync.type
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date

    name = fields.Char(string="Patient Group Name")
    company_id = fields.Many2one('res.company', string="Company")

    @api.model
    def _query_values(self):
        query = """
            INSERT INTO patientgroup_report (
                company_id, sync_type, name, 
                create_date, create_uid, 
                write_date, write_uid) 
            (
                SELECT DISTINCT a.company_id, a.sync_type,
                    COALESCE(a.patient_group,'NULL') patient_group,
                    CURRENT_TIMESTAMP create_date, 1 create_uid, 
                    CURRENT_TIMESTAMP write_date, 1 write_uid
                FROM sale_order_line a
                WHERE NOT EXISTS (
                    SELECT 1 FROM patientgroup_report t
                    WHERE t.name = COALESCE(a.patient_group,'NULL')
                    AND t.company_id = a.company_id )
            )"""
        self.env.cr.execute(query)


    @api.model
    def get_view(self,view_id=None, view_type='form', **options):
        res = super(PatientGroupReport,self).get_view(view_id=view_id,view_type=view_type, **options)
    
        if view_type == 'form':
            res['arch'] = """
            <form string="Patient Group Report" delete="false">
                <sheet>
                    <group string="Information">
                        <field name="company_id" />
                        <field name="name" />
                    </group>
                    <notebook>
                        <page string="Technical">
                            <group>
                                <field name="sync_type" />
                                <field name="sync_consol_id_unit" readonly="1" />
                                <field name="sync_consol_id_main" readonly="1" />
                                <field name="sync_consol_date" readonly="1" />
                            </group>            
                        </page>
                    </notebook>
                </sheet>
            </form>
            """
        elif view_type == 'tree':
            res['arch'] = """
                <tree string="Patient Group Report" delete="false">
                    <field name="name" />
                    <field name="company_id" />
                    <field name="sync_type" />
                </tree>
            """
        from lxml import etree
        doc = etree.XML(res['arch'])
        View = self.env['ir.ui.view'].sudo()
        res['arch'], res['fields'] = View.postprocess_and_fields(doc, self._name, validate=True)
        return res


