                headers = {}
                headers['Content-Type'] = 'application/x-www-form-urlencoded'
                body = {}
                body['csrf_token'] = record.env.user.token_consol
                values = {}
                lst = []
                values['sync_type'] = str(record.company_id.sync_type)
                values[consol_id_from] = str(record.id)
                values['name'] = str(record.name)
                values['code'] = str(record.code)
                values['plan_id'] = record.plan_id.id
                values['type_analytic'] = record.type_analytic
                values['sync_wipro_type'] = str(record.sync_wipro_type)
                values['trigger_write'] = False

                if record.parent_id.id == False:
                    values['parent_id'] = record.parent_id.id
                else:
                    values['parent_id'] = str(record.parent_id.id)
                
                if record.partner_id.id == False:
                    values['partner_id'] = record.partner_id.id
                else:
                    values['partner_id'] = str(record.partner_id.id)
                if consol_type == 'unit':
                    sync_consol_id_main = str(self.env.user.login)
                    company_name = record.company_id.name
                    values['company_name'] = company_name
                    values['user_id_cek'] = sync_consol_id_main
                if consol_type == 'main':
                    sync_consol_id_main = str(self.env.user.login)
                    company_name = record.company_id.name
                    values['company_name'] = company_name
                    values['user_id_cek'] = sync_consol_id_main

                # if record.service_id.id == False:
                #     values['service_id'] = record.service_id.id
                # else:
                #     values['service_id'] = str(record.service_id.id)
                
                # if record.service_group.id == False:
                #     values['service_group'] = record.service_group.id
                # else:
