    @api.model
    def name_search(self, name, args=None, operator='ilike', limit=100):
        args = self.rule(args)
        return super(AccountAnalytic, self).name_search(name,args=args,operator=operator,limit=limit)

    # @api.multi
    def name_get(self):
        res = []
        for analytic in self:
            name = analytic.name
            if analytic.code:
                name = '[' + analytic.code + '] ' + name
            if analytic.partner_id:
                name = name
            res.append((analytic.id, name))
        return res



