    @api.model
    def _sync_specialization_wipro(self, sync_type='1'):
        sync_ids = {int(record.sync_id): int(record.id) for record in self.sudo().search([('sync_type', '=',sync_type), ('sync_id', '>',0), ('sync_wipro_type', '=', 'specialization')])}
        sync_date = self.sudo().search([('sync_type', '=', sync_type),('sync_wipro_type', '=', 'specialization')],order='sync_date desc',limit=1).sync_date
        query = """
            SELECT 
                SpecialiseID 'sync_id', 
                Specialisation 'name', 
                SpecialiseCode 'code', 
                cast(Blocked-1 as bit) 'active' 
            FROM dbo.VRP_OdooSpecializations
        """
        data = sync.get_data(sync.servers.get(sync_type), query)
        now = tools.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        for object in data:
            object['sync_date'] = now
            object['sync_type'], object['company_id'] = sync_type, self.env['res.company'].sudo().search([('sync_type', '=', sync_type)],limit=1).id
            object['sync_wipro_type'] = 'specialization'
            if int(object['sync_id']) in sync_ids:
                self.sudo().browse(sync_ids[object['sync_id']]).write(object)
            else:
                self.sudo().create(object)


    # @api.multi
    def unlink(self):
        for r in self:
            if r.crossovered_budget_line:
                raise exceptions.ValidationError("The budget has been filled, can't be deleted!")
        return super(AccountAnalytic, self).unlink()




