class ProfitabilityBulkingWizard(models.TransientModel):
    _name = 'profitability.bulking.wizard'

    @api.model
    def _get_company(self):
        return self.env.user.company_id.id
    
    company_id = fields.Many2one('res.company', string='Company', default=_get_company)
    date_start = fields.Date(string="Date Start")
    date_end = fields.Date(string="Date End")
    
    @api.model
    def fields_view_get(self, view_id=None, view_type='form', toolbar=False, submenu=False):
        res = super(ProfitabilityBulkingWizard, self).fields_view_get(view_id=view_id, view_type=view_type, toolbar=toolbar, submenu=submenu)
        res['arch'] = """
            <form string="Profitability Bulk Generate">
                <group>
                    <group>
                        <field name="company_id" required="1" />
                    </group>
                    <group>
                        <field name="date_start" required="1"/>
                        <field name="date_end" required="1"/>
                    </group>
                </group>
                <footer>
                    <button name="generate_data" string="Generate Profitability" type="object" class="oe_highlight"/>
                </footer>
            </form>
            """
        from lxml import etree
        doc = etree.XML(res['arch'])
        View = self.env['ir.ui.view'].sudo()
        res['arch'], res['fields'] = View.postprocess_and_fields(self._name, doc, view_id)
        return res


    # @api.multi
    def generate_delete(self):
        report_id = self.id 
        company_id = self.company_id.id 
        # date_start = str(datetime.datetime.strptime(self.date_start, '%Y-%m-%d').strftime("%Y-%m-%d"))
        # date_end = str(datetime.datetime.strptime(self.date_end, '%Y-%m-%d').strftime("%Y-%m-%d"))
        date_start = datetime.strptime(str(self.date_start), '%Y-%m-%d').strftime('%Y-%m-%d')
        date_end = datetime.strptime(str(self.date_end), '%Y-%m-%d').strftime('%Y-%m-%d')



        # delete existing profitability
        query = """
            delete from profitability_analysis
            where tglproses >= '{date_start}'
                and tglproses <= '{date_end}'
                and company_id = {company_id}
        """.format(
            company_id=company_id,
            date_start=date_start,
            date_end=date_end,
            user_id=self.env.user.id)
        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))


    # @api.multi
    def generate_revenue(self):
        report_id = self.id 
        company_id = self.company_id.id 
        date_start = datetime.strptime(str(self.date_start), '%Y-%m-%d').strftime("%Y-%m-%d")
        date_end = datetime.strptime(str(self.date_end), '%Y-%m-%d').strftime("%Y-%m-%d")

        # profitability from revenue 
        query = """
            insert into profitability_analysis(
                type_data, tglproses, company_id,
                doctor_standard_id, doctor_analytic_id, doctor_primary_id, doctor_perform_id, doctor_prescribe_id,
                parent_standard_id, parent_analytic_id, parent_primary_id, parent_perform_id, parent_prescribe_id,
                group_standard_doctor_id, group_standard_spec_id, group_standard_subspec_id,
                group_analytic_doctor_id, group_analytic_spec_id, group_analytic_subspec_id,
                group_primary_doctor_id, group_primary_spec_id, group_primary_subspec_id,
                group_perform_doctor_id, group_perform_spec_id, group_perform_subspec_id,
                group_prescribe_doctor_id, group_prescribe_spec_id, group_prescribe_subspec_id,
                partner_id, payer_id, payer_type, name, patient_group, service_group,
                service_id, department_id, item_specialisation, price_total, cost_total, other_cost,
                material_cost, service_cost, scrap_cost, margin_total, user_id
            ) 
            select (case 
                when a.type_line in ('BILL','BILLING') then 'BILL'
                when a.type_line in ('BILL CANCEL','BILLING CANCEL') then 'BILL-CANCEL'
                when a.type_line in ('ACCRUAL') then 'ACCRUAL'
                when a.type_line in ('ACCRUAL REVERSAL') then 'ACCRUAL-REVERSAL'
                when a.type_line in ('DISCOUNT') then 'DISCOUNT'
                when a.type_line in ('DISCOUNT CANCEL') then 'DISCOUNT-CANCEL'
                end) type_data, a.tglproses, a.company_id,

                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.prescribe_doc_id, a.primary_doc_id) 
                    else a.account_analytic_id end) doctor_standard_id,
                    
                (case when a.department_id ilike '%laboratory%' or a.department_id ilike '%laboratorium%' 
                    then coalesce(a.prescribe_doc_id, a.primary_doc_id)
                    else a.account_analytic_id 
                end) doctor_analytic_id, 
                a.primary_doc_id doctor_primary_id,
                coalesce(a.perform_doc_id, a.primary_doc_id) doctor_perform_id,
                coalesce(a.prescribe_doc_id, a.primary_doc_id) doctor_prescribe_id,

                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.parent_prescribe_id, prs.parent_id, prm.parent_id) 
                    else coalesce(a.parent_analytic_id, aac.parent_id) 
                    end) parent_standard_id,
                (case when a.department_id ilike '%laboratory%' or a.department_id ilike '%laboratorium%' 
                    then coalesce(a.parent_prescribe_id, prs.parent_id, prm.parent_id)
                    else coalesce(a.parent_analytic_id, aac.parent_id)
                end) parent_analytic_id,

                a.parent_analytic_primary_id parent_primary_id,
                coalesce(a.parent_perform_id, a.parent_analytic_primary_id) parent_perform_id,
                coalesce(a.parent_prescribe_id, prs.parent_id, prm.parent_id) parent_prescribe_id,

                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_doctor_id, a.group_analytic_doctor_id, a.group_primary_doctor_id) 
                    else coalesce(a.group_analytic_doctor_id, a.group_primary_doctor_id) 
                 end) group_standard_doctor_id,

                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_spec_id, a.group_analytic_spec_id, a.group_primary_spec_id) 
                    else coalesce(a.group_analytic_spec_id, a.group_primary_spec_id) 
                 end) group_standard_spec_id,
               
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_subspec_id, a.group_analytic_subspec_id, a.group_primary_subspec_id) 
                    else coalesce(a.group_analytic_subspec_id, a.group_primary_subspec_id) 
                 end) group_standard_subspec_id,

                (case when a.department_id ilike '%laboratory%' or a.department_id ilike '%laboratorium%' 
                    then a.group_prescribe_doctor_id
                    else a.group_analytic_doctor_id 
                end) group_analytic_doctor_id,
                
                (case when a.department_id ilike '%laboratory%' or a.department_id ilike '%laboratorium%' 
                    then a.group_prescribe_spec_id
                    else a.group_analytic_spec_id 
                end) group_analytic_spec_id,

                (case when a.department_id ilike '%laboratory%' or a.department_id ilike '%laboratorium%' 
                    then a.group_prescribe_subspec_id
                    else a.group_analytic_subspec_id 
                end) group_analytic_subspec_id,

                a.group_primary_doctor_id,
                a.group_primary_spec_id,
                a.group_primary_subspec_id,

                a.group_perform_doctor_id,
                a.group_perform_spec_id,
                a.group_perform_subspec_id,

                a.group_prescribe_doctor_id,
                a.group_prescribe_spec_id,
                a.group_prescribe_subspec_id,

                a.partner_id, a.payer payer_id, a.payer_type,
                aac.name, a.patient_group, 
                a.service_group, a.service_categ_id service_id, 
                a.department_id, a.item_specialisation,
                sum(a.price_total) price_total, 
                0 cost_total, 0 other_cost, 0 material_cost, 
                0 service_cost, 0 scrap_cost,
                sum(a.price_total) margin_total,
                {user_id} user_id 
            from sale_order_line a 
            left join account_analytic_account aac on aac.id = a.account_analytic_id
            left join account_analytic_account aap on aap.id = coalesce(a.parent_analytic_id, aac.parent_id)
            left join account_analytic_account prs on prs.id = a.prescribe_doc_id
            left join account_analytic_account prm on prm.id = a.primary_doc_id
            where a.company_id = {company_id} 
                and a.tglproses >= '{date_start}'
                and a.tglproses <= '{date_end}'
                and a.is_takeout is not True
                -- and a.payer_name not ilike '%(INTERCO)%'
            group by (case 
                when a.type_line in ('BILL','BILLING') then 'BILL'
                when a.type_line in ('BILL CANCEL','BILLING CANCEL') then 'BILL-CANCEL'
                when a.type_line in ('ACCRUAL') then 'ACCRUAL'
                when a.type_line in ('ACCRUAL REVERSAL') then 'ACCRUAL-REVERSAL'
                when a.type_line in ('DISCOUNT') then 'DISCOUNT'
                when a.type_line in ('DISCOUNT CANCEL') then 'DISCOUNT-CANCEL'
                end),
                a.tglproses, a.company_id,
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.prescribe_doc_id, a.primary_doc_id) else a.account_analytic_id end),
                (case when a.department_id ilike '%laboratory%' or a.department_id ilike '%laboratorium%' 
                    then coalesce(a.prescribe_doc_id, a.primary_doc_id)
                    else a.account_analytic_id 
                end), 
                a.primary_doc_id,
                coalesce(a.perform_doc_id, a.primary_doc_id),
                coalesce(a.prescribe_doc_id, a.primary_doc_id),
                
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.parent_prescribe_id, prs.parent_id, prm.parent_id) 
                    else coalesce(a.parent_analytic_id, aac.parent_id) 
                end),
                (case when a.department_id ilike '%laboratory%' or a.department_id ilike '%laboratorium%' 
                    then coalesce(a.parent_prescribe_id, prs.parent_id, prm.parent_id)
                    else coalesce(a.parent_analytic_id, aac.parent_id)
                end),
                a.parent_analytic_primary_id,
                coalesce(a.parent_perform_id, a.parent_analytic_primary_id),
                coalesce(a.parent_prescribe_id, prs.parent_id, prm.parent_id),

                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_doctor_id, a.group_analytic_doctor_id, a.group_primary_doctor_id) 
                    else coalesce(a.group_analytic_doctor_id, a.group_primary_doctor_id) 
                 end),
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_spec_id, a.group_analytic_spec_id, a.group_primary_spec_id) 
                    else coalesce(a.group_analytic_spec_id, a.group_primary_spec_id) 
                 end),
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_subspec_id, a.group_analytic_subspec_id, a.group_primary_subspec_id) 
                    else coalesce(a.group_analytic_subspec_id, a.group_primary_subspec_id) 
                 end),

                (case when a.department_id ilike '%laboratory%' or a.department_id ilike '%laboratorium%' 
                    then a.group_prescribe_doctor_id
                    else a.group_analytic_doctor_id 
                end),
                
                (case when a.department_id ilike '%laboratory%' or a.department_id ilike '%laboratorium%' 
                    then a.group_prescribe_spec_id
                    else a.group_analytic_spec_id 
                end),

                (case when a.department_id ilike '%laboratory%' or a.department_id ilike '%laboratorium%' 
                    then a.group_prescribe_subspec_id
                    else a.group_analytic_subspec_id 
                end),

                a.group_primary_doctor_id,
                a.group_primary_spec_id,
                a.group_primary_subspec_id,

                a.group_perform_doctor_id,
                a.group_perform_spec_id,
                a.group_perform_subspec_id,

                a.group_prescribe_doctor_id,
                a.group_prescribe_spec_id,
                a.group_prescribe_subspec_id,

                a.partner_id, a.payer, a.payer_type,
                aac.name, a.patient_group, a.service_group,
                a.service_categ_id, a.department_id, a.item_specialisation
            having sum(a.price_total) <> 0
        """.format(
            company_id=company_id, 
            date_start=date_start, 
            date_end=date_end, 
            user_id=self.env.user.id)
        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))


    


    # @api.multi
    def generate_sales_cost(self):
        report_id = self.id 
        company_id = self.company_id.id 
        date_start = datetime.strptime(str(self.date_start), '%Y-%m-%d').strftime("%Y-%m-%d")
        date_end = datetime.strptime(str(self.date_end), '%Y-%m-%d').strftime("%Y-%m-%d")

        # jika MHKN & MHSB ambil dari odoo_cost
        cost_column = "cost_total_odoo" if self.company_id.cogs_from_odoo is True else "cost_total"

        # profitability from sales cost
        query = """
            insert into profitability_analysis(
                type_data, tglproses, company_id,
                doctor_standard_id, doctor_analytic_id, doctor_primary_id, doctor_perform_id, doctor_prescribe_id,
                parent_standard_id, parent_analytic_id, parent_primary_id, parent_perform_id, parent_prescribe_id,
                group_standard_doctor_id, group_standard_spec_id, group_standard_subspec_id,
                group_analytic_doctor_id, group_analytic_spec_id, group_analytic_subspec_id,
                group_primary_doctor_id, group_primary_spec_id, group_primary_subspec_id,
                group_perform_doctor_id, group_perform_spec_id, group_perform_subspec_id,
                group_prescribe_doctor_id, group_prescribe_spec_id, group_prescribe_subspec_id,               
                partner_id, payer_id, payer_type, name, patient_group, service_group,
                service_id, department_id, price_total, cost_total, other_cost,
                material_cost, service_cost, scrap_cost,
                margin_total, user_id 
            ) 
            select 'SALES-COST' type_data,
                a.tglproses, a.company_id,
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.prescribe_doc_id, a.primary_doc_id) 
                    else a.account_analytic_id end) doctor_standard_id,
                a.account_analytic_id doctor_analytic_id, 
                a.primary_doc_id doctor_primary_id,
                coalesce(a.perform_doc_id, a.primary_doc_id) doctor_perform_id,
                coalesce(a.prescribe_doc_id, a.primary_doc_id) doctor_prescribe_id,
                
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.parent_prescribe_id, prs.parent_id, prm.parent_id) 
                    else coalesce(a.parent_analytic_id, aac.parent_id) 
                    end) parent_standard_id,
                coalesce(a.parent_analytic_id, aac.parent_id) parent_analytic_id,
                a.parent_analytic_primary_id parent_primary_id,
                coalesce(a.parent_perform_id, a.parent_analytic_primary_id) parent_perform_id,
                coalesce(a.parent_prescribe_id, prs.parent_id, prm.parent_id) parent_prescribe_id,

                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_doctor_id, a.group_analytic_doctor_id, a.group_primary_doctor_id) 
                    else coalesce(a.group_analytic_doctor_id, a.group_primary_doctor_id) 
                 end) group_standard_doctor_id,
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_spec_id, a.group_analytic_spec_id, a.group_primary_spec_id) 
                    else coalesce(a.group_analytic_spec_id, a.group_primary_spec_id) 
                 end) group_standard_spec_id,
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_subspec_id, a.group_analytic_subspec_id, a.group_primary_subspec_id) 
                    else coalesce(a.group_analytic_subspec_id, a.group_primary_subspec_id) 
                 end) group_standard_subspec_id,

                a.group_analytic_doctor_id,
                a.group_analytic_spec_id,
                a.group_analytic_subspec_id,

                a.group_primary_doctor_id,
                a.group_primary_spec_id,
                a.group_primary_subspec_id,

                a.group_perform_doctor_id,
                a.group_perform_spec_id,
                a.group_perform_subspec_id,

                a.group_prescribe_doctor_id,
                a.group_prescribe_spec_id,
                a.group_prescribe_subspec_id,

                a.partner_id, a.payer payer_id, a.payer_type,
                aac.name, a.patient_group, a.service_group,
                a.service_categ_id service_id, a.department_id,
                0 price_total, sum(a.{cost_column}) cost_total, 
                0 other_cost, sum(a.{cost_column}) material_cost, 
                0 service_cost, 0 scrap_cost,
                sum(-1*a.{cost_column}) margin_total,
                {user_id} user_id  
            from sale_order_line a 
            left join account_analytic_account aac on aac.id = a.account_analytic_id
            left join account_analytic_account aap on aap.id = coalesce(a.parent_analytic_id, aac.parent_id)
            left join account_analytic_account prs on prs.id = a.prescribe_doc_id
            left join account_analytic_account prm on prm.id = a.primary_doc_id
            where a.company_id = {company_id} 
                and a.tglproses >= '{date_start}'
                and a.tglproses <= '{date_end}'
                and a.is_takeout is not True
                -- and a.payer_name not ilike '%(INTERCO)%'
            group by 
                a.tglproses, a.company_id,
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.prescribe_doc_id, a.primary_doc_id) else a.account_analytic_id end),
                a.account_analytic_id, a.primary_doc_id,
                coalesce(a.perform_doc_id, a.primary_doc_id),
                coalesce(a.prescribe_doc_id, a.primary_doc_id),
                
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.parent_prescribe_id, prs.parent_id, prm.parent_id) 
                    else coalesce(a.parent_analytic_id, aac.parent_id) 
                end),
                coalesce(a.parent_analytic_id, aac.parent_id),
                a.parent_analytic_primary_id,
                coalesce(a.parent_perform_id, a.parent_analytic_primary_id),
                coalesce(a.parent_prescribe_id, prs.parent_id, prm.parent_id),

                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_doctor_id, a.group_analytic_doctor_id, a.group_primary_doctor_id) 
                    else coalesce(a.group_analytic_doctor_id, a.group_primary_doctor_id) 
                 end),
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_spec_id, a.group_analytic_spec_id, a.group_primary_spec_id) 
                    else coalesce(a.group_analytic_spec_id, a.group_primary_spec_id) 
                 end),
                (case when aap.name->>'en_US' ilike '%anesthesi%' or aap.name->>'en_US' ilike '%radiolog%'
                    then coalesce(a.group_prescribe_subspec_id, a.group_analytic_subspec_id, a.group_primary_subspec_id) 
                    else coalesce(a.group_analytic_subspec_id, a.group_primary_subspec_id) 
                 end),

                a.group_analytic_doctor_id,
                a.group_analytic_spec_id,
                a.group_analytic_subspec_id,

                a.group_primary_doctor_id,
                a.group_primary_spec_id,
                a.group_primary_subspec_id,

                a.group_perform_doctor_id,
                a.group_perform_spec_id,
                a.group_perform_subspec_id,

                a.group_prescribe_doctor_id,
                a.group_prescribe_spec_id,
                a.group_prescribe_subspec_id,

                a.partner_id, a.payer, a.payer_type,
                aac.name, a.patient_group, a.service_group,
                a.service_categ_id, a.department_id
            having sum(a.{cost_column}) <> 0
        """.format(
            company_id=company_id, 
            date_start=date_start, 
            date_end=date_end,
            cost_column=cost_column,
            user_id=self.env.user.id)
        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))


    # @api.multi
    def generate_doctor_fee_line(self):
        report_id = self.id 
        company_id = self.company_id.id 
        date_start = datetime.strptime(str(self.date_start), '%Y-%m-%d').strftime("%Y-%m-%d")
        date_end = datetime.strptime(str(self.date_end), '%Y-%m-%d').strftime("%Y-%m-%d")


        # profitability from service cost from doctor.fee.line
        query = """
            insert into profitability_analysis(
                type_data, tglproses, company_id,
                doctor_standard_id, doctor_analytic_id, doctor_primary_id, doctor_perform_id, doctor_prescribe_id,
                parent_standard_id, parent_analytic_id, parent_primary_id, parent_perform_id, parent_prescribe_id,
                group_standard_doctor_id, group_standard_spec_id, group_standard_subspec_id,
                group_analytic_doctor_id, group_analytic_spec_id, group_analytic_subspec_id,
                group_primary_doctor_id, group_primary_spec_id, group_primary_subspec_id,
                group_perform_doctor_id, group_perform_spec_id, group_perform_subspec_id,
                group_prescribe_doctor_id, group_prescribe_spec_id, group_prescribe_subspec_id,               
                partner_id, payer_id, payer_type, name, patient_group, service_group,
                service_id, department_id, price_total, cost_total, other_cost,
                material_cost, service_cost, scrap_cost, margin_total, user_id 
            ) 
            select 'SERVICE-LINE' type_data,
                date(a.tglproses) tglproses, a.company_id,
                a.odoo_doctor_id doctor_standard_id, 
                a.odoo_doctor_id doctor_analytic_id, 
                a.odoo_primary_id doctor_primary_id, 
                per.id doctor_perform_id, 
                pre.id doctor_prescribe_id,
                aac.parent_id parent_standard_id, 
                aac.parent_id parent_analytic_id, 
                pri.parent_id parent_primary_id, 
                per.parent_id parent_perform_id, 
                pre.parent_id parent_prescribe_id,

                coalesce(aac.group_doctor_id, pri.group_doctor_id) group_standard_doctor_id,
                coalesce(aac.group_specialization_id, pri.group_specialization_id) group_standard_spec_id,
                coalesce(aac.group_subspecialization_id, pri.group_subspecialization_id) group_standard_subspec_id,

                aac.group_doctor_id group_analytic_doctor_id,
                aac.group_specialization_id group_analytic_spec_id,
                aac.group_subspecialization_id group_analytic_subspec_id,

                pri.group_doctor_id group_primary_doctor_id,
                pri.group_specialization_id group_primary_spec_id,
                pri.group_subspecialization_id group_primary_subspec_id,

                per.group_doctor_id group_perform_doctor_id,
                per.group_specialization_id group_perform_spec_id,
                per.group_subspecialization_id group_perform_subspec_id,

                pre.group_doctor_id group_prescribe_doctor_id,
                pre.group_specialization_id group_prescribe_spec_id,
                pre.group_subspecialization_id group_prescribe_subspec_id,

                a.odoo_patient_id partner_id, a.odoo_payer_id payer_id, 
                a.payer_type payer_type, aac."name", a.patient_group, a.service_group,
                a.odoo_service_id service_id, a.department_name department_id, 
                0 price_total, sum(a.rate) cost_total, 0 other_cost,
                0 material_cost, sum(a.rate) service_cost,
                0 scrap_cost, sum(-1*a.rate) margin_total, 
                {user_id} user_id 
            from doctor_fee_line a 
            left join account_analytic_account aac on aac.id = a.odoo_doctor_id
            left join account_analytic_account pri on pri.id = a.odoo_primary_id
            left join account_analytic_account per on per.id = coalesce(a.odoo_perform_id, a.odoo_primary_id)
            left join account_analytic_account pre on pre.id = coalesce(a.odoo_prescribe_id, a.odoo_primary_id)
            where a.company_id = {company_id}
                and date(a.tglproses) >= '{date_start}'
                and date(a.tglproses) <= '{date_end}'
                and a."state" in('confirmed','posted')
            group by date(a.tglproses), a.company_id,
                a.odoo_service_id, a.department_name, 
                aac."name", a.odoo_payer_id, a.payer_type,
                a.patient_group, a.service_group, a.odoo_patient_id,
                a.odoo_doctor_id, a.odoo_primary_id, 
                per.id, pre.id, aac.parent_id, 
                pri.parent_id, per.parent_id, pre.parent_id,

                coalesce(aac.group_doctor_id, pri.group_doctor_id),
                coalesce(aac.group_specialization_id, pri.group_specialization_id),
                coalesce(aac.group_subspecialization_id, pri.group_subspecialization_id),

                aac.group_doctor_id, aac.group_specialization_id, aac.group_subspecialization_id,
                pri.group_doctor_id, pri.group_specialization_id, pri.group_subspecialization_id,
                per.group_doctor_id, per.group_specialization_id, per.group_subspecialization_id,
                pre.group_doctor_id, pre.group_specialization_id, pre.group_subspecialization_id
            having sum(a.rate) <> 0
        """.format(
            company_id=company_id, 
            date_start=date_start, 
            date_end=date_end,
            user_id=self.env.user.id)
        self.sudo().env.cr.execute(query)
        # open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))


    

    

    # @api.multi
    def generate_doctor_fee_other(self):
        report_id = self.id 
        company_id = self.company_id.id 
        date_start = datetime.strptime(str(self.date_start), '%Y-%m-%d').strftime("%Y-%m-%d")
        date_end = datetime.strptime(str(self.date_end), '%Y-%m-%d').strftime("%Y-%m-%d")

        # profitability from service cost doctor.fee << others.transaction  BPJS
        query = """
            insert into profitability_analysis(
                type_data, tglproses, company_id,
                doctor_standard_id, doctor_analytic_id, doctor_primary_id, doctor_perform_id, doctor_prescribe_id,
                parent_standard_id, parent_analytic_id, parent_primary_id, parent_perform_id, parent_prescribe_id,
                group_standard_doctor_id, group_standard_spec_id, group_standard_subspec_id,
                group_analytic_doctor_id, group_analytic_spec_id, group_analytic_subspec_id,
                group_primary_doctor_id, group_primary_spec_id, group_primary_subspec_id,
                group_perform_doctor_id, group_perform_spec_id, group_perform_subspec_id,
                group_prescribe_doctor_id, group_prescribe_spec_id, group_prescribe_subspec_id,               
                partner_id, payer_id, payer_type, name, patient_group, service_group,
                service_id, department_id, price_total, cost_total, other_cost,
                material_cost, service_cost, scrap_cost, margin_total, user_id 
            ) 
            select 'SERVICE-BPJS' type_data,
                a.tglproses, {company_id} company_id,
                c.doctor_standard_id, 
                c.doctor_analytic_id, 
                c.doctor_primary_id, 
                c.doctor_perform_id, 
                c.doctor_prescribe_id,
                c.parent_standard_id, 
                c.parent_analytic_id, 
                c.parent_primary_id, 
                c.parent_perform_id, 
                c.parent_prescribe_id,

                c.group_standard_doctor_id,
                c.group_standard_spec_id,
                c.group_standard_subspec_id,

                c.group_analytic_doctor_id,
                c.group_analytic_spec_id,
                c.group_analytic_subspec_id,

                c.group_primary_doctor_id,
                c.group_primary_spec_id,
                c.group_primary_subspec_id,

                c.group_perform_doctor_id,
                c.group_perform_spec_id,
                c.group_perform_subspec_id,

                c.group_prescribe_doctor_id,
                c.group_prescribe_spec_id,
                c.group_prescribe_subspec_id,

                c.partner_id, coalesce(a.partner_id,d.payer_id) payer_id, 
                d.payer_type, c."name", c.patient_group, c.service_group,
                c.service_id, c.department_id, 
                0 price_total, 
                (case when b.fee_total = 0 then 0 else (c.fee_amount/b.fee_total * a.amount) end) cost_total, 
                0 other_cost,
                0 material_cost, 
                (case when b.fee_total = 0 then 0 else (c.fee_amount/b.fee_total * a.amount) end) service_cost,
                0 scrap_cost, 
                (case when b.fee_total = 0 then 0 else (c.fee_amount/b.fee_total * a.amount * -1) end) margin_total, 
                {user_id} user_id 
            from (
                select 
                    date('{date_end}') tglproses,
                    a.id doctor_fee_id,
                    a.doctor_id, 
                    sum(b.amount) amount,
                    max(b.partner_id) partner_id
                from doctor_fee a
                inner join other_transaction b on b.doctor_fee_id = a.id
                where a.year = date_part('year', timestamp '{date_start}')
                    and a.month = date_part('month', timestamp '{date_start}')::text
                    and a.state in('posted','confirmed')
                    and a.company_id = {company_id}
                    and a.is_pot_total is not True
                    and b.other_type = 'BPJS'
                group by a.doctor_id, a.id
            ) as a 
            left join lateral (
                select sum(dfl.rate) fee_total
                from doctor_fee_line dfl 
                inner join res_partner py on py.id = dfl.odoo_payer_id
                where dfl.doctor_fee_id = a.doctor_fee_id
                    and dfl.company_id = {company_id}
                    and date(dfl.tglproses) >= '{date_start}'
                    and date(dfl.tglproses) <= '{date_end}'
                    and dfl."state" in('confirmed','posted')
                    -- and py.name ilike '%BPJS KESEHATAN%'
            ) b on 1=1
            left join lateral (
                select 
                    dfl.company_id,
                    dfl.odoo_doctor_id doctor_standard_id, 
                    dfl.odoo_doctor_id doctor_analytic_id, 
                    dfl.odoo_primary_id doctor_primary_id, 
                    per.id doctor_perform_id, 
                    pre.id doctor_prescribe_id,
                    aac.parent_id parent_standard_id, 
                    aac.parent_id parent_analytic_id, 
                    pri.parent_id parent_primary_id, 
                    per.parent_id parent_perform_id, 
                    pre.parent_id parent_prescribe_id,

                    coalesce(aac.group_doctor_id, pri.group_doctor_id) group_standard_doctor_id,
                    coalesce(aac.group_specialization_id, pri.group_specialization_id) group_standard_spec_id,
                    coalesce(aac.group_subspecialization_id, pri.group_subspecialization_id) group_standard_subspec_id,

                    aac.group_doctor_id group_analytic_doctor_id,
                    aac.group_specialization_id group_analytic_spec_id,
                    aac.group_subspecialization_id group_analytic_subspec_id,

                    pri.group_doctor_id group_primary_doctor_id,
                    pri.group_specialization_id group_primary_spec_id,
                    pri.group_subspecialization_id group_primary_subspec_id,

                    per.group_doctor_id group_perform_doctor_id,
                    per.group_specialization_id group_perform_spec_id,
                    per.group_subspecialization_id group_perform_subspec_id,

                    pre.group_doctor_id group_prescribe_doctor_id,
                    pre.group_specialization_id group_prescribe_spec_id,
                    pre.group_subspecialization_id group_prescribe_subspec_id,

                    dfl.odoo_patient_id partner_id, dfl.odoo_payer_id payer_id, 
                    dfl.payer_type payer_type, aac."name", dfl.patient_group, dfl.service_group,
                    dfl.odoo_service_id service_id, dfl.department_name department_id,
                    sum(dfl.rate) fee_amount
                from doctor_fee_line dfl 
                inner join res_partner py on py.id = dfl.odoo_payer_id
                left join account_analytic_account aac on aac.id = dfl.odoo_doctor_id
                left join account_analytic_account pri on pri.id = dfl.odoo_primary_id
                left join account_analytic_account per on per.id = coalesce(dfl.odoo_perform_id, dfl.odoo_primary_id)
                left join account_analytic_account pre on pre.id = coalesce(dfl.odoo_prescribe_id, dfl.odoo_primary_id)
                where dfl.doctor_fee_id = a.doctor_fee_id
                    and dfl.company_id = {company_id}
                    and date(dfl.tglproses) >= '{date_start}'
                    and date(dfl.tglproses) <= '{date_end}'
                    and dfl."state" in('confirmed','posted')
                    -- and py.name ilike '%BPJS KESEHATAN%'
                group by dfl.company_id,
                    dfl.odoo_service_id, dfl.department_name, 
                    aac."name", dfl.odoo_payer_id, dfl.payer_type,
                    dfl.patient_group, dfl.service_group, dfl.odoo_patient_id,
                    dfl.odoo_doctor_id, dfl.odoo_primary_id, 
                    per.id, pre.id, aac.parent_id, 
                    pri.parent_id, per.parent_id, pre.parent_id,

                    coalesce(aac.group_doctor_id, pri.group_doctor_id),
                    coalesce(aac.group_specialization_id, pri.group_specialization_id),
                    coalesce(aac.group_subspecialization_id, pri.group_subspecialization_id),

                    aac.group_doctor_id, aac.group_specialization_id, aac.group_subspecialization_id,
                    pri.group_doctor_id, pri.group_specialization_id, pri.group_subspecialization_id,
                    per.group_doctor_id, per.group_specialization_id, per.group_subspecialization_id,
                    pre.group_doctor_id, pre.group_specialization_id, pre.group_subspecialization_id
                having sum(dfl.rate) <> 0
                
            ) c on 1=1

            left join lateral (
				select py."id" payer_id,
					py.customer_type_wipro payer_type, 
					py."name" payer_name
				from res_partner py 
				where py.insurance = True 
					and py.active = True 
					and py.sync_type is not null 
					and py.company_id = {company_id}
					and py.name ilike '%BPJS KESEHATAN'
				order by py.id desc limit 1 
            ) d on 1=1

        """.format(
            company_id=company_id, 
            date_start=date_start, 
            date_end=date_end,
            user_id=self.env.user.id)
        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))



        # profitability from service cost doctor.fee << others.transaction 
        query = """
            insert into profitability_analysis(
                type_data, tglproses, company_id,
                doctor_standard_id, doctor_analytic_id, doctor_primary_id, doctor_perform_id, doctor_prescribe_id,
                parent_standard_id, parent_analytic_id, parent_primary_id, parent_perform_id, parent_prescribe_id,
                group_standard_doctor_id, group_standard_spec_id, group_standard_subspec_id,
                group_analytic_doctor_id, group_analytic_spec_id, group_analytic_subspec_id,
                group_primary_doctor_id, group_primary_spec_id, group_primary_subspec_id,
                group_perform_doctor_id, group_perform_spec_id, group_perform_subspec_id,
                group_prescribe_doctor_id, group_prescribe_spec_id, group_prescribe_subspec_id,               
                partner_id, payer_id, payer_type, name, patient_group, service_group,
                service_id, department_id, price_total, cost_total, other_cost,
                material_cost, service_cost, scrap_cost, margin_total, user_id 
            ) 
            select 'SERVICE-OTHER' type_data,
                a.tglproses, {company_id} company_id,
                c.doctor_standard_id, 
                c.doctor_analytic_id, 
                c.doctor_primary_id, 
                c.doctor_perform_id, 
                c.doctor_prescribe_id,
                c.parent_standard_id, 
                c.parent_analytic_id, 
                c.parent_primary_id, 
                c.parent_perform_id, 
                c.parent_prescribe_id,

                c.group_standard_doctor_id,
                c.group_standard_spec_id,
                c.group_standard_subspec_id,

                c.group_analytic_doctor_id,
                c.group_analytic_spec_id,
                c.group_analytic_subspec_id,

                c.group_primary_doctor_id,
                c.group_primary_spec_id,
                c.group_primary_subspec_id,

                c.group_perform_doctor_id,
                c.group_perform_spec_id,
                c.group_perform_subspec_id,

                c.group_prescribe_doctor_id,
                c.group_prescribe_spec_id,
                c.group_prescribe_subspec_id,

                c.partner_id, c.payer_id, 
                c.payer_type, c."name", c.patient_group, c.service_group,
                c.service_id, c.department_id, 
                0 price_total, 
                (case when b.fee_total = 0 then 0 else (c.fee_amount/b.fee_total * a.amount) end) cost_total, 
                0 other_cost,
                0 material_cost, 
                (case when b.fee_total = 0 then 0 else (c.fee_amount/b.fee_total * a.amount) end) service_cost,
                0 scrap_cost, 
                (case when b.fee_total = 0 then 0 else (c.fee_amount/b.fee_total * a.amount * -1) end) margin_total, 
                {user_id} user_id 
            from (
                select 
                    date('{date_end}') tglproses,
                    a.id doctor_fee_id,
                    a.doctor_id, 
                    sum(b.amount) amount
                from doctor_fee a
                inner join other_transaction b on b.doctor_fee_id = a.id
                where a.year = date_part('year', timestamp '{date_start}')
                    and a.month = date_part('month', timestamp '{date_start}')::text
                    and a.state in('posted','confirmed')
                    and a.company_id = {company_id}
                    and a.is_pot_total is not True
                    and b.other_type <> 'BPJS'
                group by a.doctor_id, a.id
            ) as a 
            left join lateral (
                select sum(dfl.rate) fee_total
                from doctor_fee_line dfl 
                inner join res_partner py on py.id = dfl.odoo_payer_id
                where dfl.doctor_fee_id = a.doctor_fee_id
                    and dfl.company_id = {company_id}
                    and date(dfl.tglproses) >= '{date_start}'
                    and date(dfl.tglproses) <= '{date_end}'
                    and dfl."state" in('confirmed','posted')
                    and py.name not ilike '%BPJS KESEHATAN%'
            ) b on 1=1
            left join lateral (
                select 
                    dfl.company_id,
                    dfl.odoo_doctor_id doctor_standard_id, 
                    dfl.odoo_doctor_id doctor_analytic_id, 
                    dfl.odoo_primary_id doctor_primary_id, 
                    per.id doctor_perform_id, 
                    pre.id doctor_prescribe_id,
                    aac.parent_id parent_standard_id, 
                    aac.parent_id parent_analytic_id, 
                    pri.parent_id parent_primary_id, 
                    per.parent_id parent_perform_id, 
                    pre.parent_id parent_prescribe_id,

                    coalesce(aac.group_doctor_id, pri.group_doctor_id) group_standard_doctor_id,
                    coalesce(aac.group_specialization_id, pri.group_specialization_id) group_standard_spec_id,
                    coalesce(aac.group_subspecialization_id, pri.group_subspecialization_id) group_standard_subspec_id,

                    aac.group_doctor_id group_analytic_doctor_id,
                    aac.group_specialization_id group_analytic_spec_id,
                    aac.group_subspecialization_id group_analytic_subspec_id,

                    pri.group_doctor_id group_primary_doctor_id,
                    pri.group_specialization_id group_primary_spec_id,
                    pri.group_subspecialization_id group_primary_subspec_id,

                    per.group_doctor_id group_perform_doctor_id,
                    per.group_specialization_id group_perform_spec_id,
                    per.group_subspecialization_id group_perform_subspec_id,

                    pre.group_doctor_id group_prescribe_doctor_id,
                    pre.group_specialization_id group_prescribe_spec_id,
                    pre.group_subspecialization_id group_prescribe_subspec_id,

                    dfl.odoo_patient_id partner_id, dfl.odoo_payer_id payer_id, 
                    dfl.payer_type payer_type, aac."name", dfl.patient_group, dfl.service_group,
                    dfl.odoo_service_id service_id, dfl.department_name department_id,
                    sum(dfl.rate) fee_amount
                from doctor_fee_line dfl 
                inner join res_partner py on py.id = dfl.odoo_payer_id
                left join account_analytic_account aac on aac.id = dfl.odoo_doctor_id
                left join account_analytic_account pri on pri.id = dfl.odoo_primary_id
                left join account_analytic_account per on per.id = coalesce(dfl.odoo_perform_id, dfl.odoo_primary_id)
                left join account_analytic_account pre on pre.id = coalesce(dfl.odoo_prescribe_id, dfl.odoo_primary_id)
                where py.name not ilike '%BPJS KESEHATAN%'
                    and dfl.doctor_fee_id = a.doctor_fee_id
                    and dfl.company_id = {company_id}
                    and date(dfl.tglproses) >= '{date_start}'
                    and date(dfl.tglproses) <= '{date_end}'
                    and dfl."state" in('confirmed','posted')
                group by dfl.company_id,
                    dfl.odoo_service_id, dfl.department_name, 
                    aac."name", dfl.odoo_payer_id, dfl.payer_type,
                    dfl.patient_group, dfl.service_group, dfl.odoo_patient_id,
                    dfl.odoo_doctor_id, dfl.odoo_primary_id, 
                    per.id, pre.id, aac.parent_id, 
                    pri.parent_id, per.parent_id, pre.parent_id,

                    coalesce(aac.group_doctor_id, pri.group_doctor_id),
                    coalesce(aac.group_specialization_id, pri.group_specialization_id),
                    coalesce(aac.group_subspecialization_id, pri.group_subspecialization_id),

                    aac.group_doctor_id, aac.group_specialization_id, aac.group_subspecialization_id,
                    pri.group_doctor_id, pri.group_specialization_id, pri.group_subspecialization_id,
                    per.group_doctor_id, per.group_specialization_id, per.group_subspecialization_id,
                    pre.group_doctor_id, pre.group_specialization_id, pre.group_subspecialization_id
                having sum(dfl.rate) <> 0
                
            ) c on 1=1

        """.format(
            company_id=company_id, 
            date_start=date_start, 
            date_end=date_end,
            user_id=self.env.user.id)
        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))

        




