    def generate_referral_line(self):
        report_id = self.id 
        company_id = self.company_id.id 
        date_start = datetime.strptime(str(self.date_start), '%Y-%m-%d').strftime("%Y-%m-%d")
        date_end = datetime.strptime(str(self.date_end), '%Y-%m-%d').strftime("%Y-%m-%d")

        # profitability from referral cost from referral.fee.line
        query = """
            insert into profitability_analysis(
                type_data, tglproses, company_id,
                doctor_standard_id, doctor_analytic_id, doctor_primary_id, doctor_perform_id, doctor_prescribe_id,
                parent_standard_id, parent_analytic_id, parent_primary_id, parent_perform_id, parent_prescribe_id,
                group_standard_doctor_id, group_standard_spec_id, group_standard_subspec_id,
                group_analytic_doctor_id, group_analytic_spec_id, group_analytic_subspec_id,
                group_primary_doctor_id, group_primary_spec_id, group_primary_subspec_id,
                group_perform_doctor_id, group_perform_spec_id, group_perform_subspec_id,
                group_prescribe_doctor_id, group_prescribe_spec_id, group_prescribe_subspec_id,               
                
                partner_id, payer_id, payer_type,
                name, patient_group, service_group,
                service_id, department_id,
                price_total, cost_total,
                material_cost, service_cost, 
                scrap_cost, margin_total, user_id
            ) 
            select 'REFERRAL-COST' type_data,
                date('{date_end}') tglproses, a.company_id,
                aac.id doctor_standard_id, 
                aac.id doctor_analytic_id, 
                aac.id doctor_primary_id, 
                aac.id doctor_perform_id, 
                aac.id doctor_prescribe_id,
                aac.parent_id parent_standard_id, 
                aac.parent_id parent_analytic_id, 
                aac.parent_id parent_primary_id, 
                aac.parent_id parent_perform_id, 
                aac.parent_id parent_prescribe_id,

                aac.group_doctor_id group_standard_doctor_id,
                aac.group_specialization_id group_standard_spec_id,
                aac.group_subspecialization_id group_standard_subspec_id, 

                aac.group_doctor_id group_analytic_doctor_id,
                aac.group_specialization_id group_analytic_spec_id,
                aac.group_subspecialization_id group_analytic_subspec_id, 

                aac.group_doctor_id group_primary_doctor_id,
                aac.group_specialization_id group_primary_spec_id,
                aac.group_subspecialization_id group_primary_subspec_id,

                aac.group_doctor_id group_perform_doctor_id,
                aac.group_specialization_id group_perform_spec_id,
                aac.group_subspecialization_id group_perform_subspec_id,

                aac.group_doctor_id group_prescribe_doctor_id,
                aac.group_specialization_id group_prescribe_spec_id,
                aac.group_subspecialization_id group_prescribe_subspec_id,

                b.patient_id partner_id, b.payer_id, 
                py.customer_type_wipro payer_type, aac."name", 
                null patient_group,null service_group,
                b.service_id, null department_id, 
                0 price_total, sum(b.fee_amount) cost_total, 
                0 material_cost, sum(b.fee_amount) service_cost, 
                0 scrap_cost, sum(-1*b.fee_amount) margin_total, 
                {user_id} user_id 
            from referral_fee a
            inner join referral_fee_line b on b.fee_id = a.id  
            left join referral_agen c on c.id = a.external_id
            left join account_analytic_account aac on aac.id = c.doctor_id
            left join res_partner py on py.id = b.payer_id
            where a.company_id = {company_id}
                and a."year" = '{year}'
                and a."month" = '{month}'
                and a."state" = 'confirm'
            group by a.company_id, aac.id, aac.parent_id, b.patient_id, b.payer_id, 
              py.customer_type_wipro, aac."name", b.service_id,
              aac.group_doctor_id, aac.group_specialization_id, 
              aac.group_subspecialization_id
            having sum(b.fee_amount) <> 0

        """.format(
            company_id = company_id, 
            date_end = date_end,
            year = tools.datetime.strptime(date_end, "%Y-%m-%d").year,
            month = tools.datetime.strptime(date_end, "%Y-%m-%d").month,
            user_id = self.env.user.id 
        )
        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))


