    # @api.multi
    def generate_throughput(self):
        report_id = self.id 
        company_id = self.company_id.id 
        date_start = datetime.strptime(str(self.date_start), '%Y-%m-%d').strftime("%Y-%m-%d")
        date_end = datetime.strptime(str(self.date_end), '%Y-%m-%d').strftime("%Y-%m-%d")

        query = """
            insert into profitability_analysis(
                type_data, tglproses, company_id,
                doctor_standard_id, doctor_analytic_id, doctor_primary_id, doctor_perform_id, doctor_prescribe_id,
                parent_standard_id, parent_analytic_id, parent_primary_id, parent_perform_id, parent_prescribe_id,
                group_standard_doctor_id, group_standard_spec_id, group_standard_subspec_id,
                group_analytic_doctor_id, group_analytic_spec_id, group_analytic_subspec_id,
                group_primary_doctor_id, group_primary_spec_id, group_primary_subspec_id,
                group_perform_doctor_id, group_perform_spec_id, group_perform_subspec_id,
                group_prescribe_doctor_id, group_prescribe_spec_id, group_prescribe_subspec_id,
                payer_id, payer_type, name, patient_group, service_group,
                service_id, department_id, price_total, cost_total, other_cost,
                material_cost, service_cost, scrap_cost, margin_total, user_id,
                throughput
            ) 
            select 
                'THROUGHPUT' type_data, 
                a.tglproses, 
                {company_id} company_id,
                a.doctor_id doctor_standard_id, 
                a.doctor_id doctor_analytic_id, 
                a.doctor_id doctor_primary_id, 
                a.doctor_id doctor_perform_id, 
                a.doctor_id doctor_prescribe_id,
                a.parent_id parent_standard_id, 
                a.parent_id parent_analytic_id, 
                a.parent_id parent_primary_id, 
                a.parent_id parent_perform_id, 
                a.parent_id parent_prescribe_id,
                a.group_doctor_id group_standard_doctor_id, 
                a.group_specialization_id group_standard_spec_id, 
                a.group_subspecialization_id group_standard_subspec_id,
                a.group_doctor_id group_analytic_doctor_id, 
                a.group_specialization_id group_analytic_spec_id, 
                a.group_subspecialization_id group_analytic_subspec_id,
                a.group_doctor_id group_primary_doctor_id, 
                a.group_specialization_id group_primary_spec_id, 
                a.group_subspecialization_id group_primary_subspec_id,
                a.group_doctor_id group_perform_doctor_id, 
                a.group_specialization_id group_perform_spec_id, 
                a.group_subspecialization_id group_perform_subspec_id,
                a.group_doctor_id group_prescribe_doctor_id, 
                a.group_specialization_id group_prescribe_spec_id, 
                a.group_subspecialization_id group_prescribe_subspec_id,
                a.partner_id payer_id, b.customer_type_wipro payer_type, 
                b.name, 'IPD' patient_group, '' service_group,
                null service_id, '' department_id, 0 price_total, 0 cost_total, 
                0 other_cost, 0 material_cost, 0 service_cost, 0 scrap_cost, 
                0 margin_total, {user_id} user_id, count(*) throughput
            from (
                select 
                    date(a.admit_date) tglproses,
                    so.id order_id, 
                    so."name" admission_no,
                    dr."id" doctor_id,
                    dr.parent_id parent_id,
                    dr.group_doctor_id,
                    dr.group_specialization_id,
                    dr.group_subspecialization_id,
                    so.payer_id partner_id 
                from sale_order_line a 
                inner join sale_order so on so.id = a.order_id
                left join account_analytic_account dr on dr.id = a.primary_doc_id
                where a.company_id = {company_id}
                    and a.tglproses >= '{date_start}'
                    and a.tglproses <= '{date_end}'
                    and so.patient_type = '2'
                    and date(a.tglproses) = date(a.admit_date)
                    and a.admit_date >= '{date_start} 00:00:00'
                    and a.admit_date <= '{date_end} 23:59:59'
                group by so.id, so."name",
                    dr."id", dr.parent_id,
                    dr.group_doctor_id,
                    dr.group_specialization_id,
                    dr.group_subspecialization_id,
                    date(a.admit_date),
                    so.payer_id
            ) as a 
            left join res_partner b on b.id = a.partner_id
            group by 
                a.tglproses, 
                a.doctor_id,
                a.parent_id,
                a.partner_id, 
                a.group_doctor_id,
                a.group_specialization_id,
                a.group_subspecialization_id,
                b.name, b.customer_type_wipro 
        """.format(
            company_id=company_id, 
            date_start=date_start, 
            date_end=date_end, 
            user_id=self.env.user.id)
        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))



