    # @api.multi
    def generate_doctor_fee_thp_new(self):
        report_id = self.id 
        company_id = self.company_id.id 
        date_start = datetime.strptime(str(self.date_start), '%Y-%m-%d').strftime("%Y-%m-%d")
        date_end = datetime.strptime(str(self.date_end), '%Y-%m-%d').strftime("%Y-%m-%d")

        # profitability from service cost from other selisih dari THP per doctor
        query = """
            insert into profitability_analysis(
                type_data, tglproses, company_id,
                doctor_standard_id, doctor_analytic_id, doctor_primary_id, doctor_perform_id, doctor_prescribe_id,
                parent_standard_id, parent_analytic_id, parent_primary_id, parent_perform_id, parent_prescribe_id,
                group_standard_doctor_id, group_standard_spec_id, group_standard_subspec_id,
                group_analytic_doctor_id, group_analytic_spec_id, group_analytic_subspec_id,
                group_primary_doctor_id, group_primary_spec_id, group_primary_subspec_id,
                group_perform_doctor_id, group_perform_spec_id, group_perform_subspec_id,
                group_prescribe_doctor_id, group_prescribe_spec_id, group_prescribe_subspec_id,               
                payer_id, payer_type,
                price_total, cost_total, other_cost,
                material_cost, service_cost, 
                scrap_cost, margin_total, user_id 
            )  

            select 'SERVICE-THP' type_data,
                date('{date_start}') AS tglproses, {company_id} company_id,
                coalesce(c.doctor_standard_id, a.doctor_analytic_id) doctor_standard_id, 
                coalesce(c.doctor_analytic_id, a.doctor_analytic_id) doctor_analytic_id,  
                coalesce(c.doctor_primary_id, a.doctor_analytic_id) doctor_primary_id, 
                coalesce(c.doctor_perform_id, a.doctor_analytic_id) doctor_perform_id, 
                coalesce(c.doctor_prescribe_id, a.doctor_analytic_id) doctor_prescribe_id, 
                coalesce(c.parent_standard_id, a.parent_analytic_id) parent_standard_id, 
                coalesce(c.parent_analytic_id, a.parent_analytic_id) parent_analytic_id, 
                coalesce(c.parent_primary_id, a.parent_analytic_id) parent_primary_id,
                coalesce(c.parent_perform_id, a.parent_analytic_id) parent_perform_id, 
                coalesce(c.parent_prescribe_id, a.parent_analytic_id) parent_prescribe_id,

                coalesce(c.group_standard_doctor_id, a.group_analytic_id) group_standard_doctor_id,
                coalesce(c.group_standard_spec_id, a.group_analytic_spec_id) group_standard_spec_id,
                coalesce(c.group_standard_subspec_id, a.group_analytic_subspec_id) group_standard_subspec_id, 

                coalesce(c.group_analytic_doctor_id, a.group_analytic_id) group_analytic_doctor_id, 
                coalesce(c.group_analytic_spec_id, a.group_analytic_spec_id) group_analytic_spec_id, 
                coalesce(c.group_analytic_subspec_id, a.group_analytic_subspec_id) group_analytic_subspec_id,

                coalesce(c.group_primary_doctor_id, a.group_analytic_id) group_primary_doctor_id,
                coalesce(c.group_primary_spec_id, a.group_analytic_spec_id) group_primary_spec_id, 
                coalesce(c.group_primary_subspec_id, a.group_analytic_subspec_id) group_primary_subspec_id,

                coalesce(c.group_perform_doctor_id, a.group_analytic_id) group_perform_doctor_id, 
                coalesce(c.group_perform_spec_id, a.group_analytic_spec_id) group_perform_spec_id, 
                coalesce(c.group_perform_subspec_id, a.group_analytic_subspec_id) group_perform_subspec_id, 

                coalesce(c.group_prescribe_doctor_id, a.group_analytic_id) group_prescribe_doctor_id, 
                coalesce(c.group_prescribe_spec_id, a.group_analytic_spec_id) group_prescribe_spec_id, 
                coalesce(c.group_prescribe_subspec_id, a.group_analytic_subspec_id) group_prescribe_subspec_id,

                c.payer_id, c.payer_type, 
                0 price_total, 
                (case
                    when b.fee_total is null and c.fee_amount is null then a.amount 
                    when b.fee_total = 0 then 0 
                    else (c.fee_amount/b.fee_total * (a.amount- coalesce(b.fee_total)) ) 
                end) cost_total, 
                0 other_cost,
                0 material_cost, 
                -- (case when b.fee_total = 0 then 0 else (c.fee_amount/b.fee_total * (a.amount- coalesce(b.fee_total)) ) end) service_cost,
                -- @2024.08.16 update bugs fee dokter THP tidak muncul jika tidak ada fee_line request bu yellie MHTG
                (case
                    when b.fee_total is null and c.fee_amount is null then a.amount 
                    when b.fee_total = 0 then 0 
                    else (c.fee_amount/b.fee_total * (a.amount- coalesce(b.fee_total)) ) 
                end) service_cost,
                0 scrap_cost, 
                ((case
                    when b.fee_total is null and c.fee_amount is null then a.amount 
                    when b.fee_total = 0 then 0 
                    else (c.fee_amount/b.fee_total * (a.amount- coalesce(b.fee_total)) ) 
                end) * -1) margin_total, 
                {user_id} user_id 
            from (
                select 
                    date('{date_start}') tglproses,
                    a.id doctor_fee_id,
                    b."id" doctor_analytic_id,
                    b.parent_id parent_analytic_id, 
                    b.group_doctor_id group_analytic_id,
                    b.group_specialization_id group_analytic_spec_id, 
                    b.group_subspecialization_id group_analytic_subspec_id,  
                    sum(coalesce(a.thp,0) + coalesce(a.pph_21,0) - coalesce(a.other,0)) amount
                from doctor_fee a
                left join account_analytic_account b on b."id" = a.doctor_id 
                where a.year = date_part('year', timestamp '{date_start}')
                    and a.month = date_part('month', timestamp '{date_start}')::text
                    and a.state in('posted','confirmed')
                    and a.company_id = {company_id}
                    -- and a.id = 62416
                    and a.is_pot_total is not True
                group by a.id, 
                    b."id",
                    b.parent_id, 
                    b.group_doctor_id,
                    b.group_specialization_id, 
                    b.group_subspecialization_id
            ) as a 
            left join lateral (
                select sum(dfl.rate) fee_total
                from doctor_fee_line dfl 
                inner join res_partner py on py.id = dfl.odoo_payer_id
                where dfl.doctor_fee_id = a.doctor_fee_id
                    and dfl.company_id = {company_id}
                    and date(dfl.tglproses) >= '{date_start}'
                    and date(dfl.tglproses) <= '{date_end}'
                    and dfl."state" in('confirmed','posted')
            ) b on 1=1
            left join lateral (
                select 
                    dfl.company_id,
                    dfl.odoo_doctor_id doctor_standard_id, 
                    dfl.odoo_doctor_id doctor_analytic_id, 
                    dfl.odoo_primary_id doctor_primary_id, 
                    per.id doctor_perform_id, 
                    pre.id doctor_prescribe_id,
                    aac.parent_id parent_standard_id, 
                    aac.parent_id parent_analytic_id, 
                    pri.parent_id parent_primary_id, 
                    per.parent_id parent_perform_id, 
                    pre.parent_id parent_prescribe_id,

                    coalesce(aac.group_doctor_id, pri.group_doctor_id) group_standard_doctor_id,
                    coalesce(aac.group_specialization_id, pri.group_specialization_id) group_standard_spec_id,
                    coalesce(aac.group_subspecialization_id, pri.group_subspecialization_id) group_standard_subspec_id,

                    aac.group_doctor_id group_analytic_doctor_id,
                    aac.group_specialization_id group_analytic_spec_id,
                    aac.group_subspecialization_id group_analytic_subspec_id,

                    pri.group_doctor_id group_primary_doctor_id,
                    pri.group_specialization_id group_primary_spec_id,
                    pri.group_subspecialization_id group_primary_subspec_id,

                    per.group_doctor_id group_perform_doctor_id,
                    per.group_specialization_id group_perform_spec_id,
                    per.group_subspecialization_id group_perform_subspec_id,

                    pre.group_doctor_id group_prescribe_doctor_id,
                    pre.group_specialization_id group_prescribe_spec_id,
                    pre.group_subspecialization_id group_prescribe_subspec_id,

                    dfl.odoo_payer_id payer_id, dfl.payer_type payer_type,
                    sum(dfl.rate) fee_amount
                from doctor_fee_line dfl 
                inner join res_partner py on py.id = dfl.odoo_payer_id
                left join account_analytic_account aac on aac.id = dfl.odoo_doctor_id
                left join account_analytic_account pri on pri.id = dfl.odoo_primary_id
                left join account_analytic_account per on per.id = coalesce(dfl.odoo_perform_id, dfl.odoo_primary_id)
                left join account_analytic_account pre on pre.id = coalesce(dfl.odoo_prescribe_id, dfl.odoo_primary_id)
                where dfl.doctor_fee_id = a.doctor_fee_id
                    and dfl.company_id = {company_id}
                    and date(dfl.tglproses) >= '{date_start}'
                    and date(dfl.tglproses) <= '{date_end}'
                    and dfl."state" in('confirmed','posted')
                group by dfl.company_id,
                    dfl.odoo_payer_id, dfl.payer_type,
                    dfl.odoo_doctor_id, dfl.odoo_primary_id, 
                    per.id, pre.id, aac.parent_id, 
                    pri.parent_id, per.parent_id, pre.parent_id,

                    coalesce(aac.group_doctor_id, pri.group_doctor_id),
                    coalesce(aac.group_specialization_id, pri.group_specialization_id),
                    coalesce(aac.group_subspecialization_id, pri.group_subspecialization_id),

                    aac.group_doctor_id, aac.group_specialization_id, aac.group_subspecialization_id,
                    pri.group_doctor_id, pri.group_specialization_id, pri.group_subspecialization_id,
                    per.group_doctor_id, per.group_specialization_id, per.group_subspecialization_id,
                    pre.group_doctor_id, pre.group_specialization_id, pre.group_subspecialization_id
                having sum(dfl.rate) <> 0
                
            ) c on 1=1
        """.format(
            company_id=company_id, 
            date_start=date_start, 
            date_end=date_end, 
            user_id=self.env.user.id)
        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))



    

    # @api.multi
    def generate_ledger_new(self):
        report_id = self.id 
        company_id = self.company_id.id 
        date_start = datetime.strptime(str(self.date_start), '%Y-%m-%d').strftime("%Y-%m-%d")
        date_end = datetime.strptime(str(self.date_end), '%Y-%m-%d').strftime("%Y-%m-%d")

        # fetch sharing manual from GL
        query = """
            insert into profitability_analysis(
                type_data, tglproses, company_id,
                doctor_standard_id, doctor_analytic_id, doctor_primary_id, doctor_perform_id, doctor_prescribe_id,
                parent_standard_id, parent_analytic_id, parent_primary_id, parent_perform_id, parent_prescribe_id,
                group_standard_doctor_id, group_standard_spec_id, group_standard_subspec_id,
                group_analytic_doctor_id, group_analytic_spec_id, group_analytic_subspec_id,
                group_primary_doctor_id, group_primary_spec_id, group_primary_subspec_id,
                group_perform_doctor_id, group_perform_spec_id, group_perform_subspec_id,
                group_prescribe_doctor_id, group_prescribe_spec_id, group_prescribe_subspec_id,               
                payer_id, payer_type, price_total, cost_total, other_cost,
                material_cost, service_cost, 
                scrap_cost, margin_total, user_id
            ) 
            select 
                'GL' type_data,
                a.date tglproses, 
                a.company_id,
                b.doctor_id doctor_standard_id, 
                b.doctor_id doctor_analytic_id, 
                b.doctor_id doctor_primary_id, 
                b.doctor_id doctor_perform_id, 
                b.doctor_id doctor_prescribe_id,
                c.parent_id parent_standard_id, 
                c.parent_id parent_analytic_id, 
                c.parent_id parent_primary_id, 
                c.parent_id parent_perform_id, 
                c.parent_id parent_prescribe_id, 

                c.group_doctor_id group_standard_doctor_id,
                c.group_specialization_id group_standard_spec_id,
                c.group_subspecialization_id group_standard_subspec_id,
                    
                c.group_doctor_id group_analytic_doctor_id,
                c.group_specialization_id group_analytic_spec_id,
                c.group_subspecialization_id group_analytic_subspec_id,
                
                c.group_doctor_id group_primary_doctor_id,
                c.group_specialization_id group_primary_spec_id,
                c.group_subspecialization_id group_primary_subspec_id,

                c.group_doctor_id group_perform_doctor_id,
                c.group_specialization_id group_perform_spec_id,
                c.group_subspecialization_id group_perform_subspec_id,

                c.group_doctor_id group_prescribe_doctor_id,
                c.group_specialization_id group_prescribe_spec_id,
                c.group_subspecialization_id group_prescribe_subspec_id,

                b.partner_id payer_id, 
                d.customer_type_wipro payer_type,
                (case when a.type_data='revenue' 
                    then b.sharing_amount else 0 
                end) price_total, 
                0 cost_total, 
                (case when a.type_data='cost' 
                    then b.sharing_amount else 0 
                end) other_cost, 
                0 material_cost, 0 service_cost,
                0 scrap_cost, 
                ((case when a.type_data='cost' 
                    then -1 else 1 end) * b.sharing_amount
                ) margin_total, 
                {user_id} user_id 
            from profitability_ledger a 
            inner join profitability_ledger_line b on b.profitability_id = a.id 
            inner join account_analytic_account c on c.id = b.doctor_id
            left join res_partner d on d.id = b.partner_id
            where a.state = 'confirmed'
                and a.company_id = {company_id}
                and a."date" >= '{date_start}'
                and a."date" <= '{date_end}'
        """.format(
            company_id=company_id, 
            date_start=date_start, 
            date_end=date_end,
            user_id=self.env.user.id)
        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))
        
        
        # automatic ambil dari GL yang bukan jurnal matic untuk koreksi GOR tanpa mapping doctor_id dan payor_id 
        # prorate based on revenue di Billing Analysis 
        # Akun pendapatan, diskon
        query = """
            insert into profitability_analysis(
                type_data, tglproses, company_id,
                doctor_standard_id, doctor_analytic_id, doctor_primary_id, doctor_perform_id, doctor_prescribe_id,
                parent_standard_id, parent_analytic_id, parent_primary_id, parent_perform_id, parent_prescribe_id,
                group_standard_doctor_id, group_standard_spec_id, group_standard_subspec_id,
                group_analytic_doctor_id, group_analytic_spec_id, group_analytic_subspec_id,
                group_primary_doctor_id, group_primary_spec_id, group_primary_subspec_id,
                group_perform_doctor_id, group_perform_spec_id, group_perform_subspec_id,
                group_prescribe_doctor_id, group_prescribe_spec_id, group_prescribe_subspec_id,                
                price_total, cost_total, other_cost, material_cost, service_cost, 
                scrap_cost, margin_total, user_id, account_id,
                payer_id, payer_type
            ) 
            select 
                'GL' type_data,
                a.tglproses, 
                {company_id} company_id,
                c.doctor_standard_id, 
                c.doctor_analytic_id, 
                c.doctor_primary_id, 
                c.doctor_perform_id, 
                c.doctor_prescribe_id,
                c.parent_standard_id, 
                c.parent_analytic_id, 
                c.parent_primary_id, 
                c.parent_perform_id, 
                c.parent_prescribe_id, 

                c.group_standard_doctor_id,
                c.group_standard_spec_id,
                c.group_standard_subspec_id,
                    
                c.group_analytic_doctor_id,
                c.group_analytic_spec_id,
                c.group_analytic_subspec_id,
                
                c.group_primary_doctor_id,
                c.group_primary_spec_id,
                c.group_primary_subspec_id,

                c.group_perform_doctor_id,
                c.group_perform_spec_id,
                c.group_perform_subspec_id,

                c.group_prescribe_doctor_id,
                c.group_prescribe_spec_id,
                c.group_prescribe_subspec_id,

                (a.price_total * (case when b.total_revenue=0 then 1 else c.revenue/b.total_revenue end)) price_total, 
                0 cost_total, 
                0 other_cost, 
                0 material_cost, 
                0 service_cost,
                0 scrap_cost, 
                (a.price_total * (case when b.total_revenue=0 then 1 else c.revenue/b.total_revenue end)) margin_total, 
                {user_id} user_id, a.account_id,
                c.payer_id, c.payer_type
            from (
                select 
                    date('{date_start}') tglproses, 
                    sum(a.balance) balance, 
                    sum(a.credit-a.debit) price_total,
                    a.account_id
                from account_move_line a 
                inner join account_move b on b.id = a.move_id 
                inner join account_journal c on c.id = b.journal_id 
                inner join account_account aa on aa.id = a.account_id
                where c.name->>'en_US' not in(
                        'Sales Revenue Accrual',
                        'Sales Accrual Reversal',
                        'Sales Revenue Bill',
                        'Sales Discount', 
                        'Sales Discount Net Off',
                        'Sales Cost',
                        'Store Consumption Cost',
                        'Memorial Revenue BSL2',
                        'Memorial Cost BSL2',
                        'Memorial Discount BSL2',
                        'Memorial BSL2',
                        'Revenue BSL2',
                        'Cost BSL2',
                        'Discount BSL2'
                    )
                    and b.company_id = {company_id}
                    and b.state = 'posted'
                    and a."date" >= '{date_start}'
                    and a."date" <= '{date_end}'
                    and (left(aa.code, 1) = '4' or left(aa.code, 2) = '52')
                    and a.doctor_id is null 
                    and a.payor_id is null 
                group by a.account_id
            ) as a 
            left join lateral (
                select coalesce(sum(t.price_total),0) total_revenue 
                from profitability_analysis t 
                where t.company_id = {company_id}
                    and t.type_data in('BILL','BILL-CANCEL','ACCRUAL','ACCRUAL-REVERSAL','DISCOUNT','DISCOUNT-CANCEL')
                    and t.tglproses >= '{date_start}'
                    and t.tglproses <= '{date_end}'
            ) b on 1=1
            inner join lateral ( 
                select 
                    date('{date_start}') tglproses, 
                    t.doctor_standard_id, t.doctor_analytic_id, t.doctor_primary_id, 
                    t.doctor_prescribe_id, t.doctor_perform_id,
                    t.parent_standard_id, t.parent_analytic_id, t.parent_primary_id, 
                    t.parent_prescribe_id, t.parent_perform_id,
                    t.group_standard_doctor_id, t.group_analytic_doctor_id, t.group_primary_doctor_id, 
                    t.group_prescribe_doctor_id, t.group_perform_doctor_id, 
                    t.group_standard_spec_id, t.group_analytic_spec_id, t.group_primary_spec_id, 
                    t.group_prescribe_spec_id, t.group_perform_spec_id, 
                    t.group_standard_subspec_id, t.group_analytic_subspec_id, t.group_primary_subspec_id, 
                    t.group_prescribe_subspec_id, t.group_perform_subspec_id,
                    t.payer_id, t.payer_type,
                    sum(t.price_total) revenue   
                from profitability_analysis t 
                where t.company_id = {company_id}
                    and t.type_data in('BILL','BILL-CANCEL','ACCRUAL','ACCRUAL-REVERSAL','DISCOUNT','DISCOUNT-CANCEL')
                    and t.tglproses >= '{date_start}'
                    and t.tglproses <= '{date_end}'
                group by 
                    t.doctor_standard_id, t.doctor_analytic_id, t.doctor_primary_id, 
                    t.doctor_prescribe_id, t.doctor_perform_id,
                    t.parent_standard_id, t.parent_analytic_id, t.parent_primary_id, 
                    t.parent_prescribe_id, t.parent_perform_id,
                    t.group_standard_doctor_id, t.group_analytic_doctor_id, t.group_primary_doctor_id, 
                    t.group_prescribe_doctor_id, t.group_perform_doctor_id, 
                    t.group_standard_spec_id, t.group_analytic_spec_id, t.group_primary_spec_id, 
                    t.group_prescribe_spec_id, t.group_perform_spec_id, 
                    t.group_standard_subspec_id, t.group_analytic_subspec_id, t.group_primary_subspec_id, 
                    t.group_prescribe_subspec_id, t.group_perform_subspec_id,
                    t.payer_id, t.payer_type
            ) c on 1=1 
        """.format(
            company_id=company_id, 
            date_start=date_start, 
            date_end=date_end,
            user_id=self.env.user.id)
        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/profitability_analysis.log', 'a+').write('\n\n ' + str(query))



