class ProfitabilityAnalysisWizard(models.TransientModel):
    _name = 'profitability.analysis.wizard'

    @api.model
    def _get_user_id(self):
        return self.env.user.id

    @api.model
    def _get_company(self):
        return self.env.company.id

    company_id = fields.Many2one('res.company', string="Company", required=False, default=_get_company)
    start_date = fields.Date(string="Start Date", required=True)
    end_date = fields.Date(string="End Date", required=True)
    data_type = fields.Selection([
        # ('group_standard_spec_id','Standard Doctor'),
        ('group_analytic_spec_id','Specialise Analytic'),
        ('group_perform_spec_id','Specialise Perform'),
        ('group_prescribe_spec_id','Specialise Prescribe'),
        ('group_primary_spec_id','Specialise Primary'),
        ('payor_id', 'Payor Name')
    ], string="Data Type", default='group_analytic_spec_id')
    user_id = fields.Many2one('res.users', string="User ID", default=_get_user_id)



    # @api.multi
    def export_report(self):
        action = {}
        action['type'] = 'ir.actions.act_url'
        action['url'] = '/accounting/print_profitability?id=' + str(self.id)
        action['target'] = 'new'
        return action


    # @api.multi
    def show_report(self):
        open('/opt/odoo16/logs/profitability_analysis.log','a+').write('\n' + 'Start')
        action = {}
        action['target'] = 'current'
        
        if self.company_id:
            action['domain'] = "[('tglproses', '>=', '%s'), ('tglproses', '<=', '%s'), ('company_id', '=', %s)]" % (self.start_date, self.end_date, self.company_id.id)
        else:
            action['domain'] = "[('tglproses', '>=', '%s'), ('tglproses', '<=', '%s')]" % (self.start_date, self.end_date)
        
        open('/opt/odoo16/logs/profitability_analysis.log','a+').write('\n' + str(action['domain']) + '\n' + 'domain show report')
        action['type'] = 'ir.actions.act_window'
        action['view_mode'] = 'tree,form,pivot'
        action['view_type'] = 'form'
        action['res_model'] = 'profitability.analysis'
        action['name'] = 'Profitability Analysis Report'
        action['context'] = {
            'view_pivot_id': 'view_profitability_'+self.data_type
        }
        
        action['views'] = [(self.sudo().env.ref('mayapada.view_profitability_'+self.data_type).id, 'pivot'), (False, 'tree'), (False, 'form')]
        return action





