    @api.depends('margin_total')
    def _compute_margin_percent(self):
        open('/opt/odoo16/logs/dudi.log','a+').write('\n\n ' + str(self))
        for rec in self:
            open('/opt/odoo16/logs/dudi.log','a+').write('\n\n ' + str(rec))
            rec.margin_percent = 0.0
            open('/opt/odoo16/logs/dudi.log','a+').write('\n\n ' + str(rec.margin_percent))
        # fetch all records for your model and sum num field value
        # margin_total = sum(self.search([]).mapped('margin_total'))
        # price_total = sum(self.search([]).mapped('price_total'))
        # # Iter on each records to set records_sum
        # for rec in self:
        #     rec.margin_percent = margin_total / price_total * 100.00

    # def _select(self):
    #     select_str = super(ProfitabilityAnalysis, self)._select()
    #     return "%s, %s" % (select_str, 'sum(margin_total)/sum(price_total) as margin_percent')

    def get_query(self, args, apply_ir_rules=False):
        query = self._where_calc(args)
        if apply_ir_rules:
            self._apply_ir_rules(query, 'read')
        from_clause, where_clause, where_clause_params = query.get_sql()
        where_str = where_clause and (" WHERE %s" % where_clause) or ''
        query_str = 'SELECT (sum(margin_total)/coalesce(sum(throughput),1)) patient_spending, (sum(margin_total)/(case when sum(price_total) <> 0 then sum(price_total) else null end) * 100.0) margin_percent FROM ' + from_clause + where_str
        where_clause_params = map(lambda x: "'" + str(x) + "'" , where_clause_params)
        return query_str % tuple(where_clause_params)


    @api.model 
    def read_group(self, domain, fields, groupby, offset=0, limit=None, orderby=False, lazy=True):
        res = super(ProfitabilityAnalysis, self).read_group(domain, fields, groupby, offset=offset, limit=limit, orderby=orderby, lazy=lazy)
        open('/opt/odoo16/logs/log_profitability_domain.log','a+').write('\n' + str(fields))
        
        if 'patient_spending' in fields:
            for line in res:
                if '__domain' in line:
                    # open('/opt/odoo16/logs/log_profitability_domain.log','a+').write('\n' + str(line['__domain']))
                    query = self.get_query(line['__domain'])
                    
                    #open('/opt/odoo16/logs/log_profitability_domain.log','a+').write('\n' + str(query))                    
                    self.env.cr.execute(query)
                    result = self.env.cr.dictfetchone()
                    if result:
                        line['patient_spending'] = result['patient_spending']

        if 'margin_percent' in fields:
            for line in res:
                if '__domain' in line:
                    # open('/opt/odoo16/logs/log_profitability_domain.log','a+').write('\n' + str(line['__domain']))
                    query = self.get_query(line['__domain'])
                    
                    #open('/opt/odoo16/logs/log_profitability_domain.log','a+').write('\n' + str(query))                    
                    self.env.cr.execute(query)
                    result = self.env.cr.dictfetchone()
                    if result:
                        line['margin_percent'] = result['margin_percent'] 

                    # lines = self.search(line['__domain'])
                    # margin_total = 0.0
                    # revenue_total = 0.0
                    # for record in lines:
                    #     revenue_total += record.price_total
                    #     margin_total += record.margin_total
                    # if revenue_total > 0:
                    #     line['margin_percent'] = (margin_total / revenue_total * 100.0)
                    # else:
                    #     line['margin_percent'] = 0.0
        return res


