    # Trigger user click approved button
    # @api.multi
    def approve(self):
        self.function_consol(function="approve_consol")
        record = self.sudo()
        # Jika user blm klik "Ask Approval"
        if record.approve_status == False:
            raise exceptions.ValidationError("Ask for Approve befor Approving this PV - PV %s" %(record.name))
        # Jika tidak ada approval PV yg termapping
        if not record.approve_id:
            raise exceptions.ValidationError("There are no rule defined for this Budget - PV %s" % (record.name))
        
        # Ambil list rules user berdasarkan purchase_approval yg sudah termapping saat pertama buat PV
        # rule_ids = record.approve_id.rule_ids.sorted(key=lambda data: data.sequence)
        rule_ids = self.get_store_rule(approval_id=self.approve_id.id)
        if not rule_ids:
            raise exceptions.ValidationError("There are no rule defined for this Budget - PV %s" % (record.name))
        
        # Jika approve_rule_id not exist, berarti belum ada user yg click "Approved"
        if not self.approve_rule_id:
            # jika position user skrg login ada di parent position rule pertama approval
            # kondisi jika admin yg approved
            if self.env.user.position_id.id in rule_ids[0].position_id.get_parent_ids() or self.env.user.second_position_id.id in rule_ids[0].position_id.get_parent_ids():
                # simpan rule_id flag di model PV
                self.approve_rule_id = rule_ids[0]
                #self.approve_history("Approved by " + self.approve_status)
                record = self.sudo()
                now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                # self.message_post(body='Approved by ' + self.approve_status + ' by ' + self.env.user.name + " at " + now, message_type='notification', content_subtype='plaintext', subtype_xmlid='mail.mt_comment')
                
                # jika next rule_id sudah kosong, berarti approval sudah lengkap
                # rule_id = rule_ids.filtered(lambda data: data.sequence == record.approve_rule_id.sequence + 1):
                rule_id = self.get_next_rule(approval_id=self.approve_id.id, sequence=record.approve_rule_id.sequence)
                if not rule_id:
                    #self.state = 'validate'
                    self.status = 'approved'
                    # self.with_context(approved=True).button_confirm()
            else:
                raise exceptions.ValidationError("You doesn't have authority to approve this Budget - PV %s" % (record.name))
        
        # Jika list rules user tersedia
        else:
            # filter next rule_id
            # rule_id = rule_ids.filtered(lambda data: data.sequence == record.approve_rule_id.sequence + 1)
            rule_id = self.get_next_rule(approval_id=self.approve_id.id, sequence=record.approve_rule_id.sequence)
            if rule_id:
                # jika user position user skrg login ada di list position next rule
                if self.env.user.position_id.id in rule_id.position_id.get_parent_ids() or self.env.user.second_position_id.id in rule_id.position_id.get_parent_ids():
                    # flag current rule has approved
                    self.approve_rule_id = rule_id
                    now = tools.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                    # self.message_post(body='Approved by ' + self.approve_status + ' by ' + self.env.user.name + " at " + now, message_type='notification', content_subtype='plaintext', subtype_xmlid='mail.mt_comment')
                    # self.approve_history("Approved by " + self.approve_status)
                    
                    # jika next rule sudah tidak ada
                    # rule_id = rule_ids.filtered(lambda data: data.sequence == record.approve_rule_id.sequence + 1):
                    rule_id = self.get_next_rule(approval_id=self.approve_id.id, sequence=record.approve_rule_id.sequence)
                    if not rule_id:
                        #self.state = 'validate'
                        self.status = 'approved'
                        # self.with_context(approved=True).button_confirm()
                else:
                    raise exceptions.ValidationError("You doesn't have authority to approve this Budget - PV %s" % (record.name))
            else:
                raise exceptions.ValidationError("There are no Approval anymore for this Budget - PV %s" % (record.name))
        
        # Jika purchase_approval sudah ada flag di model PV
        if self.approve_id:
            # Ambil seluruh list rule_ids urutkan berdasarkan sequence
            # rule_ids = record.approve_id.rule_ids.sorted(key=lambda data: data.sequence)
            rule_ids = self.get_store_rule(approval_id=self.approve_id.id)

            # Jika belum ada user yg approve maka, ambil first rule_id sebagai next_store
            if not self.approve_rule_id:
                self.approve_next_store = rule_ids[0].position_id.name
            # Jika sudah ada yg approve
            else:
                # filter next rule_id
                # rule_id = rule_ids.filtered(lambda data: data.sequence == record.approve_rule_id.sequence + 1)
                rule_id = self.get_next_rule(approval_id=self.approve_id.id, sequence=record.approve_rule_id.sequence)

                if rule_id:
                    # cek sequence ada yg doble atau ngga ?
                    if len(rule_id) > 1:
                        raise exceptions.ValidationError("The sequence in Approval Rule Positions is double! - PV %s" % (record.name))
                    # update next_store sesuai next rule_id
                    self.approve_next_store = rule_id.position_id.name
                else:
                    # Jika next rule_id tidak ada berarti sudah complete
                    self.approve_next_store = "Completed"
                    self.approved_bool = True

        # record.subscribe_approval()
        approval_link = "https://erp.ad.mayapadahospital.com/web?debug#min=1&limit=80&view_type=list&model=account.move&menu_id=565&action=690"
        self.message_post(body='Approved by ' + self.approve_status + ' by ' +self.env.user.name + " at " + now + '\n' +"Please Click This Link To Approve " + approval_link,message_type='notification',content_subtype='plaintext', subtype_id=False)

    # Trigger user click approved button
    # @api.multi
    def approve_consol(self):
        record = self.sudo()
        # Jika user blm klik "Ask Approval"
        if record.approve_status == False:
            raise exceptions.ValidationError("Ask for Approve befor Approving this PV - PV %s" %(record.name))
        # Jika tidak ada approval PV yg termapping
        if not record.approve_id:
            raise exceptions.ValidationError("There are no rule defined for this Budget - PV %s" % (record.name))
        
        # Ambil list rules user berdasarkan purchase_approval yg sudah termapping saat pertama buat PV
        # rule_ids = record.approve_id.rule_ids.sorted(key=lambda data: data.sequence)
        rule_ids = self.get_store_rule(approval_id=self.approve_id.id)

        if not rule_ids:
            raise exceptions.ValidationError("There are no rule defined for this Budget - PV %s" % (record.name))
        
        # Jika approve_rule_id not exist, berarti belum ada user yg click "Approved"
        if not self.approve_rule_id:
            # jika position user skrg login ada di parent position rule pertama approval
            # kondisi jika admin yg approved
            if self.env.user.position_id.id in rule_ids[0].position_id.get_parent_ids() or self.env.user.second_position_id.id in rule_ids[0].position_id.get_parent_ids():
                # simpan rule_id flag di model PV
                self.approve_rule_id = rule_ids[0]
                #self.approve_history("Approved by " + self.approve_status)
                record = self.sudo()
                now = (tools.datetime.now() + tools.timedelta(hours=7)).strftime('%Y-%m-%d %H:%M:%S')
                # self.message_post(body='Approved by ' + self.approve_status + ' by ' + self.env.user.name + " at " + now, message_type='notification', content_subtype='plaintext', subtype_xmlid='mail.mt_comment')
                
                # jika next rule_id sudah kosong, berarti approval sudah lengkap
                # rule_id = rule_ids.filtered(lambda data: data.sequence == record.approve_rule_id.sequence + 1):
                rule_id = self.get_next_rule(approval_id=self.approve_id.id, sequence=record.approve_rule_id.sequence)
                if not rule_id:
                    #self.state = 'validate'
                    self.status = 'approved'
                    # self.with_context(approved=True).button_confirm()
            else:
                raise exceptions.ValidationError("You doesn't have authority to approve this Budget - PV %s" % (record.name))
        
        # Jika list rules user tersedia
        else:
            # filter next rule_id
            # rule_id = rule_ids.filtered(lambda data: data.sequence == record.approve_rule_id.sequence + 1)
            rule_id = self.get_next_rule(approval_id=self.approve_id.id, sequence=record.approve_rule_id.sequence)
            if rule_id:
                # jika user position user skrg login ada di list position next rule
                if self.env.user.position_id.id in rule_id.position_id.get_parent_ids() or self.env.user.second_position_id.id in rule_id.position_id.get_parent_ids():
                    # flag current rule has approved
                    self.approve_rule_id = rule_id
                    now = tools.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                    # self.message_post(body='Approved by ' + self.approve_status + ' by ' + self.env.user.name + " at " + now, message_type='notification', content_subtype='plaintext', subtype_xmlid='mail.mt_comment')
                    # self.approve_history("Approved by " + self.approve_status)
                    
                    # jika next rule sudah tidak ada
                    # rule_id = rule_ids.filtered(lambda data: data.sequence == record.approve_rule_id.sequence + 1):
                    rule_id = self.get_next_rule(approval_id=self.approve_id.id, sequence=record.approve_rule_id.sequence)
                    if not rule_id:
                        #self.state = 'validate'
                        self.status = 'approved'
                        # self.with_context(approved=True).button_confirm()
                else:
                    raise exceptions.ValidationError("You doesn't have authority to approve this Budget - PV %s" % (record.name))
            else:
                raise exceptions.ValidationError("There are no Approval anymore for this Budget - PV %s" % (record.name))
        
        # Jika purchase_approval sudah ada flag di model PV
        if self.approve_id:
            # Ambil seluruh list rule_ids urutkan berdasarkan sequence
            # rule_ids = record.approve_id.rule_ids.sorted(key=lambda data: data.sequence)
            rule_ids = self.get_store_rule(approval_id=self.approve_id.id)

            # Jika belum ada user yg approve maka, ambil first rule_id sebagai next_store
            if not self.approve_rule_id:
                self.approve_next_store = rule_ids[0].position_id.name
            # Jika sudah ada yg approve
            else:
                # filter next rule_id
                # rule_id = rule_ids.filtered(lambda data: data.sequence == record.approve_rule_id.sequence + 1)
                rule_id = self.get_next_rule(approval_id=self.approve_id.id, sequence=record.approve_rule_id.sequence)
                if rule_id:
                    # cek sequence ada yg doble atau ngga ?
                    if len(rule_id) > 1:
                        raise exceptions.ValidationError("The sequence in Approval Rule Positions is double! - PV %s" % (record.name))
                    # update next_store sesuai next rule_id
                    self.approve_next_store = rule_id.position_id.name
                else:
                    # Jika next rule_id tidak ada berarti sudah complete
                    self.approve_next_store = "Completed"
                    self.approved_bool = True

        # record.subscribe_approval()
        approval_link = "https://erp.ad.mayapadahospital.com/web?debug#min=1&limit=80&view_type=list&model=account.move&menu_id=565&action=690"
        self.message_post(body='Approved by ' + self.approve_status + ' by ' +self.env.user.name + " at " + now + '\n' +"Please Click This Link To Approve " + approval_link,message_type='notification',content_subtype='plaintext',subtype_xmlid='mail.mt_comment')


    

    # Auto compute _approval 
    # @api.one
    def _approval(self):
        record = self.sudo()
        planned = self.amount
        approval = self.env['purchase.approval'].sudo()
        self.approve_id = approval.search([('id', 'in', record.type_id.approval_ids.ids),('max_amount', '>=', planned), ('min_amount', '<=', planned)],limit=1)
        if self.approve_id:
            # rule_ids = record.approve_id.rule_ids.sorted(key=lambda data: data.sequence)
            rule_ids = self.get_store_rule(approval_id=self.approve_id.id)
            if not self.approve_rule_id:
                self.approve_next = rule_ids[0].position_id.name
            else:
                # rule_id = rule_ids.filtered(lambda data: data.sequence == record.approve_rule_id.sequence + 1)
                rule_id = self.get_next_rule(approval_id=self.approve_id.id, sequence=record.approve_rule_id.sequence)
                if rule_id:
                    if len(rule_id) > 1:
                        raise exceptions.ValidationError("The sequence in Approval Rule Positions is double!")
                    self.approve_next = rule_id.position_id.name
                    # 2021.04.12 >> tambahan firgi auto-update next_store
                    self.approve_next_store = rule_id.position_id.name
                else:
                    self.approve_next = "Completed"
                    self.approved_bool = True
                    # 2021.04.12 >> tambahan firgi auto-update next_store
                    self.approve_next_store = "Completed"
        else:
            self.approve_next = ""
                    

    # @api.one
    def _status(self):
        if self.approve_next and self.state not in ['cancel', 'posted']:
            if not self.approve_status:
                self.status = 'draft'
            elif not self.approve_next == 'Completed':
                self.status = 'waiting'
            else:
                self.status = 'approved'
        else:
            self.status = self.state
            if self.state == 'cancel':
                self.write({'approve_rule_id': False})


