    # @api.multi
    def subscribe_approval(self):
        self.ensure_one()
        user_ids = self.env['res.users'].sudo().search([('company_ids', '=', self.company_id.id),('position_id.name', '=', self.approve_next_store)])
        if user_ids:
            self.sudo().message_subscribe_users(user_ids=user_ids.ids)
        user_ids2 = self.env['res.users'].sudo().search([('company_ids', '=', self.company_id.id),('position_id.name', '=', self.approve_next)])
        if user_ids2:
            self.sudo().message_subscribe_users(user_ids=user_ids2.ids)


    # @api.one
    def _get_end_approval(self):
        record = self.sudo()
        end_approval = ''
        for at in record.type_id.approval_ids:
            if at.min_amount <= record.amount and at.max_amount >= record.amount:
                for apv in at.rule_ids:
                    if apv.enabled == True: 
                        end_approval = apv.position_id.name
        record.end_approval = end_approval



    # @api.multi
    def assert_balanced(self):
        if not self.ids:
            return True
        prec = self.env['decimal.precision'].precision_get('Account')

        self._cr.execute(
            """\
            SELECT      move_id
            FROM        account_move_line
            WHERE       move_id in %s
            GROUP BY    move_id
            HAVING      abs(sum(debit) - sum(credit)) > %s
            """, (tuple(self.ids), 10**(-max(5, prec))))
        # if len(self._cr.fetchall()) != 0:
        #     raise UserError(_("Cannot create unbalanced journal entry."))
        return True


    # @api.multi
    def button_cancel(self):
        self.function_consol(function="button_cancel_consol")
        self.write({'approve_rule_id': False})
        self.write({'approve_next_store': False})
        self.write({'no_approval': False})
        self.env.cr.execute("SELECT id from account_move_line where (payment_id is not null or referral_id is not null) and statement_id is null and move_id = %s " % self.id)
        check = self.env.cr.dictfetchall()
        if check and not self.env.context.get('payment'):
            raise exceptions.UserError("You can't cancel journal that contain payment voucher. please cancel from payment voucher menu")

        for r in self:
            if r.state == 'posted':
                lock_date = max(r.company_id.period_lock_date,r.company_id.fiscalyear_lock_date)
                if r.date <= lock_date:
                    message = _("You cannot add/modify entries prior to and inclusive of the lock date %s") % (lock_date)
                    raise exceptions.UserError(message)
        return super(AccountMove, self).button_cancel()


    # @api.multi
    def button_cancel_consol(self):
        for move in self:
            if not move.journal_id.update_posted:
                raise UserError(_('You cannot modify a posted entry of this journal.\nFirst you should set the journal to allow cancelling entries.'))
        if self.ids:
            self.check_access_rights('write')
            self.check_access_rule('write')
            self._check_lock_date()
            self._cr.execute('UPDATE account_move '\
                       'SET state=%s '\
                       'WHERE id IN %s', ('draft', tuple(self.ids),))
            self.invalidate_cache()
        self._check_lock_date()

        self.write({'approve_rule_id': False})
        self.write({'approve_next_store': False})
        self.write({'no_approval': False})
        self.env.cr.execute("SELECT id from account_move_line where payment_id is not null and statement_id is null and move_id = %s " % self.id)
        check = self.env.cr.dictfetchall()
        if check and not self.env.context.get('payment'):
            raise exceptions.UserError("You can't cancel journal that contain payment voucher. please cancel from payment voucher menu")

        for r in self:
            if r.state == 'posted':
                lock_date = max(r.company_id.period_lock_date,r.company_id.fiscalyear_lock_date)
                if r.date <= lock_date:
                    message = _("You cannot add/modify entries prior to and inclusive of the lock date %s") % (lock_date)
                    raise exceptions.UserError(message)


    # @api.multi
    def _check_lock_date(self):
        for move in self:
            lock_date = max(move.company_id.period_lock_date,move.company_id.fiscalyear_lock_date)
            if self.user_has_groups('account.group_account_manager'):
                lock_date = move.company_id.fiscalyear_lock_date
            if move.date <= lock_date and move.state == 'posted':
                if self.user_has_groups('account.group_account_manager'):
                    message = _("You cannot add/modify entries prior to and inclusive of the lock date %s") % (lock_date)
                else:
                    message = _("You cannot add/modify entries prior to and inclusive of the lock date %s. Check the company settings or ask someone with the 'Adviser' role") % (lock_date)
                raise UserError(message)
        return True

    # @api.multi
    def action_post_consol(self):
        for r in self:
            query2 = """
                UPDATE account_move_line set trigger_write = false
                WHERE move_id = {self_id}""".format(self_id = r.id)
            self.env.cr.execute(query2)
            if r.sync_consol_id_unit > 0 and r.company_id.sync_consol_type =='main':
                return
                # raise exceptions.UserError(_('You cannot Post Account Move Unit'))

            if not r.no_approval and r.journal_name == 'Payment Voucher':
                if r.approve_next != 'Completed':
                    raise exceptions.ValidationError("Waiting for Approval")
            if not r.no_approval and r.journal_name == 'TRUE':
                if r.approve_next != 'Completed':
                    raise exceptions.ValidationError("Waiting for Approval")

            r.env.cr.execute("SELECT id from account_move_line where payment_id is not null and statement_id is null and move_id = %s " % r.id)
            check = r.env.cr.dictfetchall()
            if check and not r.env.context.get('payment'):
                raise exceptions.UserError("You can't post journal that contain payment voucher. please post from payment voucher menu")

            lock_date = max(r.company_id.period_lock_date,r.company_id.fiscalyear_lock_date)
            if r.date <= lock_date:
                message = _("You cannot add/modify entries prior to and inclusive of the lock date %s") % (lock_date)
                raise exceptions.UserError(message)
            for aml in r.line_ids:
                #if aml.cheque == False:
                if not aml.payment_id:
                    aml.cheque = r.cheque
            if not r.ids:
                return True

            prec = r.env['decimal.precision'].precision_get('Account')

            # r._cr.execute(
            #     """\
            #    SELECT      move_id
            #    FROM        account_move_line
            #    WHERE       move_id in %s
            #    GROUP BY    move_id
            #    HAVING      abs(sum(debit) - sum(credit)) > %s
            # """, (tuple(r.ids), 10**(-max(5, prec))))
            # if len(r._cr.fetchall()) != 0:
            #     raise exceptions.UserError('Journal items not balance. Please check again.')
            # # open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + str((tuple(r.ids), 10**(-max(5, prec))))

            # Set the tolerance to 0.01 directly
            tolerance = 0.01

            r._cr.execute(
                """
                SELECT      move_id
                FROM        account_move_line
                WHERE       move_id in %s
                GROUP BY    move_id
                HAVING      abs(sum(debit) - sum(credit)) > %s
                """, (tuple(r.ids), tolerance))

            if r._cr.fetchall():
                raise exceptions.UserError('Journal items are not balanced (tolerance 0.01). Please check again.')

        return super(AccountMove, self).action_post()


    # @api.multi
    def action_post(self):
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "def action_post account move mayapada 1.0")
        
        for r in self:

            # 2022.04.25 - Check validasi jurnal fee doctor manual untuk feature profitability            
            if r.journal_id.name not in['Fee Doctor Journal'] and r.company_id.profitability_active is True:
                # open('/opt/odoo16/logs/log_move_profitability.log','a+').write('\n\n' + str('masuk sini 1'))
                for line in r.line_ids:
                    # open('/opt/odoo16/logs/log_move_profitability.log','a+').write('\n\n' + str('masuk sini 2'))
                    account_code = line.account_id.code
                    # open('/opt/odoo16/logs/log_move_profitability.log','a+').write('\n\n' + str(account_code[0:2]))  
                    if account_code[0:2] == '51' and not line.doctor_id:
                        # open('/opt/odoo16/logs/log_move_profitability.log','a+').write('\n\n' + str('masuk sini 3'))
                        raise exceptions.UserError(_('Please mapping Account ' + str(line.account_id.code) + ' with specific analytic doctor.'))
            
            query2 = """
                UPDATE account_move_line set trigger_write = false
                WHERE move_id = {self_id}""".format(self_id = r.id)
            self.env.cr.execute(query2)

            if r.sync_consol_id_unit > 0 and r.company_id.sync_consol_type =='main':
                query2 = """
                UPDATE account_move_line set trigger_write = false
                WHERE move_id = {self_id}""".format(self_id = r.id)
                self.env.cr.execute(query2)

                r.function_consol(function="post_consol")
                query = """
                UPDATE account_move set store_state = 'POSTED'
                WHERE id = {self_id}""".format(self_id = r.id)
                self.env.cr.execute(query)
                return
                # raise exceptions.UserError(_('You cannot Post Account Move Unit'))

            if not r.no_approval and r.journal_name == 'Payment Voucher':
                if r.approve_next != 'Completed':
                    raise exceptions.ValidationError("Waiting for Approval")
            if not r.no_approval and r.journal_name == 'TRUE':
                if r.approve_next != 'Completed':
                    raise exceptions.ValidationError("Waiting for Approval")

            r.env.cr.execute("SELECT id from account_move_line where payment_id is not null and statement_id is null and move_id = %s " % r.id)
            check = r.env.cr.dictfetchall()

            if check and not r.env.context.get('payment'):
                raise exceptions.UserError("You can't post journal that contain payment voucher. please post from payment voucher menu")

            lock_date = max(r.company_id.period_lock_date,r.company_id.fiscalyear_lock_date)
            if r.date <= lock_date:
                message = _("You cannot add/modify entries prior to and inclusive of the lock date %s") % (lock_date)
                raise exceptions.UserError(message)
            for aml in r.line_ids:
                #if aml.cheque == False:
                if not aml.payment_id:
                    aml.cheque = r.cheque
            
            if not r.ids:
                return True

            prec = r.env['decimal.precision'].precision_get('Account')

            r._cr.execute(
                """\
               SELECT      move_id
               FROM        account_move_line
               WHERE       move_id in %s
               GROUP BY    move_id
               HAVING      abs(sum(debit) - sum(credit)) > %s
            """, (tuple(r.ids), 10**(-max(5, prec))))
            if len(r._cr.fetchall()) != 0:
                raise exceptions.UserError('Journal items not balance. Please check again.')
            # # open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + str((tuple(r.ids), 10**(-max(5, prec))))

            # Set the tolerance to 0.01 directly
            # tolerance = 0.01

            # r._cr.execute(
            #     """
            #     SELECT      move_id
            #     FROM        account_move_line
            #     WHERE       move_id in %s
            #     GROUP BY    move_id
            #     HAVING      abs(sum(debit) - sum(credit)) > %s
            #     """, (tuple(r.ids), tolerance))

            # if r._cr.fetchall():
            #     raise exceptions.UserError('Journal items are not balanced (tolerance 0.01). Please check again.')


            if not r.stock_picking_id and not r.payment_id and not r.invoice_id and not r.purchase_id:
                cost_center = r.line_ids.mapped('analytic_account_id.id')
                for cc in cost_center:
                    cc_budget_true = self.env['account.analytic.account'].browse(cc).budget_true
                    cc_name = self.env['account.analytic.account'].browse(cc).display_name
                    move_line = r.line_ids.search([('move_id', '=', r.id),('analytic_account_id', '=', cc)])
                    amount_balance = sum(r.balance for r in move_line)
                    if r.company_id.cost_center_active == True:
                        if not r.company_id.cost_center_date or not r.company_id.cost_center_budget_date or not r.date:
                            raise UserError(_("Tanggal tidak boleh kosong."))
                    if r.company_id.cost_center_active == True and r.company_id.cost_center_date <= r.date:
                        budget_used = self.env['crossovered.budget.lines'].sudo().search([
                            ('analytic_account_id', '=', cc),
                            ('crossovered_budget_id.state','in', ['validate','done']),
                            ('date_from', '<=',r.date),
                            ('date_to', '>=',r.date)])
                        if budget_used:
                            budget_used.budget_line_compute_balance()
                            budget = sum(budget.remain_amount for budget in budget_used)
                            budget = budget
                            # exceed = sum(budget.exceed_amount for budget in budget_used)
                            # exceed = exceed
                            # real_budget = budget + exceed
                            real_budget = budget
                            # open('/opt/odoo16/logs/belajar.log', 'a+').write('\n' + "exceed : " + str(exceed))
                            open('/opt/odoo16/logs/belajar.log', 'a+').write('\n' + "budget : " + str(budget))
                            open('/opt/odoo16/logs/belajar.log', 'a+').write('\n' + "real budget : " + str(real_budget))
                            open('/opt/odoo16/logs/belajar.log', 'a+').write('\n' + "amount po : " + str(amount_balance))
                            if cc and amount_balance > real_budget and r.company_id.cost_center_budget_date <= r.date:
                                raise exceptions.ValidationError("Cost center " + cc_name +" exceeds the Total of Budget's Planned Amount" + '\n' + "Current Remaining Budget : " + str(real_budget) + '\n' + "Please Submit Request for Approval Exceed Budget for this PV")


        
            # update master cip di move.line
            if r.cip_id.id and r.id:
                self.env.cr.execute("""
                        UPDATE account_move_line AS mvl SET cip_id={cip_id} 
                        FROM account_move mv
                        WHERE mvl.move_id=mv.id
                            AND mvl.move_id={move_id}
                            AND mv.cip_id IS NOT NULL
                    """.format(company_id=r.company_id.id, cip_id=r.cip_id.id, move_id=r.id))

                
            # res = super(AccountMove, self).action_post()
            res = super(AccountMove, self)

            cost_center = r.line_ids.mapped('analytic_account_id.id')
            for cc in cost_center:
                cc_budget_true = self.env['account.analytic.account'].browse(cc).budget_true
                cc_name = self.env['account.analytic.account'].browse(cc).display_name
                if r.company_id.cost_center_active == True:
                    if not r.company_id.cost_center_date or not r.date:
                        raise UserError(_("Tanggal tidak boleh kosong."))
                if r.company_id.cost_center_active == True and r.company_id.cost_center_date <= r.date:
                    budget_used = self.env['crossovered.budget.lines'].sudo().search([
                        ('analytic_account_id', '=', cc),
                        ('crossovered_budget_id.state','in', ['validate','done']),
                        ('date_from', '<=',r.date),
                        ('date_to', '>=',r.date)])
                    if budget_used:
                        budget_used.budget_line_compute_balance()
                
            return res.write({'state': 'posted'})


        


    # @api.multi
    def action_draft(self):
        self.function_consol(function="action_draft_consol")
        for record in self:
            if record.state == 'cancel':
                record.state = 'draft'
                record.approve_rule_id = False
                record.approve_next_store = False

    # @api.multi
    def action_draft_consol(self):
        for record in self:
            if record.state == 'cancel':
                record.state = 'draft'
                record.approve_rule_id = False
                record.approve_next_store = False
    
    # @api.depends('restrict_mode_hash_table', 'state')
    def _compute_show_reset_to_draft_button(self):
        for move in self:
            move.show_reset_to_draft_button = False
            # move.show_reset_to_draft_button = not move.restrict_mode_hash_table and move.state in ('posted', 'cancel')

    # @api.multi
    def action_cancel_call(self):
        if self.store_state == 'POSTED':
            self.function_consol(function="button_cancel_consol")
            self.approve_rule_id = False
            self.approve_next_store = False
            self.no_approval = False
        else:
            self.function_consol(function="action_cancel_call_consol")
            for record in self:
                if record.state == 'draft':
                    record.approve_rule_id = False
                    record.approve_next_store = False
            record.no_approval = False

    # @api.multi
    def action_cancel_call_consol(self):
        for record in self:
            if record.state == 'draft':
                # record.state = 'cancel'
                record.approve_rule_id = False
                record.approve_next_store = False
        record.no_approval = False

