    # @api.multi
    def _compute_bank_amount(self):
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "account in move mayapada compute check 3.0 : " )
        
        for r in self:
            if r.bank_id:
                if r.amount >= 500000000:
                    r.bank_amount = r.bank_id.bank_charges2
                if r.amount < 500000000:
                    r.bank_amount = r.bank_id.bank_charges
            else:
                r.bank_amount = 0


