    @api.model
    def _create_periodic_journal_accrual_reversal(self,sync_type='1',date=False):
        if not date:
            date = '' + (tools.datetime.now() + tools.timedelta(hours=7) -tools.timedelta(days=1)).strftime('%Y-%m-%d')
        company = self.env['res.company'].search([('sync_type', '=', sync_type)], limit=1)
        company_id = company.id 
        cc_active = company.cost_center_active

        query = """
            SELECT 
                sol.direction, sol.amount, sol.account_label service_label, 
                sol.account_credit_id, sol.account_debit_id, 
                sol.doctor_name, sol.patient_group, sol.service_group,
                sol.service_name, sol.department_id,
                (CASE WHEN sol.direction < 1 
                    THEN COALESCE(sol.analytic_id, 0) 
                    ELSE 0 END) analytic_debit_id,
                (CASE WHEN sol.direction = 1 
                    THEN COALESCE(sol.analytic_id, 0) 
                    ELSE 0 END) analytic_credit_id,
                sol.service_name, sol.department_id
            FROM view_account_sales_accrual_reversal sol 
            WHERE sol.tglproses = '{date}'
                AND sol.sync_type = '{sync_type}'
                AND sol.amount <> 0
            """ .format(date=date, sync_type=sync_type)
        self.env.cr.execute(query)
        lines = self.env.cr.dictfetchall()
        if not lines:
            print ("There are no lines to make journal")
            return

        move_lines = []
        for line in lines:
            # validasi CC 
            if cc_active:
                if not company.cost_center_date or not date:
                    raise UserError(_("Tanggal tidak boleh kosong."))
            if cc_active and company.cost_center_date <= date:
                if not line['analytic_credit_id'] and not line['analytic_debit_id']:
                    raise exceptions.ValidationError("Please mapping analytic account for Service: {category} and Facility: {area} ".format(category=line['service_name'], area=line['department_id']))
            # validasi COA 
            if not line['account_credit_id']:
                raise exceptions.ValidationError("Please mapping credit account for {category}".format(category=line['service_name']))
            if not line['account_debit_id']:
                raise exceptions.ValidationError("Please mapping debit account for {category}".format(category=line['service_name']))
            
            if int(line['analytic_credit_id']) > 0:
                move_lines.append([0, 0, {'name':str(line['service_label']), 'analytic_account_id':int(line['analytic_credit_id']), 'account_id':int(line['account_credit_id']), 'debit':0.0, 'credit':line['amount'] or 0.0, 'map_journal':True, 'map_patient_group':line['patient_group'], 'map_service_group':line['service_group'], 'map_service_name':line['service_name'], 'map_department_name':line['department_id']}])
            else:
                move_lines.append([0, 0, {'name':str(line['service_label']), 'account_id':int(line['account_credit_id']), 'debit':0.0, 'credit':line['amount'] or 0.0}])
            
            if int(line['analytic_debit_id']) > 0:
                move_lines.append([0, 0, {'name':str(line['service_label']), 'analytic_account_id':int(line['analytic_debit_id']), 'account_id':int(line['account_debit_id']), 'credit':0.0, 'debit':line['amount'] or 0.0, 'map_journal':True, 'map_patient_group':line['patient_group'], 'map_service_group':line['service_group'], 'map_service_name':line['service_name'], 'map_department_name':line['department_id']}])
            else:
                move_lines.append([0, 0, {'name':str(line['service_label']), 'account_id':int(line['account_debit_id']), 'credit':0.0, 'debit':line['amount'] or 0.0}])
                
        journal_id = self.env['account.journal'].search([('name', 'ilike', 'Sales Accrual Reversal'),('company_id', '=', company_id)],limit=1).id
        if self.env.user.id == 1:
            move = self.env['account.move'].create({'journal_id':journal_id,'line_ids':move_lines,'date':date, 'ref': 'COST CENTER IMPORT REVENUE of ACCRUAL-REVERSAL as ' + str(date)})
        else:
            move = self.env['account.move'].create({'journal_id':journal_id,'line_ids':move_lines,'date':date, 'ref': 'REVENUE of ACCRUAL-REVERSAL as ' + str(date)})
        open('/opt/odoo16/logs/accrual.log', 'a+').write('\n' + str(move.id))

    
    @api.model
    def _create_periodic_journal_grn(self, sync_type='1', date=False):
        if not date:
            date = '' + (tools.datetime.now() + tools.timedelta(hours=7) - tools.timedelta(days=1)).strftime('%Y-%m-%d')
        # date = '2019-01-31'
        company = self.env['res.company'].search([('sync_type', '=', sync_type)], limit=1).id
        # print "1"
        # 2021.12.31 - update tambahan stock journal PRT (purchase.return) untuk Wipro MHTG & MHJS
        query = """
            SELECT 
                round(sum(
                    (case 
                        when po.is_return is not True and po.name not ilike '%PRT%'
                        then 1 else -1 
                    end) * coalesce(
                    (case 
                        when po.is_return is True or po.name ilike '%PRT%'
                        then abs(a.price_total) 
                        else a.price_total
                    end), 0) 
                )) as total,
                concat('account.account,', b.stock_valuation_id) as account_valuation,
                c.name as service_label,
                d.id as partner,
                e.id as account_payable,
                c.categ_id stock_categ_id,
                po.name as poref
            FROM purchase_order_line a
            LEFT join purchase_order po on a.order_id = po.id
            LEFT join product_category b on a.product_categ_id = b.id 
            --    and a.company_id = b.company_id
            LEFT join product_product z on a.product_id = z.id
            LEFT join product_template c on z.product_tmpl_id = c.id
            LEFT join res_partner d on d.id = a.partner_id
            LEFT join account_account e on e.code like '2102060000' and e.company_id = a.company_id
            where date(coalesce(po.wipro_date, po.date_order)) = '{0}' 
            and a.sync_type = '{1}' 
            and a.is_consignment is not True 
            --and po.name like 'PRC%' 
            and (coalesce(po.sync_id,0) > 0 or coalesce(po.sync_id_api,'') <> '')
            and a.price_subtotal <> 0 
            and b.stock_valuation_id is not null
            and po.name not ilike '%PRC-ODOO%'
            --and po.name not ilike '%PRT%'
            group by account_valuation, 
                service_label, partner, 
                account_payable, poref, stock_categ_id
        """.format(date, sync_type)
        self.env.cr.execute(query)
        # print "2"
        lines = self.env.cr.dictfetchall()
        if not lines:
            print ("There are no lines to make journal")
            return
        move_lines = []
        for line in lines:
            if line['total'] > 0:
                move_lines.append([0, 0, {'name': line['poref'] + " / " + str(line['service_label']), 'partner_id': line['partner'], 'debit': line['total'] or 0.0, 'credit': 0.0,'account_id': int(line['account_valuation'].strip('account.account,')), 'stock_categ_id':line['stock_categ_id'] or None}])
                move_lines.append([0, 0, {'name': line['poref'] + " / " + str(line['service_label']), 'partner_id': line['partner'], 'debit': 0.0, 'credit': line['total'] or 0.0, 'account_id': int(line['account_payable'])}])
            else:
                move_lines.append([0, 0, {'name': line['poref'] + " / " + str(line['service_label']), 'partner_id': line['partner'], 'debit': 0.0, 'credit': abs(line['total']) or 0.0, 'account_id': int(line['account_valuation'].strip('account.account,')), 'stock_categ_id':line['stock_categ_id'] or None}])
                move_lines.append([0, 0, {'name': line['poref'] + " / " + str(line['service_label']), 'partner_id': line['partner'], 'debit': abs(line['total']) or 0.0, 'credit': 0.0, 'account_id': int(line['account_payable'])}])
            # print "3"
        journal = self.env['account.move'].create({'journal_id':self.env['account.journal'].search([('name', 'ilike', 'Stock Journal'), ('company_id', '=', company)], limit=1).id, 'line_ids':move_lines, 'date':date, 'ref':"GRN HIS of" + str(date)})
        # journal.post()
        # print "4"


