class AccountMoveLine(models.Model):  #ini jurnal line items
    _inherit = 'account.move.line'

    sync_type = sync.type
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date
    user_id_cek = fields.Char(string="User ID")
    company_name = fields.Char(string="Company Name")

    sale_id = fields.Many2one('sale.order.line', string="Sales", index=True)
    patient_type = fields.Selection([('1', 'OP'), ('2', 'IP'),('3', 'Emergency'), ('4', 'Daycare'),('5', 'MCU/Pharmacy Issues Only(FO)'), ('6', 'Pharmacy (Direct)'),('0', 'Both')],string='Patient Type',index=True)
    cheque = fields.Char(string="Cheque Number", index=True, tracking=True)
    year_close = fields.Boolean(string="Closing Journal", default=False, index=True)

    move_id = fields.Many2one('account.move', string='Journal Entry', ondelete="cascade", help="The move of this entry line.", index=True, required=False, auto_join=True)
    payment_id = fields.Many2one('account.payment', string="Payment No.", help="Payment that created this entry",copy=False,index=True)
    new_payment_id = fields.Many2one('account.payment', string="New Payment No.", help="Payment that created this entry",copy=False,index=True)

    referral_id = fields.Many2one('referral.fee', string="Referral No.", help="Referral that created this entry",copy=False,index=True)
    covering_id = fields.Many2one('account.coveringletter', string="Letter No.", index=True)
    covering_letter = fields.Char(string="Letter Name", index=True)
    invoice_id = fields.Many2one('account.invoice', string="Invoice No.", index=True)
    invoice_no = fields.Char(string="Invoice Name", index=True)
    advance_id = fields.Many2one('account.advance', string="Advance No.", index=True)
    realization_id = fields.Many2one('account.advance.realization', string="Advance Receipt No.", index=True)
    creditnote_id = fields.Many2one('account.creditnote', string="Credit Note No.", index=True)
    salary_id = fields.Many2one('account.salary', string="Salary Expense No.", index=True)
    salary_deduction_id = fields.Many2one('account.salary.deduction', string="Salary Deduction No.", index=True)
    doctor_fee_id = fields.Many2one('doctor.fee', string="Fee Doctor (Internal)")
    external_fee_id = fields.Many2one('external.fee', string="Fee Doctor (External)")

    doctor_id = fields.Many2one('account.analytic.account', string="Doctor")
    payor_id = fields.Many2one('res.partner', string="Payor")
    profitability_id = fields.Many2one('profitability.ledger', string="Profitability No.")
    analytic_tag_ids = fields.Many2many('account.analytic.tag', string='Analytic Tags')
    currency_id = fields.Many2one('res.currency', string='Currency', required=False)

    # 2021.11.30 - untuk simpan old partner_id dan maturity_date (untuk migrasi AR MHJS karena harus reset due_date dan partner untuk cleareance AR Aging dari jurnal item)
    old_partner_id = fields.Many2one('res.partner', string="Backup Partner")
    old_date_maturity = fields.Date(string="Backup Due Date")

