    @api.model
    def create(self, vals):
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "sini check create account move line 2.0")
        from odoo.tools import DEFAULT_SERVER_DATE_FORMAT, DEFAULT_SERVER_DATETIME_FORMAT
        from datetime import datetime
        import os

        # define now datetime
        now = datetime.now()
        now_formatted = now.strftime("%Y-%m-%d %H:%M:%S")

        # define python timezone
        import pytz
        local = pytz.timezone('Asia/Jakarta')
        log_date = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%Y%m%d")
        log_year = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%Y")
        log_month = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%m")
        log_day = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%d")
        #log_time = datetime.strftime(pytz.utc.localize(datetime.strptime(datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f"),DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local),"%H%M%S.%f")
        log_time =  datetime.strftime(pytz.utc.localize(datetime.now()).astimezone(local) ,"%Y-%m-%d %H:%M:%S.%f")
        log_dir = '/opt/odoo16/logs/consol/' + log_year + '/' + log_month + '/' + log_day + '/' + 'create' + '/' + 'account.move.line' + '/'
        log_name = log_date + '_' + 'create' + '_' + 'account.move.line'
        log_file = log_dir + log_name + '.log'

        log_dir_day = '/opt/odoo16/logs/consol/' + log_year + '/' + log_month + '/' + log_day

        # create dir if not exists
        if not os.path.exists(log_dir):
            os.makedirs(log_dir)
        os.system('echo Mayapada@12345!!! | sudo -S chown -R odoo:odoo ' + log_dir_day)

        message_log = "\n\n================= start ===================\n\ntimelog: " + str(log_time)
        message_log += "\n\nuser: " + self.env.user.login + "\n\n Start Create "

        open(log_file, 'a').write(message_log)
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + str(vals))        
        result = super(AccountMoveLine, self).create(vals)
        # open('/opt/odoo16/logs/log_move_line.log', 'a+').write(str(result.payment_id.id))
        # pastikan bukan journal matic
        if not result.covering_id and not result.payment_id and not result.invoice_id and not result.advance_id and not result.salary_id:
            # jika cost center active dan analytic blm diaktifkan 
            #if result.company_id.cost_center_active:
                #if not result.company_id.cost_center_date or not result.date:
                    #raise UserError(_("Tanggal tidak boleh kosong."))
            if not result.analytic_account_id and result.company_id.cost_center_active and result.company_id.cost_center_date <= result.date:
                account_code = result.account_id.code
                # untuk COA tertentu harus diaktifkan 
                if account_code[:1] in ['4','5','6','7','8','9'] or account_code[:4] in ['120301']:
                    raise exceptions.ValidationError("Account code {code} harus dimapping dengan Cost Center Analytic".format(code=result.account_id.code + " " + result.account_id.name))

        if vals.get('company_id'):
            company_id = self.env['res.company'].search([('id','=',vals.get('company_id'))], limit=1)
            result.sync_type = company_id.sync_type

        if (result.trigger_create == False and result.move_id.journal_id.name =='Payment Voucher') or (result.trigger_create == False and result.move_id.journal_name == 'TRUE'):
            open('/opt/odoo16/logs/test_sync_id_api.log', 'a+').write('\n' + "trigger create account move line")
            result.send_api_consol_company()
        log_time =  datetime.strftime(pytz.utc.localize(datetime.now()).astimezone(local) ,"%Y-%m-%d %H:%M:%S.%f")
        message_log = "\n\n================= start ===================\n\ntimelog: " + str(log_time)
        message_log += "\n\nuser: " + self.env.user.login + "\n\n Create before return" + "\n ID: " +str(result.id)

        open(log_file, 'a').write(message_log)
        return result


