# 2021.08.31 - Salary Expense 
class AccountSalary(models.Model):
    _name = 'account.salary'
    _inherit = ['mail.thread', 'mail.activity.mixin']

    sync_type = sync.type
    sync_date = sync.date
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date

    @api.model
    def _get_company(self):
        return self.env.company.id

    company_id = fields.Many2one('res.company',string="Company",required=True,default=_get_company)
    name = fields.Char(string="Name",readonly=True,store=True,compute='compute_name')
    date = fields.Date(string="Date of Salary")
    journal_id = fields.Many2one('account.journal', string="Journal")
    expense_account_id = fields.Many2one('account.account', string="Expense Account")
    payable_account_id = fields.Many2one('account.account', string="Payable Account")
    amount = fields.Float(string="Amount (IDR)")
    analytic_id = fields.Many2one('account.analytic.account',string="CC Analytic", tracking=True)
    state = fields.Selection([('draft', 'Draft'), ('confirm', 'Confirm'),('cancel', 'Cancel')],'Status',default='draft',index=True,required=True,readonly=True,copy=False,tracking=True)
    move_ids = fields.One2many('account.move','salary_id',string="Journal Entries")
    remarks = fields.Char(string="Remarks")
    
    # @api.multi
    def action_confirm(self):
        for record in self:
            if record.state == 'draft':
                record.state = 'confirm'

                if record.amount >= 0:
                    debit_vals = {'name':"Salary (%s-%s)" %(record.analytic_id.code, record.analytic_id.name), 'analytic_account_id': record.analytic_id.id, 'debit':abs(record.amount),'credit':0.0,'account_id':record.expense_account_id.id}
                    credit_vals = {'name':"Salary (%s-%s)" %(record.analytic_id.code, record.analytic_id.name),'debit':0.0,'credit':abs(record.amount),'account_id':record.payable_account_id.id}                
                    open('/opt/odoo16/logs/salary_expense.log','a+').write('\n' + str(debit_vals) + '\n' + str(credit_vals))

                if record.amount < 0:
                    debit_vals = {'name':"Salary (%s-%s)" %(record.analytic_id.code, record.analytic_id.name),'credit':0.0,'debit':abs(record.amount),'account_id':record.payable_account_id.id}   
                    credit_vals = {'name':"Salary (%s-%s)" %(record.analytic_id.code, record.analytic_id.name), 'analytic_account_id': record.analytic_id.id, 'credit':abs(record.amount),'debit':0.0,'account_id':record.expense_account_id.id}                
                    open('/opt/odoo16/logs/salary_expense.log','a+').write('\n' + str(debit_vals) + '\n' + str(credit_vals))

            vals = {'journal_id': record.journal_id.id, 'date': record.date,'state': 'draft','salary_id': record.id,'line_ids': [(0, 0, debit_vals), (0, 0, credit_vals)]}
            move = self.env['account.move'].create(vals)
            move.action_post()
            open('/opt/odoo16/logs/salary_expense.log','a+').write('\n' + str(move.id))

    @api.model
    def create(self, vals):
        result = super(AccountSalary, self).create(vals)
        result.name = self.env['ir.sequence'].sudo().next_by_code('account.salary.seq')
        return result


    # @api.multi
    def unlink(self):
        for r in self:
            if r.state == 'confirm':
                raise exceptions.ValidationError("Please cancel/set to draft the record before delete")
        return super(AccountSalary, self).unlink()

    # @api.multi
    def action_cancel(self):
        for record in self:
            if record.state == 'confirm':
                record.state = 'draft'
                for move in self.move_ids:
                    move.button_cancel()
                    move.with_context(force_delete=True).unlink()
                    #move.unlink()

    # @api.multi
    def action_draft(self):
        for record in self:
            if record.state not in['draft']:
                record.state = 'draft'

