class SalaryExpenseImportWizard(models.TransientModel):
    _name = "salary.expense.import.wizard"

    @api.model
    def _get_company(self):
        return self.env.company.id

    company_id = fields.Many2one('res.company',string="Company",required=True,default=_get_company)
    upload_file = fields.Binary(string="Upload File")
    filename = fields.Char(string="filename")
    attachment_ids = fields.Many2many(
        comodel_name='ir.attachment',
        string='Attachments')
    uploaded = fields.Boolean()
    account_salary_ids = fields.Many2many('account.salary', relation='account_salary_bulk_update', string="Account Salary", required=False, store=True)


    # @api.multi
    def bulk_update(self):
        if not self.account_salary_ids:
             raise UserError(
                "Account Salary Kosong, Harap Diisi Terlebih Dahulu")
        if self.account_salary_ids:
            for rec in self.account_salary_ids:
                rec.action_confirm()
    
    
    def minimalist_xldate_as_datetime(self, xldate, datemode):

        return (
            datetime(1899, 12, 30)
            + timedelta(days=xldate + 1462 * datemode)
            )


    def upload(self):
        if not self.attachment_ids:
             raise UserError(
                "Attachment Kosong, Harap Diisi Terlebih Dahulu")
        if not self.company_id:
             raise UserError(
                "Company Kosong, Harap Diisi Terlebih Dahulu")
        salah = ""
        baris_salah = ""
        if self.uploaded:
            raise UserError(
                "Data has been processed. \
                Please close and click the same menu to upload again.")
        for attachment in self.attachment_ids:
            wb = open_workbook(
                file_contents=base64.decodebytes(attachment.datas))
            if not wb:
                raise UserError("Please Attach xlsx")
            values = []
            for s in wb.sheets():
                for row in range(s.nrows):
                    col_value = []
                    for col in range(s.ncols):
                        value = (s.cell(row, col).value)
                        col_value.append(value)
                    values.append(col_value)

            line = 1
            baris = 1
            for val in values:
                if line == 1:
                    line += 1
                    continue
                baris += 1

                if not val[0] or not val[1] or not val[2] or not val[3] or not val[4]:
                    raise UserError("Terdapat Data yang kosong pada baris " + str(baris))
                if not val[5]:
                    val[5] = 0
                # company = val[0]
                # company_id = self.env['res.company'].search([('name','=', company)], limit=1)
                analytic_code = val[1]
                analytic_code_id = self.env['account.analytic.account'].search([('code', '=', val[1]), ('company_id','=',self.company_id.id)],limit=1)
                if self.company_id.name in ['Mayapada Hospital Bandung', 'MHJS-Corporate','MHTG-Corporate']:
                    analytic_code = val[1]
                    analytic_code_id = self.env['account.analytic.account'].search([('code', '=', val[1]), ('company_id','=', 8)],limit=1)
                if self.company_id.name not in ['Mayapada Hospital Bandung', 'MHJS-Corporate','MHTG-Corporate']:
                    analytic_code = val[1]
                    analytic_code_id = self.env['account.analytic.account'].search([('code', '=', val[1]), ('company_id','=', self.company_id.id)],limit=1)
                account_debit = val[2]
                account_debit_id = self.env['account.account'].search([('code', '=', int(val[2])), ('company_id','=',self.company_id.id)],limit=1)
                account_credit = val[3]
                account_credit_id = self.env['account.account'].search([('code', '=', int(val[3])), ('company_id','=',self.company_id.id)],limit=1)
                # tanggal = datetime.fromordinal(datetime(1900, 1, 1).toordinal() + int(val[4]) - 2)
                tanggal = self.minimalist_xldate_as_datetime(val[4], 0)
                amount = val[5]
                
                if not analytic_code_id:
                    baris_salah += 'Baris ' + str(baris) + ' - ' + 'Code Analytic Tidak ditemukan' + ",  \n"
                    salah += str(val[1]) + ", "
                elif not account_debit_id:
                    baris_salah += 'Baris ' + str(baris) + ' - ' + 'Account Debit Tidak ditemukan' + ",  \n"
                    salah += str(val[1]) + ", "
                elif not account_credit_id:
                    baris_salah += 'Baris ' + str(baris) + ' - ' + 'Account Credit Tidak ditemukan' + ", \n "
                    salah += str(val[1]) + ", "
                # baris_salah += str(baris) + ' - ' + + ", "
                # salah += str(val[1]) + ", "
                else:
                    search_account_salary = self.env['account.salary'].search([('company_id', '=', self.company_id.id), ('analytic_id','=',analytic_code_id.id),('expense_account_id','=',account_debit_id.id),('payable_account_id','=',account_credit_id.id),('date','=',tanggal)],limit=1)
                    if search_account_salary and search_account_salary.state =='draft':
                        search_account_salary.write({'amount': amount})
                    if search_account_salary and search_account_salary.state !='draft':
                        raise UserError("State " + search_account_salary.name + " must in draft")

                            
                    elif not search_account_salary:
                        lock_date = max(self.company_id.period_lock_date,self.company_id.fiscalyear_lock_date)
                        cek_tanggal = tanggal.strftime("%Y-%m-%d")
                        if str(cek_tanggal) <= str(lock_date):
                            message = _("You cannot add/modify entries prior to and inclusive of the lock date %s") % (lock_date)
                            raise exceptions.UserError(message)
                        journal_id = self.env['account.journal'].search([('is_swb','=', True), ('company_id','=', self.company_id.id)], limit=1)
                        if not journal_id:
                            raise UserError("SWB Journal Not Found")
                        self.env['account.salary'].create({
                                                            'company_id': self.company_id.id,
                                                            'analytic_id':analytic_code_id.id,
                                                            'journal_id': journal_id.id,
                                                            'expense_account_id': account_debit_id.id,
                                                            'payable_account_id': account_credit_id.id,
                                                            'date':tanggal,
                                                            'amount': amount,
                                                        })

                        
                
        self.write({'uploaded': True})
        # self._cr.commit()

        if salah == "":
            self._cr.commit()
            raise UserError("Successfully")
        if salah != "":
            raise UserError("Nomor Baris Salah : \n"  + baris_salah)
        # Success Partial \n


