    # @api.multi
    def _compute_selisih_amount(self):
        for s in self:
            s.selisih_amount_ppn = 0
            s.selisih_amount_dpp = 0
            if s.payment_selection =='dpp':
                if s.dpp_amount > s.amount:
                    s.selisih_amount_dpp = s.dpp_amount - s.amount
                if s.dpp_amount < s.amount:
                    s.selisih_amount_dpp = s.amount - s.dpp_amount
            elif s.payment_selection =='ppn':
                
                if s.ppn_amount > s.amount:
                    s.selisih_amount_ppn = s.ppn_amount - s.amount
                if s.ppn_amount < s.amount:
                    s.selisih_amount_ppn = s.amount - s.ppn_amount
            elif s.payment_selection =='normal':
                s.selisih_amount_ppn = 0
                s.selisih_amount_dpp = 0

    # @api.multi
    def get_next_rule(self, approval_id=None, sequence=1):
        rule_id = None
        if approval_id:
            rule_id = self.sudo().env['purchase.approval.rule'].search([('approval_id','=',approval_id), ('enabled','=', True), ('sequence','>', sequence)], order='sequence asc', limit=1)
        return rule_id

    # @api.multi
    def get_store_rule(self, approval_id=None):
        rule_ids = None
        if approval_id:
            rule_ids = self.sudo().env['purchase.approval.rule'].search([('approval_id','=',approval_id), ('enabled','=', True)], order='sequence asc')
        return rule_ids


