        # # able to create payments
        # transactions = payments_need_tx.sudo()._create_payment_transaction()

        # #res = super(AccountPayment, self - payments_need_tx).action_post()

        # for tx in transactions:  # Process the transactions with a payment by token
        #     tx._send_payment_request()

        # # Post payments for issued transactions
        # transactions._finalize_post_processing()
        # payments_tx_done = payments_need_tx.filtered(
        #     lambda p: p.payment_transaction_id.state == 'done'
        # )
        # #super(AccountPayment, payments_tx_done).action_post()
        # payments_tx_not_done = payments_need_tx.filtered(
        #     lambda p: p.payment_transaction_id.state != 'done'
        # )
        # open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "account_payment post payment base mayapada : " + str(payments_tx_not_done))
        # if payments_tx_not_done:
        #     payments_tx_not_done.action_cancel()

        # if self.payment_type == 'inbound':
        #     self.create_journal()

        if self.payment_type == 'outbound':
            raise exceptions.UserError("Tidak Bisa Confirm Payment Voucher")


        # bawaan odoo10
        if self.sync_consol_id_unit > 0 and self.company_id.sync_consol_type =='main':
            raise exceptions.UserError(_('You cannot Post Account Payment Unit'))
        # LOCK AR
        lock_date = self.env['lock.ar.configuration'].sudo().search([('company_id', '=', self.company_id.id)], limit=1).date
        if self.payment_type == 'inbound' and self.type_receipt_selection == 'AR Receipt':
            if self.payment_date <= lock_date:
                raise exceptions.UserError(_('You cannot add/modify AR record prior to and inclusive of the lock date "%s".') % (lock_date))

        if not self.no_approval and self.partner_type != 'customer':
            if self.approve_next != 'Completed':
                raise exceptions.ValidationError("Waiting for Approval")
        print ("post")


        self = self.with_context(payment=True)
        selisih_adjust = 0
        for rec in self:
            # 2021.08.10 - Tambahan validasi auto-settlement total_receipt vs adjustment per billing
            if self.payment_type == 'inbound' and self.type_receipt_selection == 'AR Receipt' and self.covering_id:
                
                if self.payment_date < self.covering_id.date:
                    raise exceptions.UserError(_('You cannot add/modify receipt prior to and inclusive of covering letter date "%s".') % (self.covering_id.date))

                self._compute_total_receipt_adjustment()
                if self.amount != self.receipt_adjustment:
                    if self.amount > self.receipt_adjustment:
                        selisih_adjust = self.amount - self.receipt_adjustment
                        if selisih_adjust > 1:
                            # validasi total settlement harus sama dengan total receipt amount kalau detail billing diisi
                            if self.billing_sale_ids or self.billing_cob_ids or self.billing_ids:
                                raise UserError("Total settlement per billing tidak sesuai dengan nominal receipt.")
                        
                    if self.receipt_adjustment > self.amount:
                        selisih_adjust = self.receipt_adjustment - self.amount
                        if selisih_adjust > 1:
                            # validasi total settlement harus sama dengan total receipt amount kalau detail billing diisi
                            if self.billing_sale_ids or self.billing_cob_ids or self.billing_ids:
                                raise UserError("Total settlement per billing tidak sesuai dengan nominal receipt.")
                        
                    # # validasi total settlement harus sama dengan total receipt amount kalau detail billing diisi
                    # if self.billing_sale_ids or self.billing_cob_ids or self.billing_ids:
                    #     raise UserError("Total settlement per billing tidak sesuai dengan nominal receipt.")
            
            if rec.journal_created == False:
                raise UserError(_("Please create journal first."))
            if rec.cheque == False:
                raise UserError(_("Please fill no. Cheque."))
            if rec.state != 'draft':
                raise UserError(_("Only a draft payment can be posted. Trying to post a payment in state %s.") % rec.state)
            if any(inv.state != 'open' for inv in rec.invoice_ids):
                raise ValidationError(_("The payment cannot be processed because the invoice is not open!"))
            
            # Use the right sequence to set the name
            if rec.payment_type == 'transfer':
                sequence_code = 'account.payment.transfer'
            else:
                if rec.partner_type == 'customer':
                    if rec.payment_type == 'inbound':
                        sequence_code = 'account.payment.customer.invoice'
                    if rec.payment_type == 'outbound':
                        sequence_code = 'account.payment.customer.refund'
                if rec.partner_type == 'supplier':
                    if rec.payment_type == 'inbound':
                        sequence_code = 'account.payment.supplier.refund'
                    if rec.payment_type == 'outbound':
                        sequence_code = 'account.payment.supplier.invoice'
            rec.name = rec.name
            if not rec.name and rec.payment_type != 'transfer':
                raise UserError(_("You have to define a sequence for %s in your company.") % (sequence_code, ))
            print ("constraint")

            # Create the journal entry
            # amount = rec.amount * (rec.payment_type in ('outbound', 'transfer') and 1 or -1)
            move = rec.move_line_ids
            for ml in move:
                ml.write({'date': rec.payment_date, 'cheque': rec.cheque})
            for m in move.mapped('move_id'):
                m.write({'date': rec.payment_date, 'cheque': rec.cheque})
                m.action_post()
            approval = "Posted By " + rec.env.user.name
            rec.write({'state': 'posted', 'approved_by': approval})

            # In case of a transfer, the first journal entry created debited the source liquidity account and credited
            # the transfer account. Now we debit the transfer account and credit the destination liquidity account.
            # if rec.payment_type == 'transfer':
            #     transfer_credit_aml = move.line_ids.filtered(lambda r: r.account_id == rec.company_id.transfer_account_id)
            #     transfer_debit_aml = rec._create_transfer_entry(amount)
            #     (transfer_credit_aml + transfer_debit_aml).reconcile()

            # print "Create AFR"
            # full_reconcile = {'name': "A " + str(rec.id)}
            self = self.sudo()
            # full_recon = self.env['account.full.reconcile'].create(full_reconcile)

            # if rec.payment_type == 'outbound':

            #     print "Cari Journal payment"
            #     move_line = self.env['account.move.line'].search([('payment_id', '=', self.id), ('debit', '>', 0)], limit=1)
            #     for i in rec.bill_ids:
            #         print "Cari Journal invoice"
            #         invoice_ids = self.env['account.move.line'].search([('move_id', '=', i.move_id.id),('account_id.reconcile', '=', True)])
            #         # if not invoice_ids:
            #         #   raise UserError(_("Please validate the invoice"))
            #         if not move_line:
            #             raise UserError(_("Please create payment journal first"))
            #         if move_line:
            #             for m in move_line:
            #                 print "Cari loop"
            #                 for inv in invoice_ids:
            #                     print "Partial Recon"
            #                     partial_reconcile = {
            #                         'full_reconcile_id': full_recon.id,
            #                         'company_currency_id': i.currency_id.id,
            #                         'company_id': i.company_id.id,
            #                         'amount': abs(i.amount_total),
            #                         'debit_move_id': m.id,
            #                         'credit_move_id': inv.id
            #                     }
            #                     print "bikin Partial Recon"
            #                     # partial_recon = self.env['account.partial.reconcile'].create(partial_reconcile)
            #                     print "write Recon"
            #                     m.write({'full_reconcile_id': full_recon.id,'reconciled': True})
            #                     inv.write({'full_reconcile_id':m.full_reconcile_id.id,'reconciled':True})


            # 2021.09.28 - Firgi update reconcile selain receipt AR
            # Payment based on bills dibuat split di account.move.line per account.invoice
            # Jadi langsung dibuat full reconcile antara COA AP di Jurnal VB & PV
            if rec.bill_ids and rec.type_receipt != 'AR Receipt':
                if rec.bill_ids:
                    for line in rec.bill_ids:
                        # cek dlu invoice line sudah di reconcile blum?
                        invoice_line = self.env['account.move.line'].search([('account_id','=', line.account_id.id), ('move_id', '=', line.move_id.id), ('account_id.reconcile', '=', True)], limit=1)
                        if not invoice_line.full_reconcile_id:
                            full_recon = self.sudo().env['account.full.reconcile'].create({'name': "AI" + str(line.id)})
                            invoice_line.write({'full_reconcile_id': full_recon.id,'reconciled': True})
                        else:
                            full_recon = invoice_line.full_reconcile_id

                        # update reconcile payment_line
                        payment_line = self.env['account.move.line'].search([('payment_id', '=', rec.id), ('invoice_id', '=', line.id)], limit=1)
                        if payment_line:
                            # jika ada perbedaan COA VB vs PV
                            #Komen
                            # if payment_line.account_id.id != line.account_id.id: 
                            #     raise UserError(_("Counterpart not found for Account " + line.account_id.code + ' ' + line.account_id.name))
                            payment_line.write({'full_reconcile_id': full_recon.id,'reconciled': True})
                        cost_center = line.invoice_line_ids.mapped('account_analytic_id.id')
                        for cc in cost_center:
                            cc_budget_true = self.env['account.analytic.account'].browse(cc).budget_true
                            if rec.company_id.cost_center_active == True:
                                if not rec.company_id.cost_center_date or not line.date_invoice:
                                    raise UserError(_("Tanggal tidak boleh kosong."))
                            if rec.company_id.cost_center_active == True and rec.company_id.cost_center_date <= line.date_invoice :
                                budget_used = self.env['crossovered.budget.lines'].sudo().search([
                                    ('analytic_account_id', '=', cc),
                                    ('crossovered_budget_id.state','in', ['validate','done']),
                                    ('date_from', '<=',line.date_invoice),
                                    ('date_to', '>=',line.date_invoice)])
                                if budget_used:
                                    budget_used.budget_line_compute_balance()


            
            # 2021.09.27 - jika AR Receipt di odoo
            if rec.payment_type == 'inbound' and rec.type_receipt_selection == 'AR Receipt':
                # compute balance CL on confirm receipt payment
                if rec.covering_id:
                    if rec.covering_id.sync_id:
                        print("Skip validasi Balance Karena ini data MHCL Wipro.")
                    else:
                        rec.covering_id.total_payment += rec.amount
                        rec.covering_id.total_balance_amount -= rec.amount

                # Jika receipt based on Admission
                if rec.billing_type == 'admission':
                    for bill in rec.billing_ids:
                        bill.sale_order_id.payer_receipt += bill.payer_receipt
                        bill.sale_order_id.payer_balance -= bill.payer_receipt

                # Jika receipt based on billing
                if rec.billing_type == 'bill':
                    for bill in rec.billing_sale_ids:
                        bill.sale_order_bill_id.payer_receipt += bill.payer_receipt
                        bill.sale_order_bill_id.payer_balance -= bill.payer_receipt
                        if (bill.payer_receipt or 0) != 0:
                            bill.sale_order_bill_id.action_history(remark="CONFIRM " + self.name, trans_date=rec.payment_date, receipt_id=rec.id)
            
