    def _synchronize_from_moves(self, changed_fields):
        ''' Update the account.payment regarding its related account.move.
        Also, check both models are still consistent.
        :param changed_fields: A set containing all modified fields on account.move.
        '''
        if self._context.get('skip_account_move_synchronization'):
            return

        for pay in self.with_context(skip_account_move_synchronization=True):

            # After the migration to 14.0, the journal entry could be shared between the account.payment and the
            # account.bank.statement.line. In that case, the synchronization will only be made with the statement line.
            if pay.move_id.statement_line_id:
                continue

            move = pay.move_id
            move_vals_to_write = {}
            payment_vals_to_write = {}

            if 'journal_id' in changed_fields:
                if pay.journal_id.type not in ('bank', 'cash'):
                    raise UserError(_("A payment must always belongs to a bank or cash journal."))

            if 'line_ids' in changed_fields:
                all_lines = move.line_ids
                liquidity_lines, counterpart_lines, writeoff_lines = pay._seek_for_lines()

                open('/opt/odoo16/logs/create_problem.log','a+').write('\n' + 'liquidity_lines : ' + str(liquidity_lines))
                open('/opt/odoo16/logs/create_problem.log','a+').write('\n' + 'counterpart_lines : ' + str(counterpart_lines))
                open('/opt/odoo16/logs/create_problem.log','a+').write('\n' + 'writeoff_lines : ' + str(writeoff_lines))
                
                ########Chaelvin
                # if len(liquidity_lines) != 1:
                #     raise UserError(_(
                #         "Journal Entry %s is not valid. In order to proceed, the journal items must "
                #         "include one and only one outstanding payments/receipts account.",
                #         move.display_name,
                #     ))

                # if len(counterpart_lines) != 1:
                #     raise UserError(_(
                #         "Journal Entry %s is not valid. In order to proceed, the journal items must "
                #         "include one and only one receivable/payable account (with an exception of "
                #         "internal transfers).",
                #         move.display_name,
                #     ))

                # if any(line.currency_id != all_lines[0].currency_id for line in all_lines):
                #     raise UserError(_(
                #         "Journal Entry %s is not valid. In order to proceed, the journal items must "
                #         "share the same currency.",
                #         move.display_name,
                #     ))

                # if any(line.partner_id != all_lines[0].partner_id for line in all_lines):
                #     raise UserError(_(
                #         "Journal Entry %s is not valid. In order to proceed, the journal items must "
                #         "share the same partner.",
                #         move.display_name,
                #     ))

                if counterpart_lines.account_id.account_type == 'asset_receivable':
                    partner_type = 'customer'
                else:
                    partner_type = 'supplier'

                liquidity_amount = liquidity_lines.amount_currency

                move_vals_to_write.update({
                    'currency_id': liquidity_lines.currency_id.id,
                    'partner_id': liquidity_lines.partner_id.id,
                })
                payment_vals_to_write.update({
                    'amount': abs(liquidity_amount),
                    'partner_type': partner_type,
                    'currency_id': liquidity_lines.currency_id.id,
                    'destination_account_id': counterpart_lines.account_id.id,
                    'partner_id': liquidity_lines.partner_id.id,
                })

                # for line in liquidity_lines:
                #     liquidity_amount = line.amount_currency

                #     move_vals_to_write.update({
                #         'currency_id': line.currency_id.id,
                #         'partner_id': line.partner_id.id,
                #     })
                #     payment_vals_to_write.update({
                #         'amount': abs(liquidity_amount),
                #         'partner_type': partner_type,
                #         'currency_id': line.currency_id.id,
                #         'destination_account_id': counterpart_lines.account_id.id,
                #         'partner_id': line.partner_id.id,
                #     })

                if liquidity_amount > 0.0:
                    payment_vals_to_write.update({'payment_type': 'inbound'})
                elif liquidity_amount < 0.0:
                    payment_vals_to_write.update({'payment_type': 'outbound'})

            move.write(move._cleanup_write_orm_values(move, move_vals_to_write))
            pay.write(move._cleanup_write_orm_values(pay, payment_vals_to_write))
            

    def _compute_total_invoices_amount(self):
        """ Compute the sum of the residual of invoices, expressed in the payment currency """
        payment_currency = self.currency_id or self.journal_id.currency_id or self.journal_id.company_id.currency_id or self.env.user.company_id.currency_id
        invoices = self._get_invoices()

        if all(inv.currency_id == payment_currency for inv in invoices):
            total = sum(invoices.mapped('residual_signed'))
        else:
            total = 0
            for inv in invoices:
                if inv.company_currency_id != payment_currency:
                    total += inv.company_currency_id.with_context(date=self.payment_date).compute(inv.residual_company_signed, payment_currency)
                else:
                    total += inv.residual_company_signed
        return abs(total)




    # @api.one
    @api.depends('bill_ids', 'amount', 'payment_date', 'currency_id')
    def _compute_payment_difference(self):
        if len(self.bill_ids) == 0:
            return
        if self.bill_ids[0].type in ['in_invoice', 'out_refund']:
            self.payment_difference = self.amount - self._compute_total_invoices_amount()
        else:
            self.payment_difference = self._compute_total_invoices_amount() - self.amount




   
    @api.depends('invoice_ids', 'payment_type', 'partner_type', 'partner_id')
    def _compute_destination_account_id(self):
        for record in self:
            open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "account payment mayapada compute check 3.0 : " )
            
            if record.invoice_ids:
                record.destination_account_id = record.invoice_ids[0].account_id.id
            elif record.payment_type == 'transfer':
                if not record.company_id.transfer_account_id.id:
                    raise UserError(_('Transfer account not defined on the company.'))
                record.destination_account_id = record.company_id.transfer_account_id.id
            elif record.partner_id:
                if record.partner_type == 'customer':
                    record.destination_account_id = record.partner_id.property_account_receivable_id.id
                else:
                    record.destination_account_id = record.partner_id.property_account_payable_id.id



