    @api.model
    def default_get(self, fields):
        rec = super(AccountPayment, self).default_get(fields)
        bill_commands = rec.get('bill_ids')

        if bill_commands and len(bill_commands) == 1:
            # Parse command untuk dapatkan invoice
            # Format command biasanya: (6, 0, [ids]) atau (4, id, 0)
            invoice_ids = []
            for command in bill_commands:
                if command[0] == 6:  # replace all
                    invoice_ids.extend(command[2])
                elif command[0] == 4:  # link to existing
                    invoice_ids.append(command[1])
                elif command[0] == 0:  # create new
                    invoice_ids.append(command[2].get('id'))

            if invoice_ids:
                invoice = self.env['account.move'].browse(invoice_ids[0])
                rec['communication'] = invoice.ref or invoice.name or invoice.number
                rec['currency_id'] = invoice.currency_id.id
                rec['payment_type'] = invoice.move_type in ('out_invoice', 'in_refund') and 'inbound' or 'outbound'
                rec['partner_type'] = MAP_INVOICE_TYPE_PARTNER_TYPE[invoice.move_type]
                rec['partner_id'] = invoice.partner_id.id
                rec['amount'] = invoice.amount_residual

        return rec

