    # @api.multi
    def unreconcile(self):
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "account payment mayapada compute check 5.0 : " )
        
        """ Set back the payments in 'posted' or 'sent' state, without deleting the journal entries.
            Called when cancelling a bank statement line linked to a pre-registered payment.
        """
        for payment in self:
            if payment.payment_reference:
                payment.write({'state': 'sent'})
            else:
                payment.write({'state': 'posted'})


    # @api.multi
    def cancel(self):
        if self.payment_type =='outbound':
            self.function_consol(function="cancel_consol")
        # LOCK AR
        lock_date = self.env['lock.ar.configuration'].sudo().search([('company_id', '=', self.company_id.id)], limit=1).date
        if str(self.name[0:3]) == 'RCV' and self.payment_type == 'inbound' :
            if self.payment_date <= lock_date:
                raise exceptions.UserError(_('You cannot add/modify AR record prior to and inclusive of the lock date "%s".') % (lock_date))

        self.write({'approve_rule_id': False})
        self = self.with_context(payment=True)
        for record in self:
            if not record.remarks:
                raise exceptions.ValidationError("Fill remarks before cancel")
            record.journal_created = False

            if record.state == 'posted':
                move_lines = self.env['account.move.line'].search([('move_id', '=', self.account_move_id.id),('reconciled', '=', True)])
                if move_lines:
                    for m in move_lines:
                        m.full_reconcile_id.unlink()
                        m.write({'reconciled': False})

            # Update Payment Receipt & Payment Balance By Dudi
            # Jika receipt based on admission
            # 2021.08.19 revisi AR Receipt settlement di Odoo u/ MHJS & MHTG
            if record.payment_type == 'inbound' and record.type_receipt_selection == 'AR Receipt':
                if record.billing_type == 'admission':
                    for bill in record.billing_ids:
                        bill.sale_order_id.payer_balance += bill.payer_receipt
                        bill.sale_order_id.payer_receipt -= bill.payer_receipt
                if record.billing_type == 'bill':
                    for bill in record.billing_sale_ids:
                        bill.sale_order_bill_id.payer_balance += bill.payer_receipt
                        bill.sale_order_bill_id.payer_receipt -= bill.payer_receipt
                        # bill.sale_order_bill_id.action_history(remark="CANCEL " + self.name)
                        if (bill.payer_receipt or 0) != 0:
                            bill.sale_order_bill_id.cancel_history(receipt_id=self.id)
                if record.billing_type == 'cob':
                    for bill in record.billing_cob_ids:
                        bill.sale_order_cob_id.payer_balance += bill.payer_receipt
                        bill.sale_order_cob_id.payer_receipt -= bill.payer_receipt
                        # bill.sale_order_cob_id.action_history(remark="CANCEL " + self.name)
                        if (bill.payer_receipt or 0) != 0:
                            bill.sale_order_cob_id.cancel_history(receipt_id=self.id)
                # Update outstanding balance CL
                if record.covering_id:
                   record.covering_id.total_payment -= record.amount
                   record.covering_id.total_balance_amount += record.amount

        self.state = 'cancel'
        if self.account_move_id:
            self.account_move_id.button_cancel()
            self.account_move_id.unlink()
            # for journal in self.journal_ids:
            #     journal.button_cancel()
            #     journal.unlink()

        return True
        # result = super(AccountPayment, self).action_cancel()
        # raise exceptions.ValidationError(str(result))
        # return super(AccountPayment, self).action_cancel()




    # @api.multi
    def function_consol(self, function=False):
        from odoo.tools import DEFAULT_SERVER_DATE_FORMAT, DEFAULT_SERVER_DATETIME_FORMAT
        from datetime import datetime
        import os

        # define now datetime
        now = datetime.now()
        now_formatted = now.strftime("%Y-%m-%d %H:%M:%S")

        # define python timezone
        import pytz
        local = pytz.timezone('Asia/Jakarta')
        log_date = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%Y%m%d")
        log_year = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%Y")
        log_month = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%m")
        log_day = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%d")
        #log_time = datetime.strftime(pytz.utc.localize(datetime.strptime(datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f"),DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local),"%H%M%S.%f")
        log_time =  datetime.strftime(pytz.utc.localize(datetime.now()).astimezone(local) ,"%Y-%m-%d %H:%M:%S.%f")
        log_dir = '/opt/odoo16/logs/consol/' + log_year + '/' + log_month + '/' + log_day + '/' + 'function' + '/' + 'account.payment' + '/'
        log_name = log_date + '_' + 'function' + '_' + 'account.payment'
        log_file = log_dir + log_name + '.log'

        log_dir_day = '/opt/odoo16/logs/consol/' + log_year + '/' + log_month + '/' + log_day

        # create dir if not exists
        if not os.path.exists(log_dir):
            os.makedirs(log_dir)
        os.system('echo Mayapada@12345!!! | sudo -S chown -R odoo:odoo ' + log_dir_day)

        message_log = "\n\n================= start ===================\n\ntimelog: " + str(log_time)
        message_log += "\n\nuser: " + self.env.user.login + "\n\n Start Function "

        open(log_file, 'a').write(message_log)
        for record in self:
            if record.payment_type == 'outbound':
                consol_active = record.company_id.sync_consol_account_payment
                consol_url = record.company_id.sync_consol_url
                consol_type = record.company_id.sync_consol_type
                consol_id_to = ""
                consol_id_from = ""
                name_function = function
                if consol_active:
                    if consol_type == 'unit':
                        url = consol_url + "/internal_api/call_function/unit/account.payment"
                        consol_id_to = 'sync_consol_id_main'
                        consol_id_from = 'sync_consol_id_unit'
                    if consol_type == 'main':
                        url = consol_url + "/internal_api/call_function/main/account.payment"
                        consol_id_to = 'sync_consol_id_unit'
                        consol_id_from = 'sync_consol_id_main'

                    # self.env.user.auth_api_consol(consol_active=consol_active, url=consol_url, consol_type=consol_type, consol_id_to=consol_id_to, consol_id_from=consol_id_from)
                    login_user = self.env.user.login
                    password_user = self.env.user.password_consol
                    self.env.user.auth_api_consol(login_user=login_user, password_user=password_user, consol_active=consol_active, url=consol_url, consol_type=consol_type, consol_id_to=consol_id_to, consol_id_from=consol_id_from)
                    
                    headers = {}
                    headers['Content-Type'] = 'application/x-www-form-urlencoded'
                    body = {}
                    body['csrf_token'] = self.env.user.token_consol
                    # body['ids'] = self.env.user[consol_id_from]
                    body['ids'] = record.id
                    # body['arguments'] = (new_passwd)
                    query = """
                        update res_users set company_id = (select(id) from res_company where name = '{company_name}') where id = {sync_consol_id_main}
                        """.format(company_name=self.env.user.company_id.name, sync_consol_id_main=int(self.env.user.sync_consol_id_main))
                    body['query'] = query
                    company_name = record.company_id.name
                    sync_consol_id_main = str(self.env.user.login)
                    body['company_name'] = company_name
                    
                    body['user_id'] = sync_consol_id_main
                    body['function'] = name_function
                    cookies = {'session_id': self.env.user.cookies}
                    response_json = requests.post(url=url, headers=headers, data=body, verify=False, cookies=cookies)
                    json_resp = response_json.json()
                    self.env.user.sync_consol_response = json_resp
                    log_time =  datetime.strftime(pytz.utc.localize(datetime.now()).astimezone(local) ,"%Y-%m-%d %H:%M:%S.%f")
                    message_log = "\n\n================= start ===================\n\ntimelog: " + str(log_time)
                    message_log += "\n\nuser: " + self.env.user.login + "\n\n End Function"

                    open(log_file, 'a').write(message_log)

