    # @api.multi
    def create_journal(self):
        partner_tmp = self.partner_id
        amount_tmp = self.amount

        selisih_adjust = 0
        for rec in self:


            if rec.payment_type == 'outbound':
                raise exceptions.UserError("Tidak Bisa Create Journal Payment Voucher")

            if rec.sync_consol_id_unit > 0 and rec.company_id.sync_consol_type =='main':
                raise exceptions.UserError(_('You cannot Create Journal Account Payment Unit'))


            # if rec.payment_type == 'outbound' and rec.approve_next != 'Completed':
            #    raise exceptions.ValidationError("Waiting for Approval")

            if rec.payment_selection =='dpp' and rec.amount != rec.dpp_amount and rec.selisih_amount_dpp > 2:
                raise exceptions.ValidationError("Nominal Amount Harus Sama Dengan Total DPP")
            # if rec.payment_selection =='dpp' and rec.amount > rec.invoice_amount:
            #     raise exceptions.ValidationError("Nominal Amount Tidak Boleh Lebih Besar Dari Invoice Amount")


            if rec.payment_selection =='ppn' and rec.amount != rec.ppn_amount and rec.selisih_amount_ppn > 2:
                raise exceptions.ValidationError("Nominal Amount Harus Sama Dengan Total PPN")
            # if rec.payment_selection =='ppn' and rec.amount > rec.invoice_amount:
            #     raise exceptions.ValidationError("Nominal Amount Tidak Boleh Lebih Besar Dari Invoice Amount")

            if rec.journal_created or rec.account_move_id:
                raise exceptions.ValidationError("Journal has been created before.")

            if rec.name == False or rec.payment_type == 'inbound':
                rec.name = rec.env['ir.sequence'].with_context(ir_sequence_date=rec.payment_date).next_by_code('account.payment.customer.invoice')
            
            # 2021.08.10 - Tambahan validasi auto-settlement total_receipt vs adjustment per billing
            if rec.payment_type == 'inbound' and rec.type_receipt_selection == 'AR Receipt' and rec.covering_id:
                if rec.amount != rec.receipt_adjustment:
                    # raise UserError("Total settlement per billing tidak sesuai dengan nominal receipt.")
                    if self.amount > self.receipt_adjustment:
                        selisih_adjust = self.amount - self.receipt_adjustment
                        if selisih_adjust > 1:
                            # validasi total settlement harus sama dengan total receipt amount kalau detail billing diisi
                            raise UserError("Total settlement per billing tidak sesuai dengan nominal receipt.")
                        
                    if self.receipt_adjustment > self.amount:
                        selisih_adjust = self.receipt_adjustment - self.amount
                        if selisih_adjust > 1:
                            # validasi total settlement harus sama dengan total receipt amount kalau detail billing diisi
                            raise UserError("Total settlement per billing tidak sesuai dengan nominal receipt.")

            # Create the journal entry
            amount = rec.amount * (rec.payment_type in ('outbound', 'transfer') and 1 or -1)
            move = rec._create_payment_entry(amount)

            # In case of a transfer, the first journal entry created debited the source liquidity account and credited
            # the transfer account. Now we debit the transfer account and credit the destination liquidity account.
            if rec.payment_type == 'transfer':
                transfer_credit_aml = move.line_ids.filtered(lambda r: r.account_id == rec.company_id.transfer_account_id)
                transfer_debit_aml = rec._create_transfer_entry(amount)
                (transfer_credit_aml + transfer_debit_aml)

            if rec.covering_letter and rec.move_line_ids:
                for mvl in rec.move_line_ids:
                    mvl.write({'covering_letter': self.covering_letter, 'name': 'Customer Payment: ' + self.name + ' / ' + self.covering_letter})

      
            # rec.write({'journal_created': True,'move_name': move.name,'account_move_id': move.id})
            rec.write({'journal_created': True,'move_name': move.name,'account_move_id': move.id, 'partner_id': partner_tmp, 'amount': amount_tmp})



    def _create_transfer_entry(self, amount):
        """ Create the journal entry corresponding to the 'incoming money' part of an internal transfer, return the reconciliable move line
        """
        aml_obj = self.env['account.move.line'].with_context(check_move_validity=False)
        debit, credit, amount_currency, dummy = aml_obj.with_context(date=self.payment_date).compute_amount_fields(amount, self.currency_id, self.company_id.currency_id)
        amount_currency = self.destination_journal_id.currency_id and self.currency_id.with_context(date=self.payment_date).compute(amount, self.destination_journal_id.currency_id) or 0

        dst_move = self.env['account.move'].create(self._get_move_vals(self.destination_journal_id))

        dst_liquidity_aml_dict = self._get_shared_move_line_vals(debit, credit, amount_currency, dst_move.id)
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "sini check transfer entry 1.1")
        dst_liquidity_aml_dict.update({
            'name': _('Transfer from %s') % self.journal_id.name,
            'account_id': self.destination_journal_id.default_credit_account_id.id,
            'currency_id': self.destination_journal_id.currency_id.id,
            'new_payment_id': self.id,
            'journal_id': self.destination_journal_id.id})
        aml_obj.create(dst_liquidity_aml_dict)

        transfer_debit_aml_dict = self._get_shared_move_line_vals(credit, debit, 0, dst_move.id)
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "sini check transfer entry 1.2")
        transfer_debit_aml_dict.update({
            'name': self.name,
            'new_payment_id': self.id,
            'account_id': self.company_id.transfer_account_id.id,
            'journal_id': self.destination_journal_id.id})
        if self.currency_id != self.company_id.currency_id:
            transfer_debit_aml_dict.update({
                'currency_id': self.currency_id.id,
                'amount_currency': -self.amount,
            })
        transfer_debit_aml = aml_obj.create(transfer_debit_aml_dict)
        dst_move.action_post()
        return transfer_debit_aml





    @api.model
    def _sync_receipt_voucher_company(self, sync_type='1'):
        sync_ids = {int(record.sync_id): int(record.id) for record in self.sudo().search([('sync_type', '=',sync_type), ('sync_id', '>',0)])}
        sync_date = self.sudo().search([('sync_type', '=', sync_type)],order='sync_date desc',limit=1).sync_date
        data = []
        date = '' + (tools.datetime.now() + tools.timedelta(hours=7) - tools.timedelta(days=1)).strftime('%Y-%m-%d')
        # date = '2019-01-31'
        query_receipt = """
            SELECT
                a.BillID as sync_id,
                convert(varchar(10), a.ReceiptDate, 121) AS payment_date,
                a.ReceiptType AS type_receipt,
                a.PatientType AS patient_type,
                a.PaymentName AS payment_name,
                a.Memo AS communication,
                (CASE WHEN a.PayerID Is Null or a.PayerID = 0 Then 918273 Else a.PayerID END) AS partner_id,
                a.ReceiptAmount AS amount,
                a.AdmissionID AS order_id,
                'customer' AS partner_type,
                'draft' AS state,
                a.Tglproses AS tglproses,
                a.LetterNo AS covering_letter,
                a.InvoiceNo AS invoice_no,
                a.ReceiptNo AS receipt_no,
                a.BillNo AS bill_no,
                a.AdmissionNumber AS admission_no,
                'bill' billing_type
            FROM dbo.VRP_OdooReceiptBills a
            WHERE a.tglproses = '%s'
         """ % (date)
        values = ''
        data += sync.get_data(sync.servers.get(sync_type), query_receipt)
        if not data:
            print ("No data available")
            return
        fields_without_id = tuple(
            key for key in self._fields
            if key != 'id' and 'property' not in key and 'ids' not in key
            and self._fields[key].required == True
            and self._fields[key].store == True)
        columns = tuple(key for key in data[0].keys() if key in self._fields and key not in fields_without_id) + ('sync_date', 'sync_type', 'company_id') if data else ()
        fields_without_id += columns
        columns += tuple(key for key in data[0].keys() if key in self._fields and key not in columns) if data else ()
        fields = fields_without_id + ('id', )
        if columns:
            columns += ('id', )
        default_values = {}
        for field in fields:
            if field in columns:
                continue
            default = self._fields[field].default
            if callable(default):
                default = default(self)
            if isinstance(default, models.Model):
                default = default.id
            default_values[field] = default
        now = tools.datetime.now().strftime('%Y%m%d %H:%M:%S')
        default_values['currency_id'] = self.env.user.company_id.currency_id.id
        #uom_id = self.env.ref('product.product_uom_categ_unit').id
        new_sync_ids = []
        for object in data:
            new_sync_ids += [object['sync_id']]
            for value in default_values:
                if value in object:
                    continue
                object[value] = default_values[value]
            # object['state'] = 'draft'
            object['payment_method_id'] = 1
            object['journal_id'] = self.env['account.journal'].search([('sync_type', '=', sync_type)], limit=1).id
            object['payment_type'] = 'inbound'
            object['partner_type'] = 'customer'
            partner_id = object['partner_id']
            object['partner_id'] = self.env['res.partner'].search([('sync_id', '=', object['partner_id']),('sync_type', '=', sync_type), ('customer_wipro', '=', True)], order="id asc", limit=1).id
            if not object['partner_id']:
                open('/opt/odoo16/logs/missing.log', 'a+').write('\n' + str(tools.datetime.now()) + " res.partner with sync_id %s and sync_type %s doesn't exist" % (partner_id, sync_type))
                return
            object['order_id'] = self.env['sale.order'].search([('sync_id', '=', object['order_id']),('sync_type', '=', sync_type)],limit=1).id or None
            object['id'] = 'DEFAULT'
            object['sync_date'] = now
            object['sync_type'], object['company_id'] = sync_type, self.env['res.company'].sudo().search([('sync_type', '=', sync_type)],limit=1).id
            if values:
                values += ', '
            value = False
            for field in fields:
                if value:
                    value += ', '
                else:
                    value = '('
                if field == 'id' and object['id'] == 'DEFAULT':
                    value += object['id']
                    continue
                if type(object[field]) in [str, unicode]:
                    string = object[field]
                    value += "'" + string.replace("'", "''") + "'"
                    continue
                value += sync.json(object[field])
            value += ')'
            values += value
            if not values:
                print ("No Values")
                return
        excluded = sync.remove_unicode(str(tuple('EXCLUDED.' + field for field in fields_without_id))).replace("'", "")
        columns = sync.remove_unicode(str(fields)).replace("'", "")
        columns_without_id = sync.remove_unicode(str(fields_without_id)).replace("'", "")
        query = "INSERT into account_payment %s values %s on conflict (id) do update set %s = %s" % (columns, values, columns_without_id, excluded)
        print (query.encode('utf8'))
        self.env.cr.execute(query)


    @api.model
    def _sync_receipt_voucher_company_manual(self,sync_type='1',date_start='2019-01-01',date_end='2019-01-01'):
        sync_ids = { int(record.sync_id): int(record.id) for record in self.sudo().search([('sync_type', '=',sync_type), ('sync_id', '>',0)])}
        sync_date = self.sudo().search([('sync_type', '=', sync_type)],order='sync_date desc',limit=1).sync_date
        data = []
        date = '' + (tools.datetime.now() + tools.timedelta(hours=7) - tools.timedelta(days=1)).strftime('%Y-%m-%d')
        # date = '2019-01-31'
        query_receipt = """
            SELECT
                a.BillID as sync_id,
                convert(varchar(10), a.ReceiptDate, 121) AS payment_date,
                a.ReceiptType AS type_receipt,
                a.PatientType AS patient_type,
                a.PaymentName AS payment_name,
                a.Memo AS communication,
                (CASE WHEN a.PayerID Is Null or a.PayerID = 0 Then 918273 Else a.PayerID END) AS partner_id,
                a.ReceiptAmount AS amount,
                a.AdmissionID AS order_id,
                'customer' AS partner_type,
                'draft' AS state,
                a.Tglproses AS tglproses,
                a.LetterNo AS covering_letter,
                a.InvoiceNo AS invoice_no,
                a.ReceiptNo AS receipt_no,
                a.BillNo AS bill_no,
                a.AdmissionNumber AS admission_no,
                'bill' billing_type
            FROM dbo.VRP_OdooReceiptBills a
            WHERE a.tglproses >= '%s' and a.tglproses <= '%s'
         """ % (date_start, date_end)
        values = ''
        data += sync.get_data(sync.servers.get(sync_type), query_receipt)
        if not data:
            print ("No data available")
            return
        fields_without_id = tuple(
            key for key in self._fields
            if key != 'id' and 'property' not in key and 'ids' not in key
            and self._fields[key].required == True
            and self._fields[key].store == True)
        columns = tuple(
            key for key in data[0].keys()
            if key in self._fields and key not in fields_without_id) + ('sync_date', 'sync_type', 'company_id') if data else ()
        fields_without_id += columns
        columns += tuple(
            key for key in data[0].keys()
            if key in self._fields and key not in columns) if data else ()
        fields = fields_without_id + ('id', )
        if columns:
            columns += ('id', )
        default_values = {}
        for field in fields:
            if field in columns:
                continue
            default = self._fields[field].default
            if callable(default):
                default = default(self)
            if isinstance(default, models.Model):
                default = default.id
            default_values[field] = default
        now = tools.datetime.now().strftime('%Y%m%d %H:%M:%S')
        default_values['currency_id'] = self.env.user.company_id.currency_id.id
        #uom_id = self.env.ref('product.product_uom_categ_unit').id
        new_sync_ids = []
        for object in data:
            new_sync_ids += [object['sync_id']]
            for value in default_values:
                if value in object:
                    continue
                object[value] = default_values[value]
            # object['state'] = 'draft'
            object['payment_method_id'] = 1
            object['journal_id'] = self.env['account.journal'].search([('sync_type', '=', sync_type)], limit=1).id
            object['payment_type'] = 'inbound'
            object['partner_type'] = 'customer'
            partner_id = object['partner_id']
            object['partner_id'] = self.env['res.partner'].search([('sync_id', '=', object['partner_id']),('sync_type', '=', sync_type), ('customer_wipro', '=', True)], order="id asc", limit=1).id
            if not object['partner_id']:
                open('/opt/odoo16/logs/missing.log', 'a+').write('\n' + str(tools.datetime.now()) +" res.partner with sync_id %s and sync_type %s doesn't exist" % (partner_id, sync_type))
                return
            object['order_id'] = self.env['sale.order'].search([('sync_id', '=', object['order_id']),('sync_type', '=', sync_type)],limit=1).id or None
            object['id'] = 'DEFAULT'
            object['sync_date'] = now
            object['sync_type'], object['company_id'] = sync_type, self.env['res.company'].sudo().search([('sync_type', '=', sync_type)],limit=1).id
            if values:
                values += ', '
            value = False
            for field in fields:
                if value:
                    value += ', '
                else:
                    value = '('
                if field == 'id' and object['id'] == 'DEFAULT':
                    value += object['id']
                    continue
                if type(object[field]) in [str, unicode]:
                    string = object[field]
                    value += "'" + string.replace("'", "''") + "'"
                    continue
                value += sync.json(object[field])
            value += ')'
            values += value
            if not values:
                print ("No Values")
                return
        excluded = sync.remove_unicode(str(tuple('EXCLUDED.' + field for field in fields_without_id))).replace("'", "")
        columns = sync.remove_unicode(str(fields)).replace("'", "")
        columns_without_id = sync.remove_unicode(str(fields_without_id)).replace("'", "")
        query = "INSERT into account_payment %s values %s on conflict (id) do update set %s = %s" % (columns, values, columns_without_id, excluded)
        print (query.encode('utf8'))
        self.env.cr.execute(query)


    # @api.multi
    def unlink(self):
        for r in self:
            r.move_name = False
            r.account_move_id = False
        if any(bool(rec.move_line_ids) for rec in self):
            raise UserError(_("You can not delete a payment that is already posted"))
        return super(AccountPayment, self).unlink()


    # @api.multi
    def action_post_payment(self):
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "def action_post payment 1.0")
        
        if self.sync_consol_id_unit > 0 and self.company_id.sync_consol_type =='main':
            raise exceptions.UserError(_('You cannot Post Account Payment Unit'))
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "def action_post payment 2.0")
        # LOCK AR
        lock_date = self.env['lock.ar.configuration'].sudo().search([('company_id', '=', self.company_id.id)], limit=1).date
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "def action_post payment 3.0")
        if self.payment_type == 'inbound' and self.type_receipt_selection == 'AR Receipt':
            if self.payment_date <= lock_date:
                raise exceptions.UserError(_('You cannot add/modify AR record prior to and inclusive of the lock date "%s".') % (lock_date))

        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "def action_post payment 4.0")
        if not self.no_approval and self.partner_type != 'customer':
            if self.approve_next != 'Completed':
                raise exceptions.ValidationError("Waiting for Approval")
        print ("post")


        self = self.with_context(payment=True)
        selisih_adjust = 0
        open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "def action_post payment 5.0")
        
        for rec in self:
            # 2021.08.10 - Tambahan validasi auto-settlement total_receipt vs adjustment per billing
            if self.payment_type == 'inbound' and self.type_receipt_selection == 'AR Receipt' and self.covering_id:
                
                if self.payment_date < self.covering_id.date:
                    raise exceptions.UserError(_('You cannot add/modify receipt prior to and inclusive of covering letter date "%s".') % (self.covering_id.date))

                self._compute_total_receipt_adjustment()
                if self.amount != self.receipt_adjustment:
                    if self.amount > self.receipt_adjustment:
                        selisih_adjust = self.amount - self.receipt_adjustment
                        if selisih_adjust > 1:
                            # validasi total settlement harus sama dengan total receipt amount kalau detail billing diisi
                            if self.billing_sale_ids or self.billing_cob_ids or self.billing_ids:
                                raise UserError("Total settlement per billing tidak sesuai dengan nominal receipt.")
                        
                    if self.receipt_adjustment > self.amount:
                        selisih_adjust = self.receipt_adjustment - self.amount
                        if selisih_adjust > 1:
                            # validasi total settlement harus sama dengan total receipt amount kalau detail billing diisi
                            if self.billing_sale_ids or self.billing_cob_ids or self.billing_ids:
                                raise UserError("Total settlement per billing tidak sesuai dengan nominal receipt.")
                        
                    # # validasi total settlement harus sama dengan total receipt amount kalau detail billing diisi
                    # if self.billing_sale_ids or self.billing_cob_ids or self.billing_ids:
                    #     raise UserError("Total settlement per billing tidak sesuai dengan nominal receipt.")
            open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "def action_post payment 6.0")
        
            if rec.journal_created == False:
                raise UserError(_("Please create journal first."))
            if rec.cheque == False:
                raise UserError(_("Please fill no. Cheque."))
            if rec.state != 'draft':
                raise UserError(_("Only a draft payment can be posted. Trying to post a payment in state %s.") % rec.state)
            if any(inv.state != 'open' for inv in rec.invoice_ids):
                raise ValidationError(_("The payment cannot be processed because the invoice is not open!"))
            
            # Use the right sequence to set the name
            if rec.payment_type == 'transfer':
                sequence_code = 'account.payment.transfer'
            else:
                if rec.partner_type == 'customer':
                    if rec.payment_type == 'inbound':
                        sequence_code = 'account.payment.customer.invoice'
                    if rec.payment_type == 'outbound':
                        sequence_code = 'account.payment.customer.refund'
                if rec.partner_type == 'supplier':
                    if rec.payment_type == 'inbound':
                        sequence_code = 'account.payment.supplier.refund'
                    if rec.payment_type == 'outbound':
                        sequence_code = 'account.payment.supplier.invoice'
            rec.name = rec.name
            if not rec.name and rec.payment_type != 'transfer':
                raise UserError(_("You have to define a sequence for %s in your company.") % (sequence_code, ))
            print ("constraint")

            # Create the journal entry
            # amount = rec.amount * (rec.payment_type in ('outbound', 'transfer') and 1 or -1)
            open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "def action_post payment 7.0")
        
            move = rec.move_line_ids
            for ml in move:
                ml.write({'date': rec.payment_date, 'cheque': rec.cheque})
            for m in move.mapped('move_id'):
                m.write({'date': rec.payment_date, 'cheque': rec.cheque})
                m.action_post()
                m._post(soft=False)
            approval = "Posted By " + rec.env.user.name
            rec.write({'state': 'posted', 'approved_by': approval})
            open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "def action_post payment 8.0")
        
            # In case of a transfer, the first journal entry created debited the source liquidity account and credited
