            #                     inv.write({'full_reconcile_id':m.full_reconcile_id.id,'reconciled':True})


            # 2021.09.28 - Firgi update reconcile selain receipt AR
            # Payment based on bills dibuat split di account.move.line per account.invoice
            # Jadi langsung dibuat full reconcile antara COA AP di Jurnal VB & PV
            open('/opt/odoo16/logs/jancoks.log', 'a+').write('\n' + "def action_post payment 9.0")
        
            if rec.bill_ids and rec.type_receipt != 'AR Receipt':
                if rec.bill_ids:
                    for line in rec.bill_ids:
                        # cek dlu invoice line sudah di reconcile blum?
                        invoice_line = self.env['account.move.line'].search([('account_id','=', line.account_id.id), ('move_id', '=', line.move_id.id), ('account_id.reconcile', '=', True)], limit=1)
