    # @api.one
    @api.constrains('amount')
    def _check_amount(self):
        if self.amount < 0.0:
            raise ValidationError(_('The payment amount must be strictly positive.'))


    @api.model
    def create(self, vals):
        # raise exceptions.UserError(_(str(vals)))
        from odoo.tools import DEFAULT_SERVER_DATE_FORMAT, DEFAULT_SERVER_DATETIME_FORMAT
        from datetime import datetime
        import os

        # define now datetime
        now = datetime.now()
        now_formatted = now.strftime("%Y-%m-%d %H:%M:%S")

        # define python timezone
        import pytz
        local = pytz.timezone('Asia/Jakarta')
        log_date = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%Y%m%d")
        log_year = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%Y")
        log_month = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%m")
        log_day = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%d")
        #log_time = datetime.strftime(pytz.utc.localize(datetime.strptime(datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f"),DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local),"%H%M%S.%f")
        log_time =  datetime.strftime(pytz.utc.localize(datetime.now()).astimezone(local) ,"%Y-%m-%d %H:%M:%S.%f")
        log_dir = '/opt/odoo16/logs/consol/' + log_year + '/' + log_month + '/' + log_day + '/' + 'create' + '/' + 'account.payment' + '/'
        log_name = log_date + '_' + 'create' + '_' + 'account.payment'
        log_file = log_dir + log_name + '.log'

        log_dir_day = '/opt/odoo16/logs/consol/' + log_year + '/' + log_month + '/' + log_day

        # create dir if not exists
        if not os.path.exists(log_dir):
            os.makedirs(log_dir)
        os.system('echo Mayapada@12345!!! | sudo -S chown -R odoo:odoo ' + log_dir_day)

        message_log = "\n\n================= start ===================\n\ntimelog: " + str(log_time)
        message_log += "\n\nuser: " + self.env.user.login + "\n\n Start Create "

        open(log_file, 'a').write(message_log)
        record = super(AccountPayment, self).create(vals)

        if record.payment_type == 'outbound':
            raise exceptions.UserError("Tidak Bisa Create Payment Voucher")

        self = record
        if vals.get('company_id'):
            company_id = self.env['res.company'].search([('id','=',vals.get('company_id'))], limit=1)
            record.sync_type = company_id.sync_type

        if record.trigger_create == False and record.payment_type == 'outbound':
            open('/opt/odoo16/logs/test_sync_id_api.log', 'a+').write('\n' + "trigger create account payment")
            record.send_api_consol_company()
            for tes_loop in record.cov_line_ids:
                tes_loop.send_api_consol_company()




        if not record.account_analytic_id and record.company_id.cost_center_active and record.company_id.cost_center_date <= record.payment_date:
            if record.writeoff_account_id:
                account_code = record.writeoff_account_id.code
                if (account_code[:1] in ['4','5','6','7','8','9'] and account_code[:4] not in ['6901','6902','5100']):
                    raise exceptions.ValidationError("Account code {code} harus dimapping dengan Cost Center Analytic".format(code=record.writeoff_account_id.code + " " + record.writeoff_account_id.name))





        if self.payment_type == 'transfer':
            sequence_code = 'account.payment.transfer'
        else:
            if self.partner_type == 'customer':
                if self.payment_type == 'inbound':
                    sequence_code = 'account.payment.customer.invoice'
                if self.payment_type == 'outbound':
                    sequence_code = 'account.payment.customer.refund'
            if self.partner_type == 'supplier':
                if self.payment_type == 'inbound':
                    sequence_code = 'account.payment.supplier.refund'
                if self.payment_type == 'outbound':
                    sequence_code = 'account.payment.supplier.invoice'
                    self.name = self.env['ir.sequence'].with_context(ir_sequence_date=self.payment_date).next_by_code(sequence_code)
                    if not self.name and self.payment_type != 'transfer':
                        raise UserError(_("You have to define a sequence for %s in your company.") % (sequence_code, ))
        
        # 2021.08.10 - Tambahan validasi auto-settlement total_receipt vs adjustment per billing
        if self.payment_type == 'inbound' and self.type_receipt_selection == 'AR Receipt' and self.covering_id:
            self.covering_letter = self.covering_id.name
            self._compute_total_receipt_adjustment()
            
        # 2021.04.13 - request bu shanti
        # untuk pembuatan PV tambahkan validasi untuk cek code & no_rek supplier
        if self.payment_type == 'outbound' and self.partner_type == 'supplier':
            if not self.bank_id:
                raise UserError(_("Bank Information for %s must be set before.") % (self.partner_id.name))
            if self.partner_id.vendor_code == '' or self.partner_id.vendor_code == 'BLANK':
                raise UserError(_("Partner code for %s must be set before.") % (self.partner_id.name))

        if self.payment_type == 'inbound' and self.type_receipt_selection == 'AR Receipt':
            self._compute_total_receipt_adjustment()

        self.write({'bill_ids': vals.get('bill_ids')})
        log_time =  datetime.strftime(pytz.utc.localize(datetime.now()).astimezone(local) ,"%Y-%m-%d %H:%M:%S.%f")
        message_log = "\n\n================= start ===================\n\ntimelog: " + str(log_time)
        message_log += "\n\nuser: " + self.env.user.login + "\n\n Create before return" + "\n ID: " +str(record.id)

        open(log_file, 'a').write(message_log)
        return record


