    # @api.multi
    def write(self, vals):
        from odoo.tools import DEFAULT_SERVER_DATE_FORMAT, DEFAULT_SERVER_DATETIME_FORMAT
        from datetime import datetime
        import os

        # define now datetime
        now = datetime.now()
        now_formatted = now.strftime("%Y-%m-%d %H:%M:%S")

        # define python timezone
        import pytz
        local = pytz.timezone('Asia/Jakarta')
        log_date = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%Y%m%d")
        log_year = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%Y")
        log_month = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%m")
        log_day = datetime.strftime(pytz.utc.localize(datetime.strptime(now_formatted, DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local), "%d")
        #log_time = datetime.strftime(pytz.utc.localize(datetime.strptime(datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f"),DEFAULT_SERVER_DATETIME_FORMAT)).astimezone(local),"%H%M%S.%f")
        log_time =  datetime.strftime(pytz.utc.localize(datetime.now()).astimezone(local) ,"%Y-%m-%d %H:%M:%S.%f")
        log_dir = '/opt/odoo16/logs/consol/' + log_year + '/' + log_month + '/' + log_day + '/' + 'write' + '/' + 'account.payment' + '/'
        log_name = log_date + '_' + 'write' + '_' + 'account.payment'
        log_file = log_dir + log_name + '.log'

        log_dir_day = '/opt/odoo16/logs/consol/' + log_year + '/' + log_month + '/' + log_day

        # create dir if not exists
        if not os.path.exists(log_dir):
            os.makedirs(log_dir)
        os.system('echo Mayapada@12345!!! | sudo -S chown -R odoo:odoo ' + log_dir_day)

        message_log = "\n\n================= start ===================\n\ntimelog: " + str(log_time)
        message_log += "\n\nuser: " + self.env.user.login + "\n\n Start Write "

        open(log_file, 'a').write(message_log)
        invoice_amount = self.invoice_amount
        record = super(AccountPayment, self).write(vals)

        if self.payment_type == 'outbound':
            raise exceptions.UserError("Tidak Bisa Edit Payment Voucher")

        if self.env.context.get('amount_updated'):
            return record
        self = self.with_context(amount_updated=True)
        if self.company_id:
            self.sync_type = self.company_id.sync_type


        if not self.account_analytic_id and self.company_id.cost_center_active and self.company_id.cost_center_date <= self.payment_date:
            if self.writeoff_account_id:
                account_code = self.writeoff_account_id.code
                if (account_code[:1] in ['4','5','6','7','8','9'] and account_code[:4] not in ['6901','6902','5100']):
                    raise exceptions.ValidationError("Account code {code} harus dimapping dengan Cost Center Analytic".format(code=self.writeoff_account_id.code + " " + self.writeoff_account_id.name))

        if self.trigger_write == True and self.payment_type == 'outbound':
            open('/opt/odoo16/logs/test_sync_id_api.log', 'a+').write('\n' + "trigger write account payment")
            query = """
            UPDATE account_payment set trigger_write = false
            WHERE id = {self_id}""".format(self_id = self.id)
            self.env.cr.execute(query)
            self.send_api_consol_write_company()

        if self.payment_type == 'inbound' and self.type_receipt_selection == 'AR Receipt':
            self._compute_total_receipt_adjustment()

        if self.journal_created != True:
            if self.payment_selection =='normal':
                if not self.amount:
                    self.amount = self.invoice_amount
                elif self.invoice_amount != invoice_amount:
                    self.amount += self.invoice_amount - invoice_amount
            elif self.payment_selection == 'dpp':
                self.amount = self.dpp_amount
            elif self.payment_selection == 'ppn':
                self.amount = self.ppn_amount
        # self.write({'bill_ids': vals.get('bill_ids')})

        # 2021.08.10 - Tambahan validasi auto-settlement total_receipt vs adjustment per billing
        if self.payment_type == 'inbound' and self.type_receipt_selection == 'AR Receipt' and self.covering_id:
            self._compute_total_receipt_adjustment()

        # 2021.09.28 - Langsung mark as paid invoice saat create payment
        if self.bill_ids:
            for bill in self.bill_ids:
                if bill.residual <= 0 and bill.state == 'open':
                    bill.reconciled = True
                    bill.action_invoice_paid()
        log_time =  datetime.strftime(pytz.utc.localize(datetime.now()).astimezone(local) ,"%Y-%m-%d %H:%M:%S.%f")
        message_log = "\n\n================= start ===================\n\ntimelog: " + str(log_time)
        message_log += "\n\nuser: " + self.env.user.login + "\n\n Write before return" + "\n ID: " +str(self.id)

        open(log_file, 'a').write(message_log)
        return record


