    @api.onchange('sync_type', 'name','payment_type','partner_type','partner_id','journal_id','bank_amount','invoice_amount','amount', 'payment_date','cheque','approved_by','communication','bank_id','type_id','item_type','remarks')
    def onchange_trigger_write(self):
        self.trigger_write = True


    # @api.multi
    def _compute_bank_amount(self):
        for r in self:
            if r.bank_id:
                if r.amount >= 500000000:
                    r.bank_amount = r.bank_id.bank_charges2
                if r.amount < 500000000:
                    r.bank_amount = r.bank_id.bank_charges
            else:
                r.bank_amount = 0


    @api.onchange('bank_id', 'partner_id', 'payment_type')
    def _bank_domain(self):
        res = {}
        if self.partner_id:
        
            res['domain'] = {'bank_id': [('bank_id', '=', self.partner_id.id)]}
        else:
            res['domain'] = {'bank_id': [('bank_id', '=', 9999999999999)]}
        return res


    # @api.multi
    def _compute_payment_amount(self):
        for s in self:
            s.invoice_amount = 0
            s.dpp_amount = 0
            s.ppn_amount = 0
            if s.bill_ids:
                for bill in s.bill_ids:
                    #s.invoice_amount += bill.amount_total_signed
                    s.invoice_amount += bill.residual
                    s.dpp_amount += bill.amount_untaxed
                    s.ppn_amount += bill.ppn
            else:
                s.invoice_amount = 0
                s.dpp_amount = 0
                s.ppn_amount = 0



    # @api.multi
    def _compute_salary_amount(self):

        for s in self:
            s.salary_amount = 0
            s.salary_deduction_amount = 0
            if s.salary_ids:
                for salary in s.salary_ids:
                    s.salary_amount += salary.amount
            if s.salary_deduction_ids:
                for deduction in s.salary_deduction_ids:
                    s.salary_deduction_amount += deduction.amount * -1




    # 2021.09.07 - custom account.move parameter
    def _get_move_vals(self, journal=None):
        """ Return dict to create the payment move
        """
        journal = journal or self.journal_id
        if not journal.sequence_id:
            raise UserError(_('Configuration Error !'), _('The journal %s does not have a sequence, please specify one.') % journal.name)
        if not journal.sequence_id.active:
            raise UserError(_('Configuration Error !'), _('The sequence of journal %s is deactivated.') % journal.name)
        name = self.move_name or journal.with_context(ir_sequence_date=self.payment_date).sequence_id.next_by_id()
        return {
            'name': name,
            'date': self.payment_date,
            'ref': self.communication or '',
            'partner_id': self.partner_id.id or False,
            'payment_id': self.id,
            'bank_id': self.bank_id.id or False,
            'covering_id': self.covering_id and self.covering_id.id or False,
            'covering_letter': self.covering_id.name or False,
            'invoice_id': self.bill_ids and self.bill_ids[0].id or False,
            'invoice_no': self.bill_ids and self.bill_ids[0].name or False,
            'company_id': self.company_id.id,
            'journal_id': journal.id,
            'currency_id': self.company_id.currency_id.id,
        }

    # 2021.09.27 - Firgi
    def _get_shared_move_line_vals(self, debit, credit, amount_currency, move_id, invoice_id=False):
        """ Returns values common to both move lines (except for debit, credit and amount_currency which are reversed)
        """
        return {
            'partner_id': self.payment_type in ('inbound', 'outbound') and self.env['res.partner']._find_accounting_partner(self.partner_id).id or False,
            'invoice_id': invoice_id and invoice_id.id or False,
            'invoice_no': invoice_id and invoice_id.name or False,
            'move_id': move_id,
            'debit': debit,
            'credit': credit,
            'amount_currency': amount_currency or False,
            'date_maturity': invoice_id and invoice_id.date_due or (self.covering_id and self.covering_id.due_date or False),
            'covering_id': self.covering_id and self.covering_id.id or False,
            'covering_letter': self.covering_id and self.covering_id.name or False,
            'currency_id': self.company_id.currency_id.id
        }

