    def _synchronize_to_moves(self, changed_fields):
        ''' Update the account.move regarding the modified account.payment.
        :param changed_fields: A list containing all modified fields on account.payment.
        '''
        # return
        if self._context.get('skip_account_move_synchronization'):
            return

        if not any(field_name in changed_fields for field_name in self._get_trigger_fields_to_synchronize()):
            return

        for pay in self.with_context(skip_account_move_synchronization=True):
            liquidity_lines, counterpart_lines, writeoff_lines = pay._seek_for_lines()

            # Make sure to preserve the write-off amount.
            # This allows to create a new payment with custom 'line_ids'.

            write_off_line_vals = []
            if liquidity_lines and counterpart_lines and writeoff_lines:
                write_off_line_vals.append({
                    'name': writeoff_lines[0].name,
                    'account_id': writeoff_lines[0].account_id.id,
                    'partner_id': writeoff_lines[0].partner_id.id,
                    'currency_id': writeoff_lines[0].currency_id.id,
                    'amount_currency': sum(writeoff_lines.mapped('amount_currency')),
                    'balance': sum(writeoff_lines.mapped('balance')),
                })

            line_vals_list = pay._prepare_move_line_default_vals(write_off_line_vals=write_off_line_vals)

            line_ids_commands = [
                Command.update(liquidity_lines.id, line_vals_list[0]) if liquidity_lines else Command.create(line_vals_list[0]),
                Command.update(counterpart_lines.id, line_vals_list[1]) if counterpart_lines else Command.create(line_vals_list[1])
            ]

            for line in writeoff_lines:
                line_ids_commands.append((2, line.id))

            for extra_line_vals in line_vals_list[2:]:
                line_ids_commands.append((0, 0, extra_line_vals))

            # Update the existing journal items.
            # If dealing with multiple write-off lines, they are dropped and a new one is generated.

            pay.move_id\
                .with_context(skip_invoice_sync=True)\
                .write({
                    'partner_id': pay.partner_id.id,
                    'currency_id': pay.currency_id.id,
                    'partner_bank_id': pay.partner_bank_id.id,
                    'line_ids': line_ids_commands,
                })



    # update dudi 2025-12-01
    def _prepare_move_line_default_vals(self, write_off_line_vals=None):
        # raise exceptions.UserError(str("line_vals_list"))
        ''' Prepare the dictionary to create the default account.move.lines for the current payment.
        :param write_off_line_vals: Optional list of dictionaries to create a write-off account.move.line easily containing:
            * amount:       The amount to be added to the counterpart amount.
            * name:         The label to set on the line.
            * account_id:   The account on which create the write-off.
        :return: A list of python dictionary to be passed to the account.move.line's 'create' method.
        '''
        self.ensure_one()
        write_off_line_vals = write_off_line_vals or {}
        open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + str("DUDI 1"))
        if not self.outstanding_account_id:
            raise UserError(_(
                "You can't create a new payment without an outstanding payments/receipts account set either on the company or the %s payment method in the %s journal.",
                self.payment_method_line_id.name, self.journal_id.display_name))

        open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + str("DUDI 2"))
        # Compute amounts.
        write_off_line_vals_list = write_off_line_vals or []
        write_off_amount_currency = sum(x['amount_currency'] for x in write_off_line_vals_list)
        write_off_balance = sum(x['balance'] for x in write_off_line_vals_list)

        open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + str("DUDI 3"))
        if self.payment_type == 'inbound':
            # Receive money.
            liquidity_amount_currency = self.amount
        elif self.payment_type == 'outbound':
            # Send money.
            liquidity_amount_currency = -self.amount
        else:
            liquidity_amount_currency = 0.0

        open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + str("DUDI 4"))
        liquidity_balance = self.currency_id._convert(
            liquidity_amount_currency,
            self.company_id.currency_id,
            self.company_id,
            self.date,
        )
        counterpart_amount_currency = -liquidity_amount_currency - write_off_amount_currency
        counterpart_balance = -liquidity_balance - write_off_balance
        currency_id = self.currency_id.id

        open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + str("DUDI 5"))
        # Compute a default label to set on the journal items.
        liquidity_line_name = ''.join(x[1] for x in self._get_liquidity_aml_display_name_list())
        counterpart_line_name = ''.join(x[1] for x in self._get_counterpart_aml_display_name_list())

        open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + str("DUDI 6"))
        line_vals_list = [
            # Liquidity line.
            {
                'name': liquidity_line_name,
                'date_maturity': self.date,
                'amount_currency': liquidity_amount_currency,
                'currency_id': currency_id,
                'debit': liquidity_balance if liquidity_balance > 0.0 else 0.0,
                'credit': -liquidity_balance if liquidity_balance < 0.0 else 0.0,
                'partner_id': self.partner_id.id,
                'account_id': self.outstanding_account_id.id,
            },
            # Receivable / Payable.
            {
                'name': counterpart_line_name,
                'date_maturity': self.date,
                'amount_currency': counterpart_amount_currency,
                'currency_id': currency_id,
                'debit': counterpart_balance if counterpart_balance > 0.0 else 0.0,
                'credit': -counterpart_balance if counterpart_balance < 0.0 else 0.0,
                'partner_id': self.partner_id.id,
                # 'account_id': self.destination_account_id.id,
                'account_id': self.destination_account_id.id or (self.partner_id.property_account_payable_id.id if self.partner_type == 'supplier' else self.partner_id.property_account_receivable_id.id),
            },
        ]
        # raise exceptions.UserError(str(line_vals_list + write_off_line_vals_list))
        # return line_vals_list
        return line_vals_list + write_off_line_vals_list


    # 2021.09.27 - Firgi
    def _get_counterpart_move_line_vals(self, invoice=False):
        # raise exceptions.UserError(str("masuk _get_counterpart_move_line_vals"))
        if self.payment_type == 'transfer':
            name = self.name
        else:
            name = ''
            if self.partner_type == 'customer':
                if self.payment_type == 'inbound':
                    name += _("Customer Payment")
                elif self.payment_type == 'outbound':
                    name += _("Customer Refund")
            elif self.partner_type == 'supplier':
                if self.payment_type == 'inbound':
                    name += _("Vendor Refund")
                elif self.payment_type == 'outbound':
                    name += _("Vendor Payment")
            if invoice:
                name += ': '
                for inv in invoice:
                    if inv.move_id:
                        name += inv.number + ', '
                name = name[:len(name)-2] 
        return {
            'name': name,
            'account_id': self.destination_account_id.id or (self.partner_id.property_account_payable_id.id if self.partner_type == 'supplier' else self.partner_id.property_account_receivable_id.id),
            'journal_id': self.journal_id.id,
            'currency_id': self.currency_id != self.company_id.currency_id and self.currency_id.id or False,
            'payment_id': self.id
        }
    # overide account_id di account_move
    @api.depends('journal_id', 'payment_type', 'payment_method_line_id')
    def _compute_outstanding_account_id(self):
        for pay in self:
            if pay.payment_type == 'inbound':
                # pay.outstanding_account_id = (pay.payment_method_line_id.payment_account_id
                #                               or pay.journal_id.company_id.account_journal_payment_debit_account_id)
                pay.outstanding_account_id = self.journal_id.default_account_id.id
            elif pay.payment_type == 'outbound':
                # pay.outstanding_account_id = (pay.payment_method_line_id.payment_account_id
                #                               or pay.journal_id.company_id.account_journal_payment_credit_account_id)
                pay.outstanding_account_id = self.journal_id.default_account_id.id
            else:
                pay.outstanding_account_id = False

    def _get_valid_liquidity_accounts(self):
        return (
            self.journal_id.default_account_id |
            self.payment_method_line_id.payment_account_id |
            self.journal_id.default_credit_account_id |
            self.journal_id.default_debit_account_id |
            self.journal_id.company_id.account_journal_payment_debit_account_id |
            self.journal_id.company_id.account_journal_payment_credit_account_id |
            self.journal_id.inbound_payment_method_line_ids.payment_account_id |
            self.journal_id.outbound_payment_method_line_ids.payment_account_id
        )

    def _get_liquidity_move_line_vals(self, amount):
        name = self.name
        if self.payment_type == 'transfer':
            name = _('Transfer to %s') % self.destination_journal_id.name
        vals = {
            'name': name,
            'account_id': self.payment_type in ('outbound','transfer','inbound') and self.journal_id.default_debit_account_id.id or self.journal_id.default_credit_account_id.id,
            'payment_id': self.id,
            'journal_id': self.journal_id.id,
            'currency_id': self.currency_id != self.company_id.currency_id and self.currency_id.id or False,
        }

        # If the journal has a currency specified, the journal item need to be expressed in this currency
        if self.journal_id.currency_id and self.currency_id != self.journal_id.currency_id:
            amount = self.currency_id.with_context(date=self.payment_date).compute(amount, self.journal_id.currency_id)
            debit, credit, amount_currency, dummy = self.env['account.move.line'].with_context(date=self.payment_date).compute_amount_fields(amount, self.journal_id.currency_id, self.company_id.currency_id)
            vals.update({
                'amount_currency': amount_currency,
                'currency_id': self.journal_id.currency_id.id,
            })

        return vals













    # 2021.09.27 - ubah move.line per invoice bills jika satu  pembayaran berisi beberapa invoice bill sekaligus agar aging bisa ambil dari GL
    def _create_payment_entry(self, amount):

        if self.payment_selection == 'normal':
            """ Create a journal entry corresponding to a payment, if the payment references invoice(s) they are reconciled.
                Return the journal entry.
            """
            if self.move_id:
                if self.move_id.line_ids:
                    self.move_id.line_ids.unlink()

            aml_obj = self.env['account.move.line'].with_context(check_move_validity=False)
            invoice_currency = False
            if self.bill_ids and all([x.currency_id == self.bill_ids[0].currency_id for x in self.bill_ids]):
                #if all the invoices selected share the same currency, record the paiement in that currency too
                invoice_currency = self.bill_ids[0].currency_id
            debit, credit, amount_currency, currency_id = aml_obj.with_context(date=self.payment_date).compute_amount_fields(amount, self.currency_id, self.company_id.currency_id, invoice_currency)
            
            if self.move_id:
                move = self.move_id
                move.write(self._get_move_vals())
            else:
                move = self.env['account.move'].create(self._get_move_vals())
                
            open('/opt/odoo16/logs/account_invoice.log','a+').write('\n')
            open('/opt/odoo16/logs/account_invoice.log','a+').write(str(amount_currency))
            # open('/opt/odoo16/logs/dudi.log','a+').write('currency_id: ' + str(currency_id))
            #open('/opt/odoo16/logs/account_invoice.log','a+').write(str(self._get_move_vals()))


            # Write line corresponding to invoice payment
            # counterpart_aml_dict = self._get_shared_move_line_vals(debit, credit, amount_currency, move.id, False)
            # counterpart_aml_dict.update(self._get_counterpart_move_line_vals(self.bill_ids))
            # counterpart_aml_dict.update({'currency_id': currency_id})
            # counterpart_aml = aml_obj.create(counterpart_aml_dict)

            # 2021.09.27 - Update saldo credit ke AP/AR Agig di split per invoice 
            # total settlement per billing tidak boleh melebihi total amount
            open('/opt/odoo16/logs/account_invoice.log','a+').write('\nReceipt/Payment per bill:')
            open('/opt/odoo16/logs/account_invoice.log','a+').write(' Debit' + str(debit) + 'Credit' + str(credit))

            if self.bill_ids:
                outstanding_debit = abs(amount) if self.payment_type == 'outbound' else 0 
                outstanding_credit = abs(amount) if self.payment_type == 'inbound' else 0 
                
                # jika reconcile payment difference maka full payment per invoice
                if self.payment_difference:
                    if self.payment_difference_handling == 'reconcile':
                        outstanding_debit = outstanding_debit - self.payment_difference if self.payment_type == 'outbound' else 0
                        outstanding_credit = outstanding_credit + self.payment_difference if self.payment_type == 'inbound' else 0               

                counterparts = []
                for bill in self.bill_ids:
                    # open('/opt/odoo16/logs/account_invoice.log','a+').write('\nOutstanding loop:')
                    # open('/opt/odoo16/logs/account_invoice.log','a+').write(str(outstanding_amount))
                    # open('/opt/odoo16/logs/account_invoice.log','a+').write('\nResidual Company Signed:')
                    # open('/opt/odoo16/logs/account_invoice.log','a+').write(str(bill.residual_company_signed))

                    # akumulasi debit 
                    if outstanding_debit >= bill.residual_company_signed:
                        bill_debit = bill.residual_company_signed
                        outstanding_debit -= bill.residual_company_signed
                    else:
                        bill_debit = outstanding_debit
                        outstanding_debit = 0

                    # akumulasi credit 
                    if outstanding_credit >= bill.residual_company_signed:
                        bill_credit = bill.residual_company_signed
                        outstanding_credit -= bill.residual_company_signed
                    else:
                        bill_credit = outstanding_credit
                        outstanding_credit = 0

                    open('/opt/odoo16/logs/account_invoice.log','a+').write('\nReceipt/Payment per bill:')
                    open('/opt/odoo16/logs/account_invoice.log','a+').write(' Debit' + str(bill_debit) + 'credit' + str(bill_credit))

                    if bill_credit > 0 or bill_debit > 0:
                        open('/opt/odoo16/logs/account_invoice.log','a+').write('\n')
                        open('/opt/odoo16/logs/account_invoice.log','a+').write(' Debit' + str(bill_debit) + 'credit' + str(bill_credit))
                        # bill_debit, bill_credit, bill_amount_currency, bill_currency_id = aml_obj.with_context(date=self.payment_date).compute_amount_fields(bill_receipt, self.currency_id, self.company_id.currency_id, invoice_currency)
                        counterpart_aml_dict = self._get_shared_move_line_vals(bill_debit, bill_credit, ((bill_debit-bill_credit) if amount_currency else False), move.id, bill)
                        counterpart_aml_dict.update(self._get_counterpart_move_line_vals(bill))
                        counterpart_aml_dict.update({'currency_id': currency_id})
                        counterpart_aml = aml_obj.create(counterpart_aml_dict)
                        open('/opt/odoo16/logs/account_invoice.log','a+').write('\n')
                        open('/opt/odoo16/logs/account_invoice.log','a+').write(str(counterpart_aml))

                        # reconcile payment vs invoice
                        # bill.register_payment(counterpart_aml)

                # jika reconcile payment difference maka full payment per invoice
                if self.payment_difference and self.payment_difference_handling == 'reconcile':
                    writeoff_line = self._get_shared_move_line_vals(0, 0, 0, move.id, False)
                    amount_currency_wo, currency_id = aml_obj.with_context(date=self.payment_date).compute_amount_fields(self.payment_difference, self.currency_id, self.company_id.currency_id, invoice_currency)[2:]
                    # the writeoff debit and credit must be computed from the invoice residual in company currency
                    # minus the payment amount in company currency, and not from the payment difference in the payment currency
                    # to avoid loss of precision during the currency rate computations. See revision 20935462a0cabeb45480ce70114ff2f4e91eaf79 for a detailed example.
                    total_residual_company_signed = sum(invoice.residual_company_signed for invoice in self.bill_ids)
                    total_payment_company_signed = self.currency_id.with_context(date=self.payment_date).compute(self.amount,self.company_id.currency_id)
                    if self.bill_ids[0].type in ['in_invoice', 'out_refund']:
                        amount_wo = total_payment_company_signed - total_residual_company_signed
                    else:
                        amount_wo = total_residual_company_signed - total_payment_company_signed
                    # Align the sign of the secondary currency writeoff amount with the sign of the writeoff
                    # amount in the company currency
                    if amount_wo > 0:
                        debit_wo = amount_wo
                        credit_wo = 0.0
                        amount_currency_wo = abs(amount_currency_wo)
                    else:
                        debit_wo = 0.0
                        credit_wo = -amount_wo
                        amount_currency_wo = -abs(amount_currency_wo)
                    writeoff_line['name'] = self.name + ' (Counterpart)'
                    writeoff_line['account_id'] = self.writeoff_account_id.id
                    writeoff_line['analytic_account_id'] = self.account_analytic_id.id
                    writeoff_line['debit'] = debit_wo
                    writeoff_line['credit'] = credit_wo
                    writeoff_line['payment_id'] = self.id
                    writeoff_line['amount_currency'] = amount_currency_wo
                    writeoff_line['currency_id'] = currency_id
                    writeoff_line = aml_obj.create(writeoff_line)

            # 2021.09.28 - Jika tidak ada bills/invoice GL gelondongan 
            else:
                counterpart_aml_dict = self._get_shared_move_line_vals(debit, credit, amount_currency, move.id, self.bill_ids and self.bill_ids[0] or False)
                counterpart_aml_dict.update(self._get_counterpart_move_line_vals(self.bill_ids))
                counterpart_aml_dict.update({'currency_id': currency_id})
                # raise exceptions.ValidationError(str(counterpart_aml_dict))
                # xxx
                counterpart_aml = aml_obj.create(counterpart_aml_dict)
                open('/opt/odoo16/logs/account_invoice.log','a+').write('\n')
                open('/opt/odoo16/logs/account_invoice.log','a+').write(str(counterpart_aml))

                # Reconcile with the invoices
                if self.payment_difference_handling == 'reconcile' and self.payment_difference:
                    writeoff_line = self._get_shared_move_line_vals(0, 0, 0, move.id, False)
                    amount_currency_wo, currency_id = aml_obj.with_context(date=self.payment_date).compute_amount_fields(
                            self.payment_difference, self.currency_id,
                            self.company_id.currency_id, invoice_currency)[2:]

                    # the writeoff debit and credit must be computed from the invoice residual in company currency
                    # minus the payment amount in company currency, and not from the payment difference in the payment currency
                    # to avoid loss of precision during the currency rate computations. See revision 20935462a0cabeb45480ce70114ff2f4e91eaf79 for a detailed example.
                    total_residual_company_signed = sum(invoice.residual_company_signed for invoice in self.bill_ids)
                    total_payment_company_signed = self.currency_id.with_context(date=self.payment_date).compute(self.amount,self.company_id.currency_id)
                    if self.bill_ids[0].type in ['in_invoice', 'out_refund']:
                        amount_wo = total_payment_company_signed - total_residual_company_signed
                    else:
                        amount_wo = total_residual_company_signed - total_payment_company_signed

                    # Align the sign of the secondary currency writeoff amount with the sign of the writeoff
                    # amount in the company currency
                    if amount_wo > 0:
                        debit_wo = amount_wo
                        credit_wo = 0.0
                        amount_currency_wo = abs(amount_currency_wo)
                    else:
                        debit_wo = 0.0
                        credit_wo = -amount_wo
                        amount_currency_wo = -abs(amount_currency_wo)

                    writeoff_line['name'] = self.name + ' (Counterpart)'
                    writeoff_line['account_id'] = self.writeoff_account_id.id
                    writeoff_line['analytic_account_id'] = self.account_analytic_id.id
                    writeoff_line['debit'] = debit_wo
                    writeoff_line['credit'] = credit_wo 
                    writeoff_line['payment_id'] = self.id
                    writeoff_line['amount_currency'] = amount_currency_wo
                    writeoff_line['currency_id'] = currency_id
                    writeoff_line = aml_obj.create(writeoff_line)
                    if counterpart_aml['debit']:
                        counterpart_aml['debit'] += credit_wo - debit_wo
                    if counterpart_aml['credit']:
                        counterpart_aml['credit'] += debit_wo - credit_wo
                    counterpart_aml['amount_currency'] -= amount_currency_wo

                self.bill_ids.register_payment(counterpart_aml)


            # Write counterpart lines
            if not self.currency_id != self.company_id.currency_id:
                amount_currency = 0
            # open('/opt/odoo16/logs/dudi.log','a+').write('currency_id: ' + str(currency_id))
            liquidity_aml_dict = self._get_shared_move_line_vals(credit, debit, -amount_currency, move.id, False)
            liquidity_aml_dict.update(self._get_liquidity_move_line_vals(-amount))
            # raise exceptions.ValidationError(str(liquidity_aml_dict))
            # open('/opt/odoo16/logs/dudi.log','a+').write('liquidity_aml_dict: ' + str(liquidity_aml_dict))
            aml_obj.create(liquidity_aml_dict)
            return move

        if self.payment_selection == 'dpp':
            """ Create a journal entry corresponding to a payment, if the payment references invoice(s) they are reconciled.
                Return the journal entry.
            """
            if self.move_id:
                if self.move_id.line_ids:
                    self.move_id.line_ids.unlink()

            aml_obj = self.env['account.move.line'].with_context(check_move_validity=False)
            invoice_currency = False
            if self.bill_ids and all([x.currency_id == self.bill_ids[0].currency_id for x in self.bill_ids]):
                #if all the invoices selected share the same currency, record the paiement in that currency too
                invoice_currency = self.bill_ids[0].currency_id
            debit, credit, amount_currency, currency_id = aml_obj.with_context(date=self.payment_date).compute_amount_fields(amount, self.currency_id, self.company_id.currency_id, invoice_currency)
            
            if self.move_id:
                move = self.move_id
                move.write(self._get_move_vals())
            else:
                move = self.env['account.move'].create(self._get_move_vals())

            open('/opt/odoo16/logs/account_invoice.log','a+').write('\n')
            open('/opt/odoo16/logs/account_invoice.log','a+').write(str(amount_currency))
            #open('/opt/odoo16/logs/account_invoice.log','a+').write(str(self._get_move_vals()))


            # Write line corresponding to invoice payment
            # counterpart_aml_dict = self._get_shared_move_line_vals(debit, credit, amount_currency, move.id, False)
            # counterpart_aml_dict.update(self._get_counterpart_move_line_vals(self.bill_ids))
            # counterpart_aml_dict.update({'currency_id': currency_id})
            # counterpart_aml = aml_obj.create(counterpart_aml_dict)

            # 2021.09.27 - Update saldo credit ke AP/AR Agig di split per invoice 
