    # @api.multi
    def cancel_journal(self):
        self = self.with_context(payment=True)
        for rec in self:
            if rec.journal_created is True and rec.state == 'draft':
                for move in rec.move_line_ids.mapped('move_id'):
                    for line in move.line_ids:
                        line.write({'reconciled':False, 'full_reconcile_id':False})
                    # if rec.bill_ids:
                    #    move.line_ids.remove_move_reconcile()

                    move.button_cancel()
                    move.unlink()

                rec.journal_created = False





    # @api.multi
    def cancel_consol(self):
        open('/opt/odoo16/logs/test_sync_id_api.log', 'a+').write('\n' + "MASUK CANCEL CONCOL")
        for rec in self:
            rec.approve_rule_id = False
            for move in rec.move_line_ids.mapped('move_id'):
                if rec.invoice_ids:
                    move.line_ids.remove_move_reconcile()
                move.button_cancel()
                move.unlink()
            rec.state = 'draft'


    # @api.multi 
    def action_draft(self):
        self.function_consol(function="action_draft_consol")
        for record in self:
            if record.state == 'cancel':
                record.state = 'draft'

    # @api.multi 
    def action_draft_consol(self):
        for record in self:
            if record.state == 'cancel':
                record.state = 'draft'
    
    # @api.multi 
    def action_cancel_call(self):
        self.function_consol(function="action_cancel_call_consol")
        for record in self:
            if record.state == 'draft':
                record.state = 'cancel'
               

    # @api.multi 
    def action_cancel_call_consol(self):
        for record in self:
            if record.state == 'draft':
                record.state = 'cancel'
              

    # @api.multi
    def action_print(self):
        action = {}
        action['type'] = 'ir.actions.act_url'
        if self.payment_type == 'outbound':
            action['url'] = '/account/approval_payment_voucher?id=' + str(self.id)
        else:
            action['url'] = '/account/approval_receive_voucher?id=' + str(self.id)
        action['target'] = 'new'
        return action

    # @api.multi
    def action_print_approvalsheet(self):
        action = {}
        action['type'] = 'ir.actions.act_url'
        if self.payment_type == 'outbound':
            action['url'] = '/account/approval_pv_sheet?id=' + str(self.id)
        else:
            return
        return action


    # @api.multi 
    def action_show_billing(self):
        for record in self:
            if record.covering_id and record.state == 'draft' and record.type_receipt_selection == 'AR Receipt':
                if record.billing_type == 'bill':
                    # delete payment if exists
                    self.env.cr.execute("""
                        delete from account_payment_bill_rel 
                        where account_payment_id={payment_id}
                        """.format(payment_id=record.id))

                    # insert new billing from MHCL 
                    self.env.cr.execute("""
                        insert into account_payment_bill_rel (
                            account_payment_id, covering_id, sale_order_bill_id, payer_amount, payer_ending) 
                        select {payment_id} account_payment_id, a.account_coveringletter_id as covering_id, 
                            a.sale_order_bill_id, b.payer_balance as payer_amount, b.payer_balance as payer_ending 
                        from account_coveringletter_bill_rel a 
                        inner join sale_order_bill b on b.id = a.sale_order_bill_id 
                        where a.account_coveringletter_id = {letter_id}
                    """.format(
                        payment_id=record.id, 
                        letter_id=record.covering_id.id
                    ))


                if record.billing_type == 'cob':
                    # delete payment if exists
                    self.env.cr.execute("""
                        delete from account_payment_cob_rel 
                        where account_payment_id={payment_id}
                        """.format(payment_id=record.id))

                    # insert new billing from MHCL 
                    self.env.cr.execute("""
                        insert into account_payment_cob_rel (
                            account_payment_id, covering_id, sale_order_cob_id, payer_amount, payer_ending) 
                        select {payment_id} account_payment_id, a.account_coveringletter_id as covering_id,
                            a.sale_order_cob_id, b.payer_balance as payer_amount, b.payer_balance as payer_ending
                        from account_coveringletter_cob_rel a 
                        inner join sale_order_cob b on b.id = a.sale_order_cob_id 
                        where a.account_coveringletter_id = {letter_id}
                    """.format(
                        payment_id=record.id, 
                        letter_id=record.covering_id.id
                    ))

                if record.billing_type == 'admission':
                    # delete payment if exists
                    self.env.cr.execute("""
                        delete from account_payment_admission_rel 
                        where account_payment_id={payment_id}
                        """.format(payment_id=record.id))

                    # insert new billing from MHCL 
                    self.env.cr.execute("""
                        insert into account_payment_admission_rel (
                            account_payment_id, covering_id, sale_order_id, payer_amount, payer_ending) 
                        select {payment_id} account_payment_id, a.account_coveringletter_id as covering_id, 
                            a.sale_order_id, b.payer_balance as payer_amount, b.payer_balance as payer_ending
                        from account_coveringletter_admission_rel a 
                        inner join sale_order b on b.id = a.sale_order_id 
                        where a.account_coveringletter_id = {letter_id}
                    """.format(
                        payment_id=record.id, 
                        letter_id=record.covering_id.id
                    ))

                record.receipt_adjustment = 0 
                record.receipt_unadjustment = record.amount
            else:
                raise exceptions.ValidationError("Hanya receipt dengan status Draft dan Letter yang sudah dipilih yang dapat di settlement.")
                
    

    # @api.multi 
    def action_auto_settlement(self):
        for record in self:
            if record.amount > 0 and record.payment_type == 'inbound' and record.type_receipt_selection == 'AR Receipt':
                total_receipt = record.amount
                if record.billing_type == 'bill':
                    for bill in record.billing_sale_ids:
                        if total_receipt >= bill.payer_amount:
                            bill.payer_receipt = bill.payer_amount
                            bill.payer_ending = 0
                            total_receipt -= bill.payer_amount
                        else:
                            bill.payer_receipt = total_receipt
                            bill.payer_ending = bill.payer_amount - total_receipt
                            total_receipt = 0

                if record.billing_type == 'cob':
                    for bill in record.billing_cob_ids:
                        if total_receipt >= bill.payer_amount:
                            bill.payer_receipt = bill.payer_amount
                            bill.payer_ending = 0
                            total_receipt -= bill.payer_amount
                        else:
                            bill.payer_receipt = total_receipt
                            bill.payer_ending = bill.payer_amount - total_receipt
                            total_receipt = 0

                if record.billing_type == 'admission':
                    for bill in record.billing_ids:
                        if total_receipt >= bill.payer_amount:
                            bill.payer_receipt = bill.payer_amount
                            bill.payer_ending = 0
                            total_receipt -= bill.payer_amount
                        else:
                            bill.payer_receipt = total_receipt
                            bill.payer_ending = bill.payer_amount - total_receipt
                            total_receipt = 0
                record.receipt_unadjustment = total_receipt
                record.receipt_adjustment = record.amount - total_receipt
            else:
                raise exceptions.ValidationError("Nominal receipt harus diisi.")
               

    # @api.multi 
    def _compute_total_receipt_adjustment(self):
        for record in self:
            if record.payment_type == 'inbound' and record.type_receipt_selection == 'AR Receipt':
                adjustment_amount = 0
                unadjustment_amount = record.amount
                
                if record.billing_sale_ids:
                    for line in record.billing_sale_ids:
                        adjustment_amount += line.payer_receipt
                        unadjustment_amount -= line.payer_receipt

                if record.billing_cob_ids:
                    for line in record.billing_cob_ids:
                        adjustment_amount += line.payer_receipt
                        unadjustment_amount -= line.payer_receipt
                
                if record.billing_ids:
                    for line in record.billing_ids:
                        adjustment_amount += line.payer_receipt
                        unadjustment_amount -= line.payer_receipt

                record.receipt_adjustment = adjustment_amount
                record.receipt_unadjustment = unadjustment_amount
            

    @api.onchange('amount','type_receipt_selection','covering_id')
    def _change_receipt_amount(self):
        self._compute_total_receipt_adjustment()

    @api.depends('amount','type_receipt_selection','covering_id')
    def _depends_receipt_amount(self):
        self._compute_total_receipt_adjustment()
    
    
    @api.depends('billing_sale_ids.sale_order_bill_id', 'billing_sale_ids.payer_receipt')
    def _depend_amount(self):
        for record in self.billing_sale_ids:
            record.payer_amount = (record.sale_order_bill_id.payer_balance or 0)
            record.payer_ending = (record.payer_amount or 0) - (record.payer_receipt or 0)
        self._compute_total_receipt_adjustment()


    @api.depends('billing_cob_ids.sale_order_cob_id', 'billing_cob_ids.payer_receipt')
    def _depend_amount(self):
        for record in self.billing_cob_ids:
            record.payer_amount = (record.sale_order_cob_id.payer_balance or 0)
            record.payer_ending = (record.payer_amount or 0) - (record.payer_receipt or 0)
        self._compute_total_receipt_adjustment()

    @api.depends('billing_ids.sale_order_id', 'billing_ids.payer_receipt')
    def _depend_amount(self):
        for record in self.billing_ids:
            record.payer_amount = (record.sale_order_id.payer_balance or 0)
            record.payer_ending = (record.payer_amount or 0) - (record.payer_receipt or 0)
        self._compute_total_receipt_adjustment()

    # @api.multi
    def button_bills(self):
        return {
            'name': _('Paid Invoices'),
            'view_type': 'form',
            'view_mode': 'tree,form',
            'res_model': 'account.invoice',
            'view_id': False,
            'type': 'ir.actions.act_window',
            'domain': [('id', 'in', [x.id for x in self.bill_ids])],
        }



