class AccountReportStandardLedger(models.TransientModel):
    _inherit = 'account.report.standard.ledger'

    sync_type = sync.type
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date



    def action_view_lines(self):
        if self.company_id.financial_report_range_active:
            company_id = self.company_id.id
            from datetime import datetime, timedelta
            
            now = datetime.now()
            start_date = self.date_from
            end_date = self.date_to
            # start_date = now - timedelta(days=self.company_id.financial_report_range_start)
            # end_date = now - timedelta(days=self.company_id.financial_report_range_end)
            
            if not start_date or not end_date:
                raise UserError(_("Please set both start date and end date."))

            query = """
            WITH params AS (
                SELECT 
                    DATE '{start_date}' AS start_date,   -- ganti sesuai kebutuhan
                    DATE '{end_date}' AS end_date      -- ganti sesuai kebutuhan
            ),
            list_journals AS (
                SELECT unnest(ARRAY[
                    'Sales Revenue Bill'
                ]) AS journal_name
            ),
            calendar AS (
                SELECT generate_series(
                    p.start_date, 
                    p.end_date, 
                    interval '1 day'
                )::date AS dt
                FROM params p
            ),
            journal_summary AS (
                SELECT aj.name AS journal_name, am.date::date AS dt
                FROM account_move am
                INNER JOIN account_move_line aml ON aml.move_id = am.id 
                INNER JOIN account_journal aj ON aj.id = am.journal_id 
                JOIN params p ON TRUE
                WHERE am.company_id = {company_id}
                  AND am.state = 'posted'
                  AND am.date BETWEEN p.start_date AND p.end_date
                  AND aj.name IN (SELECT journal_name FROM list_journals)
                GROUP BY aj.name, am.date
            ),
            missing_dates AS (
                SELECT j.journal_name, c.dt AS missing_date
                FROM list_journals j
                CROSS JOIN calendar c
                LEFT JOIN journal_summary js 
                       ON js.journal_name = j.journal_name AND js.dt = c.dt
                WHERE js.dt IS NULL
            )
            SELECT 
                journal_name,
                COUNT(*) AS missing_count,
                string_agg(to_char(missing_date, 'YYYY-MM-DD'), ', ' ORDER BY missing_date) AS missing_dates
            FROM missing_dates
            GROUP BY journal_name
            ORDER BY journal_name;
      
            """.format(start_date=start_date,end_date=end_date, company_id=company_id)
            self.env.cr.execute(query)
            result = self.env.cr.dictfetchall()
            if result:
                missing_info = []
                for row in result:
                    missing_info.append("%s: %s" % (row['journal_name'], row['missing_dates']))
        
                # gabungkan jadi string
                missing_text = "\n".join(missing_info)

                raise exceptions.UserError(
                    "Cannot generate report because there are still missing entries for Sales Revenue Bill journals:\n%s" % missing_text
                )
                # raise exceptions.UserError("Cannot generate report because there are still missing entries for Sales Revenue Bill journals.")

            self.ensure_one()
            self._compute_data()
            return {
                'name': self.report_id.name,
                'view_type': 'form',
                'view_mode': 'tree,form',
                'views': [(self.env.ref('account_standard_report.view_aged_tree').id if self.ledger_type == 'aged' else False, 'tree'), (False, 'form')],
                'res_model': 'account.report.standard.ledger.line',
                'type': 'ir.actions.act_window',
                'domain': "[('report_id','=',%s),('line_type','not in',('5_super_total','4_total'))]" % (self.report_id.id),
                'context': {'search_default_%s' % self.ledger_type: 1},
                'target': 'current',
            }
        else:
            self.ensure_one()
            self._compute_data()
            return {
                'name': self.report_id.name,
                'view_type': 'form',
                'view_mode': 'tree,form',
                'views': [(self.env.ref('account_standard_report.view_aged_tree').id if self.ledger_type == 'aged' else False, 'tree'), (False, 'form')],
                'res_model': 'account.report.standard.ledger.line',
                'type': 'ir.actions.act_window',
                'domain': "[('report_id','=',%s),('line_type','not in',('5_super_total','4_total'))]" % (self.report_id.id),
                'context': {'search_default_%s' % self.ledger_type: 1},
                'target': 'current',
            }


    def print_pdf_report(self):
        if self.company_id.financial_report_range_active:
            company_id = self.company_id.id
            from datetime import datetime, timedelta
            
            now = datetime.now()
            start_date = self.date_from
            end_date = self.date_to
            # start_date = now - timedelta(days=self.company_id.financial_report_range_start)
            # end_date = now - timedelta(days=self.company_id.financial_report_range_end)
            
            if not start_date or not end_date:
                raise UserError(_("Please set both start date and end date."))
            
            query = """
            WITH params AS (
                SELECT 
                    DATE '{start_date}' AS start_date,   -- ganti sesuai kebutuhan
                    DATE '{end_date}' AS end_date      -- ganti sesuai kebutuhan
            ),
            list_journals AS (
                SELECT unnest(ARRAY[
                    'Sales Revenue Bill'
                ]) AS journal_name
            ),
            calendar AS (
                SELECT generate_series(
                    p.start_date, 
                    p.end_date, 
                    interval '1 day'
                )::date AS dt
                FROM params p
            ),
            journal_summary AS (
                SELECT aj.name AS journal_name, am.date::date AS dt
                FROM account_move am
                INNER JOIN account_move_line aml ON aml.move_id = am.id 
                INNER JOIN account_journal aj ON aj.id = am.journal_id 
                JOIN params p ON TRUE
                WHERE am.company_id = {company_id}
                  AND am.state = 'posted'
                  AND am.date BETWEEN p.start_date AND p.end_date
                  AND aj.name IN (SELECT journal_name FROM list_journals)
                GROUP BY aj.name, am.date
            ),
            missing_dates AS (
                SELECT j.journal_name, c.dt AS missing_date
                FROM list_journals j
                CROSS JOIN calendar c
                LEFT JOIN journal_summary js 
                       ON js.journal_name = j.journal_name AND js.dt = c.dt
                WHERE js.dt IS NULL
            )
            SELECT 
                journal_name,
                COUNT(*) AS missing_count,
                string_agg(to_char(missing_date, 'YYYY-MM-DD'), ', ' ORDER BY missing_date) AS missing_dates
            FROM missing_dates
            GROUP BY journal_name
            ORDER BY journal_name;
      
            """.format(start_date=start_date,end_date=end_date, company_id=company_id)
            self.env.cr.execute(query)
            result = self.env.cr.dictfetchall()
            if result:
                missing_info = []
                for row in result:
                    missing_info.append("%s: %s" % (row['journal_name'], row['missing_dates']))
        
                # gabungkan jadi string
                missing_text = "\n".join(missing_info)

                raise exceptions.UserError(
                    "Cannot generate report because there are still missing entries for Sales Revenue Bill journals:\n%s" % missing_text
                )
                # raise exceptions.UserError("Cannot generate report because there are still missing entries for Sales Revenue Bill journals.")

            self.ensure_one()
            self._compute_data()
            return self.env['report'].get_action(self, 'account_standard_report.report_account_standard_report')
        else:
            self.ensure_one()
            self._compute_data()
            return self.env['report'].get_action(self, 'account_standard_report.report_account_standard_report')



