    # @api.multi
    def generate(self):
        if datetime.now().date() <= datetime.strptime(str(self.date_start), '%Y-%m-%d').date():
            raise exceptions.ValidationError("Periode awal tidak boleh lebih dari tanggal " + datetime.now().date().strftime('%d-%m-%Y') + "!!")
        elif datetime.now().date() <= datetime.strptime(str(self.date_end), '%Y-%m-%d').date():
            raise exceptions.ValidationError("Periode akhir tidak boleh lebih dari tanggal " + datetime.now().date().strftime('%d-%m-%Y') + "!!")
        elif datetime.strptime(str(self.date_start), '%Y-%m-%d').date() > datetime.strptime(str(self.date_end), '%Y-%m-%d').date():
            raise exceptions.ValidationError("Periode awal tidak boleh lebih dari periode akhir!!")
        else:
            date_start = datetime.strptime(str(self.date_start), '%Y-%m-%d').date()
            date_end = datetime.strptime(str(self.date_end), '%Y-%m-%d').date()
            date_current = date_start
            date_str = ''
            record = self
            str_current = ''
            if date_start == date_end:
                open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + 'BARU' + str("MASUK SINI IF DATE SAMA"))
                # date_str = date_str + ',' + str_current.strftime('%Y-%m-%d')
                sync_type = record.company_id.sync_type
                str_current = date_current.strftime('%Y-%m-%d')
                # accrual & reversal
                if record.type_journal == 'accrual':
                    journal_id = record.env['account.journal'].search([('name', 'ilike', 'Sales Revenue Accrual'),('company_id', '=', record.company_id.id)])
                    if record.env['account.move'].search([('journal_id', 'in', journal_id.ids),('date', '=', str_current),('company_id', '=', record.company_id.id)])  and self.env.user.id != 1:
                        date_str = date_str + str_current + ": Already Have Journal \n"
                    else:
                        record.env['account.move']._create_periodic_journal_accrual(sync_type=sync_type, date=str_current)
                        record.env['account.move']._create_periodic_journal_accrual_reversal(sync_type=sync_type, date=str_current)
                # billing & cancel billing
                if record.type_journal == 'bill':
                    open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + 'BARU' + str("MASUK BILL"))
                    journal_id = record.env['account.journal'].search([('name', 'like', 'Sales Revenue Bill'),('company_id', '=', record.company_id.id)],limit=1)
                    open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + 'journal_id' + str(journal_id.id))
                    open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + 'str_current' + str(str_current))
                    open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + 'company_id' + str(record.company_id.id))
                    open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + 'user' + str(self.env.user.id))
                    if record.env['account.move'].search([('journal_id', '=', journal_id.id),('date', '=', str_current),('company_id', '=', record.company_id.id)])  and self.env.user.id != 1:
                        open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + 'BARU' + str("MASUK BILL 1"))
                        date_str = date_str + str_current + ": Already Have Journal \n"
                    else:
                        open('/opt/odoo16/logs/dudi.log', 'a+').write('\n' + 'BARU' + str("MASUK BILL 2"))
                        record.env['account.move']._create_periodic_journal_revenue_bill(sync_type=sync_type, date=str_current)
