    date_start = fields.Date(string="Date Start")
    date_end = fields.Date(string="Date End")
    partner_id = fields.Many2one("res.partner", string="Customer")
    type_report = fields.Selection([
        ('vendor_bill_prc', 'Vendor Bill Report (PRC)'), 
        ('vendor_bill', 'Vendor Bill Report'), 
        ('aging_detail', 'AP Aging Per Supplier'), 
        ('aging_invoice', 'AP Aging per Invoice')], 
        string='Type Report', required=True)
    format_print_id = fields.Selection([('pdf','PDF'),('xls','EXCEL')], string="Format", required=True, default='xls')

    # @api.multi
    def print_all(self):
        if self.type_report == 'aging_detail':
            action = {}
            action['type'] = 'ir.actions.act_url'
            action['url'] = '/accounting/aging_report_ap_detail?id=' + str(self.id)
            action['target'] = 'new'
            return action

        if self.type_report == 'aging_invoice':
            action = {}
            action['type'] = 'ir.actions.act_url'
            action['url'] = '/accounting/aging_report_ap_invoice?id=' + str(self.id)
            action['target'] = 'new'
            return action

        if self.type_report == 'vendor_bill':
            action = {}
            action['type'] = 'ir.actions.act_url'
            action['url'] = '/accounting/vendor_bill_report_noprc?id=' + str(self.id)
            action['target'] = 'new'
            return action

        if self.type_report == 'vendor_bill_prc':
            action = {}
            action['type'] = 'ir.actions.act_url'
            action['url'] = '/accounting/vendor_bill_report?id=' + str(self.id)
            action['target'] = 'new'
            return action




